const _appInviteUrl = 'https://betshuva.com/betshuva-app/invite-v2.html';
const _sharedContactPrefix = 'betshuva://contact/';
const _maxVideoDuration = Duration(seconds: 30);

Future<bool> _videoWithinDurationLimit(
    BuildContext context, XFile video) async {
  VideoPlayerController? controller;
  try {
    controller = kIsWeb
        ? VideoPlayerController.networkUrl(Uri.parse(video.path))
        : VideoPlayerController.file(File(video.path));
    await controller.initialize().timeout(const Duration(seconds: 12));
    if (controller.value.duration <= _maxVideoDuration) return true;
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('ניתן לשלוח סרטון באורך של עד 30 שניות',
            textDirection: TextDirection.rtl),
      ));
    }
    return false;
  } catch (_) {
    // The server performs the authoritative duration and container check.
    return true;
  } finally {
    await controller?.dispose();
  }
}

String _sharedContactText(Map<String, String> contact) =>
    '$_sharedContactPrefix${base64Url.encode(utf8.encode(jsonEncode(contact)))}';

Map<String, dynamic>? _sharedContactFromText(String text) {
  if (!text.startsWith(_sharedContactPrefix)) return null;
  try {
    final encoded = text.substring(_sharedContactPrefix.length).trim();
    final value =
        jsonDecode(utf8.decode(base64Url.decode(base64Url.normalize(encoded))));
    return value is Map<String, dynamic> ? value : null;
  } catch (_) {
    return null;
  }
}

class _MessageInputHistory {
  final List<String> _entries = [];
  int _index = 0;
  String _draft = '';

  void record(String text) {
    if (text.isEmpty) return;
    if (_entries.isEmpty || _entries.last != text) _entries.add(text);
    _index = _entries.length;
    _draft = '';
  }

  void navigate(TextEditingController controller, {required bool older}) {
    if (_entries.isEmpty) return;
    if (older) {
      if (_index == _entries.length) _draft = controller.text;
      if (_index > 0) _index--;
    } else {
      if (_index < _entries.length) _index++;
    }
    final text = _index == _entries.length ? _draft : _entries[_index];
    controller.value = TextEditingValue(
      text: text,
      selection: TextSelection.collapsed(offset: text.length),
    );
  }
}

KeyEventResult _handleMessageInputNavigation(TextEditingController controller,
    _MessageInputHistory history, KeyEvent event,
    {VoidCallback? onWebEnter}) {
  final key = event.logicalKey;
  final isEnter =
      key == LogicalKeyboardKey.enter || key == LogicalKeyboardKey.numpadEnter;
  if (kIsWeb &&
      event is KeyDownEvent &&
      isEnter &&
      !HardwareKeyboard.instance.isShiftPressed &&
      !HardwareKeyboard.instance.isControlPressed &&
      !HardwareKeyboard.instance.isAltPressed &&
      !HardwareKeyboard.instance.isMetaPressed) {
    if (controller.text.trim().isNotEmpty) onWebEnter?.call();
    return KeyEventResult.handled;
  }
  if (event is KeyUpEvent ||
      HardwareKeyboard.instance.isShiftPressed ||
      HardwareKeyboard.instance.isControlPressed ||
      HardwareKeyboard.instance.isAltPressed ||
      HardwareKeyboard.instance.isMetaPressed) {
    return KeyEventResult.ignored;
  }

  if (key == LogicalKeyboardKey.arrowUp ||
      key == LogicalKeyboardKey.arrowDown) {
    history.navigate(controller, older: key == LogicalKeyboardKey.arrowUp);
    return KeyEventResult.handled;
  }

  final isLeft = key == LogicalKeyboardKey.arrowLeft;
  final isRight = key == LogicalKeyboardKey.arrowRight;
  if (!isLeft && !isRight) return KeyEventResult.ignored;

  final selection = controller.selection;
  if (!selection.isValid) return KeyEventResult.ignored;

  // In an RTL run, moving visually left advances through the logical string,
  // while moving visually right goes back. Enforce that mapping explicitly;
  // Flutter Web can otherwise apply the surrounding Directionality twice.
  final current = selection.isCollapsed
      ? selection.extentOffset
      : (isLeft ? selection.end : selection.start);
  final next = (current + (isLeft ? 1 : -1)).clamp(0, controller.text.length);
  controller.selection = TextSelection.collapsed(offset: next);
  return KeyEventResult.handled;
}

Future<Map<String, String>?> _manualSharedContact(BuildContext context) async {
  final name = TextEditingController();
  final phone = TextEditingController();
  final email = TextEditingController();
  return showDialog<Map<String, String>>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: const Text('שיתוף איש קשר'),
      content: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(
            controller: name,
            decoration: const InputDecoration(labelText: 'שם')),
        TextField(
            controller: phone,
            keyboardType: TextInputType.phone,
            decoration: const InputDecoration(labelText: 'טלפון')),
        TextField(
            controller: email,
            keyboardType: TextInputType.emailAddress,
            decoration: const InputDecoration(labelText: 'אימייל')),
      ]),
      actions: [
        TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('ביטול')),
        ElevatedButton(
          onPressed: () {
            if (name.text.trim().isEmpty ||
                (phone.text.trim().isEmpty && email.text.trim().isEmpty)) {
              return;
            }
            Navigator.pop(dialogContext, {
              'name': name.text.trim(),
              'phone': phone.text.trim(),
              'email': email.text.trim(),
            });
          },
          child: const Text('שתף'),
        ),
      ],
    ),
  );
}

Future<Map<String, String>?> _pickPhoneContact(BuildContext context) async {
  if (kIsWeb) return _manualSharedContact(context);
  final granted = await FlutterContacts.requestPermission(readonly: true);
  if (!granted) return null;
  final contacts = await FlutterContacts.getContacts(withProperties: true);
  if (!context.mounted) return null;
  var query = '';
  final selected = await showModalBottomSheet<Contact>(
    context: context,
    isScrollControlled: true,
    builder: (sheetContext) => StatefulBuilder(
      builder: (context, setSheetState) {
        final normalizedQuery = query.toLowerCase();
        final visible = contacts.where((contact) {
          if (normalizedQuery.isEmpty) return true;
          final values = <String>[
            contact.displayName,
            ...contact.phones.map((phone) => phone.number),
            ...contact.emails.map((email) => email.address),
          ];
          return values
              .any((value) => value.toLowerCase().contains(normalizedQuery));
        }).toList();
        return SafeArea(
          child: SizedBox(
            height: MediaQuery.sizeOf(context).height * .72,
            child: Column(children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
                child: TextField(
                  autofocus: true,
                  textAlign: TextAlign.right,
                  textDirection: TextDirection.rtl,
                  decoration: const InputDecoration(
                    hintText: 'חיפוש איש קשר...',
                    hintTextDirection: TextDirection.rtl,
                    prefixIcon: Icon(Icons.search),
                  ),
                  onChanged: (value) =>
                      setSheetState(() => query = value.trim()),
                ),
              ),
              Expanded(
                child: visible.isEmpty
                    ? const Center(child: Text('לא נמצאו אנשי קשר'))
                    : ListView.builder(
                        itemCount: visible.length,
                        itemBuilder: (_, index) {
                          final contact = visible[index];
                          return ListTile(
                            leading: const CircleAvatar(
                                child: Icon(Icons.person_outline)),
                            title: Text(contact.displayName,
                                textAlign: TextAlign.right,
                                textDirection: TextDirection.rtl),
                            subtitle: Text(
                              contact.phones.isNotEmpty
                                  ? contact.phones.first.number
                                  : contact.emails.isNotEmpty
                                      ? contact.emails.first.address
                                      : '',
                              textAlign: TextAlign.right,
                            ),
                            onTap: () => Navigator.pop(sheetContext, contact),
                          );
                        },
                      ),
              ),
            ]),
          ),
        );
      },
    ),
  );
  if (selected == null) return null;
  return {
    'name': selected.displayName,
    'phone': selected.phones.isNotEmpty ? selected.phones.first.number : '',
    'email': selected.emails.isNotEmpty ? selected.emails.first.address : '',
  };
}

Future<Map<String, String>?> _pickAppFriend(
    BuildContext context, String token) async {
  try {
    final response = await http.get(
      Uri.parse('$kApi/users'),
      headers: {'Authorization': 'Bearer $token'},
    ).timeout(const Duration(seconds: 10));
    if (!context.mounted) return null;
    if (response.statusCode != 200) throw Exception();
    final friends = (jsonDecode(response.body) as List)
        .cast<Map<String, dynamic>>()
        .where((friend) => friend['id']?.toString() != kScanBotId)
        .toList();
    var query = '';
    return await showDialog<Map<String, String>>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          final visible = friends
              .where((friend) => (friend['name']?.toString() ?? '')
                  .toLowerCase()
                  .contains(query.toLowerCase()))
              .toList();
          return AlertDialog(
            title: const Text('בחירת חבר לשיתוף'),
            content: SizedBox(
              width: 430,
              height: 430,
              child: Column(children: [
                TextField(
                  autofocus: true,
                  decoration: const InputDecoration(
                    hintText: 'חיפוש חבר...',
                    prefixIcon: Icon(Icons.search),
                  ),
                  onChanged: (value) =>
                      setDialogState(() => query = value.trim()),
                ),
                const SizedBox(height: 10),
                Expanded(
                  child: visible.isEmpty
                      ? const Center(child: Text('לא נמצאו חברים'))
                      : ListView.builder(
                          itemCount: visible.length,
                          itemBuilder: (_, index) {
                            final friend = visible[index];
                            final name = friend['name']?.toString() ?? 'חבר';
                            return ListTile(
                              leading: UserAvatar(
                                picUrl: friend['profile_pic_url']?.toString(),
                                name: name,
                                radius: 21,
                              ),
                              title: Text(name),
                              subtitle: const Text(
                                  'יישלח שם, תמונה וקישור לצ׳אט בלבד'),
                              onTap: () => Navigator.pop(dialogContext, {
                                'name': name,
                                'appUserId': friend['id'].toString(),
                                if (friend['profile_pic_url'] != null)
                                  'profilePicUrl':
                                      friend['profile_pic_url'].toString(),
                              }),
                            );
                          },
                        ),
                ),
              ]),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('ביטול'),
              ),
            ],
          );
        },
      ),
    );
  } catch (_) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('לא ניתן לטעון כעת את רשימת החברים')),
      );
    }
    return null;
  }
}

Future<Map<String, String>?> _pickSharedContact(
    BuildContext context, String token) async {
  final source = await showModalBottomSheet<String>(
    context: context,
    builder: (sheetContext) => SafeArea(
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        ListTile(
          leading: const Icon(Icons.people_outline, color: kPrimary),
          title: const Text('מהחברים שלי'),
          subtitle: const Text('שיתוף שם, תמונה וקישור לצ׳אט'),
          onTap: () => Navigator.pop(sheetContext, 'app'),
        ),
        ListTile(
          leading: const Icon(Icons.contact_phone_outlined),
          title: Text(kIsWeb ? 'איש קשר חדש' : 'איש קשר מהטלפון'),
          onTap: () => Navigator.pop(sheetContext, 'phone'),
        ),
      ]),
    ),
  );
  if (source == null || !context.mounted) return null;
  return source == 'app'
      ? _pickAppFriend(context, token)
      : _pickPhoneContact(context);
}

Future<Map<String, String>?> _confirmMyContactShare(
    BuildContext context, String token,
    {bool isGroup = false}) async {
  try {
    final response = await http.get(
      Uri.parse('$kApi/profile/share-card'),
      headers: {'Authorization': 'Bearer $token'},
    );
    if (!context.mounted) return null;
    if (response.statusCode != 200) {
      var message = 'לא ניתן לשתף את פרטי הקשר';
      try {
        message = (jsonDecode(response.body) as Map<String, dynamic>)['error']
                ?.toString() ??
            message;
      } catch (_) {}
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text(message)));
      return null;
    }
    final data = jsonDecode(response.body) as Map<String, dynamic>;
    final contact = <String, String>{
      'name': data['name']?.toString() ?? '',
      'phone': data['phone']?.toString() ?? '',
      'email': data['email']?.toString() ?? '',
      'city': data['city']?.toString() ?? '',
      'street': data['street']?.toString() ?? '',
      'houseNumber': data['house_number']?.toString() ?? '',
      'apartment': data['apartment']?.toString() ?? '',
    };
    String formattedAddress() => [
          contact['street']!,
          if (contact['houseNumber']!.isNotEmpty) contact['houseNumber']!,
          if (contact['apartment']!.isNotEmpty) 'דירה ${contact['apartment']}',
        ].where((part) => part.isNotEmpty).join(' ');
    var shareName = contact['name']!.isNotEmpty;
    var sharePhone = false;
    var shareEmail = false;
    var shareCity = false;
    var shareAddress = false;
    final selection = await showDialog<Map<String, bool>>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          final hasSelection = shareName ||
              sharePhone ||
              shareEmail ||
              shareCity ||
              shareAddress;
          return AlertDialog(
            title: const Text('שיתוף הפרטים שלי'),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (isGroup)
                  const Padding(
                    padding: EdgeInsets.only(bottom: 12),
                    child: Text(
                      'שימו לב: כל חברי הקבוצה יוכלו לראות ולשמור את הפרטים.',
                      style: TextStyle(color: Colors.orange),
                    ),
                  ),
                const Text('בחרו אילו פרטים לשתף:'),
                CheckboxListTile(
                  value: shareName,
                  contentPadding: EdgeInsets.zero,
                  title: Text('שם: ${contact['name']}'),
                  onChanged: contact['name']!.isEmpty
                      ? null
                      : (value) =>
                          setDialogState(() => shareName = value ?? false),
                ),
                CheckboxListTile(
                  value: sharePhone,
                  contentPadding: EdgeInsets.zero,
                  title: Text(contact['phone']!.isEmpty
                      ? 'טלפון: לא הוגדר'
                      : 'טלפון: ${contact['phone']}'),
                  onChanged: (value) =>
                      setDialogState(() => sharePhone = value ?? false),
                ),
                CheckboxListTile(
                  value: shareEmail,
                  contentPadding: EdgeInsets.zero,
                  title: Text(contact['email']!.isEmpty
                      ? 'אימייל: לא הוגדר'
                      : 'אימייל: ${contact['email']}'),
                  onChanged: (value) =>
                      setDialogState(() => shareEmail = value ?? false),
                ),
                CheckboxListTile(
                  value: shareCity,
                  contentPadding: EdgeInsets.zero,
                  title: Text(contact['city']!.isEmpty
                      ? 'עיר מגורים: לא הוגדרה'
                      : 'עיר מגורים: ${contact['city']}'),
                  onChanged: (value) =>
                      setDialogState(() => shareCity = value ?? false),
                ),
                CheckboxListTile(
                  value: shareAddress,
                  contentPadding: EdgeInsets.zero,
                  title: Text(formattedAddress().isEmpty
                      ? 'כתובת: לא הוגדרה'
                      : 'כתובת: ${formattedAddress()}'),
                  onChanged: (value) =>
                      setDialogState(() => shareAddress = value ?? false),
                ),
                if (!hasSelection)
                  const Text(
                    'יש לבחור לפחות פרט אחד',
                    style: TextStyle(color: Colors.red),
                  ),
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('ביטול'),
              ),
              ElevatedButton.icon(
                onPressed: !hasSelection
                    ? null
                    : () => Navigator.pop(dialogContext, <String, bool>{
                          'name': shareName,
                          'phone': sharePhone,
                          'email': shareEmail,
                          'city': shareCity,
                          'address': shareAddress,
                        }),
                icon: const Icon(Icons.send_outlined),
                label: const Text('שתף'),
              ),
            ],
          );
        },
      ),
    );
    if (selection == null || !context.mounted) return null;

    final missingPhone =
        selection['phone'] == true && contact['phone']!.isEmpty;
    final missingEmail =
        selection['email'] == true && contact['email']!.isEmpty;
    final missingCity = selection['city'] == true && contact['city']!.isEmpty;
    final missingAddress =
        selection['address'] == true && formattedAddress().isEmpty;
    if (missingPhone || missingEmail || missingCity || missingAddress) {
      final phoneCtrl = TextEditingController();
      final emailCtrl = TextEditingController();
      final cityCtrl = TextEditingController();
      final streetCtrl = TextEditingController();
      final houseCtrl = TextEditingController();
      final apartmentCtrl = TextEditingController();
      var saveForLater = false;
      var locating = false;
      String? locationError;
      final completed = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (context, setDialogState) {
            final valid = (!missingPhone || phoneCtrl.text.trim().isNotEmpty) &&
                (!missingEmail || emailCtrl.text.trim().isNotEmpty) &&
                (!missingCity || cityCtrl.text.trim().isNotEmpty) &&
                (!missingAddress || streetCtrl.text.trim().isNotEmpty);
            return AlertDialog(
              title: const Text('השלמת פרטים לשיתוף'),
              content: SingleChildScrollView(
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  const Text('הפרטים הבאים חסרים. הם ישותפו רק בהודעה זו.'),
                  if (missingCity || missingAddress) ...[
                    const SizedBox(height: 10),
                    OutlinedButton.icon(
                      onPressed: locating
                          ? null
                          : () async {
                              setDialogState(() {
                                locating = true;
                                locationError = null;
                              });
                              try {
                                var permission =
                                    await Geolocator.checkPermission();
                                if (permission == LocationPermission.denied) {
                                  permission =
                                      await Geolocator.requestPermission();
                                }
                                if (permission == LocationPermission.denied ||
                                    permission ==
                                        LocationPermission.deniedForever) {
                                  throw Exception('לא ניתנה הרשאת מיקום');
                                }
                                final position =
                                    await Geolocator.getCurrentPosition(
                                  locationSettings: const LocationSettings(
                                    accuracy: LocationAccuracy.high,
                                    timeLimit: Duration(seconds: 12),
                                  ),
                                );
                                final response = await http.put(
                                  Uri.parse('$kApi/location/address'),
                                  headers: {
                                    'Authorization': 'Bearer $token',
                                    'Content-Type': 'application/json',
                                  },
                                  body: jsonEncode({
                                    'latitude': position.latitude,
                                    'longitude': position.longitude,
                                  }),
                                );
                                if (response.statusCode != 200) {
                                  throw Exception('לא ניתן לזהות את הכתובת');
                                }
                                final payload = jsonDecode(response.body)
                                    as Map<String, dynamic>;
                                cityCtrl.text =
                                    payload['city']?.toString() ?? '';
                                streetCtrl.text =
                                    payload['street']?.toString() ?? '';
                                houseCtrl.text =
                                    payload['house_number']?.toString() ?? '';
                              } catch (error) {
                                locationError = error
                                    .toString()
                                    .replaceFirst('Exception: ', '');
                              } finally {
                                if (dialogContext.mounted) {
                                  setDialogState(() => locating = false);
                                }
                              }
                            },
                      icon: locating
                          ? const SizedBox(
                              width: 18,
                              height: 18,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            )
                          : const Icon(Icons.my_location),
                      label: Text(locating
                          ? 'מאתר את הכתובת...'
                          : 'שיתוף המיקום שלי ומילוי אוטומטי'),
                    ),
                    if (locationError != null)
                      Padding(
                        padding: const EdgeInsets.only(top: 6),
                        child: Text(locationError!,
                            style: const TextStyle(color: Colors.red)),
                      ),
                  ],
                  if (missingPhone)
                    TextField(
                      controller: phoneCtrl,
                      keyboardType: TextInputType.phone,
                      decoration: const InputDecoration(labelText: 'טלפון'),
                      onChanged: (_) => setDialogState(() {}),
                    ),
                  if (missingEmail)
                    TextField(
                      controller: emailCtrl,
                      keyboardType: TextInputType.emailAddress,
                      decoration: const InputDecoration(labelText: 'אימייל'),
                      onChanged: (_) => setDialogState(() {}),
                    ),
                  if (missingCity)
                    _LocationAutocompleteField(
                      controller: cityCtrl,
                      label: 'עיר מגורים',
                      onChanged: (_) => setDialogState(() {}),
                    ),
                  if (missingAddress) ...[
                    _StreetAutocompleteField(
                      controller: streetCtrl,
                      cityController: cityCtrl,
                      onChanged: (_) => setDialogState(() {}),
                    ),
                    Row(children: [
                      Expanded(
                          child: TextField(
                        controller: houseCtrl,
                        decoration:
                            const InputDecoration(labelText: 'מספר בית'),
                      )),
                      const SizedBox(width: 12),
                      Expanded(
                          child: TextField(
                        controller: apartmentCtrl,
                        decoration: const InputDecoration(labelText: 'דירה'),
                      )),
                    ]),
                  ],
                  CheckboxListTile(
                    value: saveForLater,
                    contentPadding: EdgeInsets.zero,
                    title: const Text('לשמור את הפרטים בפרופיל לשימוש עתידי?'),
                    subtitle: const Text('לא יישמר דבר ללא סימון אפשרות זו'),
                    onChanged: (value) =>
                        setDialogState(() => saveForLater = value ?? false),
                  ),
                ]),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(dialogContext, false),
                  child: const Text('ביטול'),
                ),
                ElevatedButton(
                  onPressed:
                      !valid ? null : () => Navigator.pop(dialogContext, true),
                  child: const Text('המשך לשיתוף'),
                ),
              ],
            );
          },
        ),
      );
      if (completed != true) return null;
      if (missingPhone) contact['phone'] = phoneCtrl.text.trim();
      if (missingEmail) contact['email'] = emailCtrl.text.trim();
      if (missingCity) contact['city'] = cityCtrl.text.trim();
      if (missingAddress) {
        contact['street'] = streetCtrl.text.trim();
        contact['houseNumber'] = houseCtrl.text.trim();
        contact['apartment'] = apartmentCtrl.text.trim();
      }
      if (saveForLater) {
        final saved = await http.patch(
          Uri.parse('$kApi/profile/share-details'),
          headers: {
            'Authorization': 'Bearer $token',
            'Content-Type': 'application/json',
          },
          body: jsonEncode({
            if (missingPhone) 'phone': contact['phone'],
            if (missingEmail) 'email': contact['email'],
            if (missingCity) 'city': contact['city'],
            if (missingAddress) 'street': contact['street'],
            if (missingAddress) 'house_number': contact['houseNumber'],
            if (missingAddress) 'apartment': contact['apartment'],
          }),
        );
        if (saved.statusCode != 200 && context.mounted) {
          ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
            content: Text('הפרטים ישותפו כעת, אך לא נשמרו בפרופיל'),
          ));
        }
      }
    }

    return <String, String>{
      if (selection['name'] == true) 'name': contact['name']!,
      if (selection['phone'] == true) 'phone': contact['phone']!,
      if (selection['email'] == true) 'email': contact['email']!,
      if (selection['city'] == true) 'city': contact['city']!,
      if (selection['address'] == true) 'address': formattedAddress(),
    };
  } catch (_) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('לא ניתן לטעון את פרטי הקשר')),
      );
    }
    return null;
  }
}

Future<Map<String, String>?> _pickGroupSharedContact(BuildContext context,
    String token, List<Map<String, dynamic>> members) async {
  final source = await showModalBottomSheet<String>(
    context: context,
    builder: (sheetContext) => SafeArea(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
      ListTile(
          leading: const Icon(Icons.people_outline),
          title: const Text('מהחברים שלי'),
          onTap: () => Navigator.pop(sheetContext, 'app')),
      ListTile(
          leading: const Icon(Icons.contact_phone_outlined),
          title: const Text('איש קשר מהטלפון'),
          onTap: () => Navigator.pop(sheetContext, 'phone')),
      ListTile(
          leading: const Icon(Icons.groups_outlined),
          title: const Text('חבר מהקבוצה'),
          onTap: () => Navigator.pop(sheetContext, 'group')),
    ])),
  );
  if (source == null || !context.mounted) return null;
  if (source == 'app') return _pickAppFriend(context, token);
  if (source == 'phone') return _pickPhoneContact(context);
  final member = await showModalBottomSheet<Map<String, dynamic>>(
    context: context,
    builder: (sheetContext) => SafeArea(
        child: ListView.builder(
      itemCount: members.length,
      itemBuilder: (_, index) => ListTile(
        leading: const CircleAvatar(child: Icon(Icons.person_outline)),
        title: Text(members[index]['name']?.toString() ?? 'חבר בקבוצה'),
        subtitle: Text(members[index]['phone']?.toString() ??
            members[index]['email']?.toString() ??
            ''),
        onTap: () => Navigator.pop(sheetContext, members[index]),
      ),
    )),
  );
  if (member == null) return null;
  return {
    'name': member['name']?.toString() ?? 'חבר בקבוצה',
    'phone': member['phone']?.toString() ?? '',
    'email': member['email']?.toString() ?? '',
  };
}

String _normalizeIsraeliMobile(String value) {
  var digits = value.replaceAll(RegExp(r'\D'), '');
  if (digits.startsWith('00')) digits = digits.substring(2);
  if (digits.startsWith('972')) digits = '0${digits.substring(3)}';
  return digits;
}

bool _isValidIsraeliMobile(String value) =>
    RegExp(r'^05\d{8}$').hasMatch(_normalizeIsraeliMobile(value));

String _whatsAppPhoneNumber(String rawPhone) {
  var digits = rawPhone.replaceAll(RegExp(r'\D'), '');
  if (digits.startsWith('00')) digits = digits.substring(2);
  if (digits.startsWith('0')) digits = '972${digits.substring(1)}';
  return digits;
}

Uri _whatsAppUri(String rawPhone, String message) {
  final phone = _whatsAppPhoneNumber(rawPhone);
  return Uri.parse(
    'https://wa.me/$phone?text=${Uri.encodeComponent(message)}',
  );
}

Future<bool> _openWhatsApp(String phone, String message) {
  return launchUrl(
    _whatsAppUri(phone, message),
    mode: LaunchMode.externalApplication,
  );
}

