class _OfficeDocumentScreenState extends State<_OfficeDocumentScreen> {
  late final Future<Map<String, dynamic>> _preview =
      _loadOfficePreview(widget.fileUrl, widget.token);
  int _sheetIndex = 0;

  Widget _excelView(Map<String, dynamic> data) {
    final sheets = (data['sheets'] as List? ?? const []).cast<Map>();
    if (sheets.isEmpty) {
      return const Center(child: Text('הקובץ אינו מכיל גיליונות'));
    }
    final sheet = sheets[_sheetIndex.clamp(0, sheets.length - 1)];
    final rows = (sheet['rows'] as List? ?? const []).cast<List>();
    return Column(children: [
      if (sheets.length > 1)
        Padding(
          padding: const EdgeInsets.all(10),
          child: DropdownButtonFormField<int>(
            initialValue: _sheetIndex,
            decoration:
                const InputDecoration(labelText: 'גיליון', isDense: true),
            items: [
              for (var i = 0; i < sheets.length; i++)
                DropdownMenuItem(
                    value: i,
                    child: Text(
                        sheets[i]['name']?.toString() ?? 'גיליון ${i + 1}'))
            ],
            onChanged: (value) => setState(() => _sheetIndex = value ?? 0),
          ),
        ),
      Expanded(
          child: rows.isEmpty
              ? const Center(child: Text('הגיליון ריק'))
              : Scrollbar(
                  child: SingleChildScrollView(
                  child: SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    child: DataTable(
                      headingRowColor:
                          WidgetStatePropertyAll(Color(0xFFEAF4EB)),
                      columns: [
                        for (var i = 0; i < rows.first.length; i++)
                          DataColumn(label: Text(_excelColumnName(i)))
                      ],
                      rows: [
                        for (var rowIndex = 0;
                            rowIndex < rows.length;
                            rowIndex++)
                          DataRow(cells: [
                            for (final value in rows[rowIndex])
                              DataCell(ConstrainedBox(
                                constraints:
                                    const BoxConstraints(maxWidth: 240),
                                child: SelectableText(value?.toString() ?? ''),
                              ))
                          ])
                      ],
                    ),
                  ),
                ))),
    ]);
  }

  String _excelColumnName(int index) {
    var value = index + 1;
    var label = '';
    while (value > 0) {
      value--;
      label = String.fromCharCode(65 + value % 26) + label;
      value ~/= 26;
    }
    return label;
  }

  @override
  Widget build(BuildContext context) => Scaffold(
        appBar: AppBar(
            automaticallyImplyLeading: !widget.embedded,
            leading: widget.embedded
                ? IconButton(
                    tooltip: 'סגירת המסמך',
                    onPressed: widget.onClose,
                    icon: const Icon(Icons.close),
                  )
                : null,
            title: Text(widget.fileName,
                maxLines: 1, overflow: TextOverflow.ellipsis),
            actions: [
              IconButton(
                  tooltip: 'הורדה',
                  icon: const Icon(Icons.download_outlined),
                  onPressed: () => _downloadChatFile(
                      context, widget.fileUrl, widget.fileName)),
            ]),
        body: FutureBuilder<Map<String, dynamic>>(
          future: _preview,
          builder: (context, snapshot) {
            if (snapshot.connectionState != ConnectionState.done) {
              return const Center(child: CircularProgressIndicator());
            }
            if (snapshot.hasError || snapshot.data == null) {
              return Center(
                  child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Column(mainAxisSize: MainAxisSize.min, children: [
                        const Icon(Icons.file_present_outlined,
                            size: 52, color: kSubtext),
                        const SizedBox(height: 12),
                        Text(
                            snapshot.error
                                .toString()
                                .replaceFirst('Exception: ', ''),
                            textAlign: TextAlign.center),
                        const SizedBox(height: 12),
                        OutlinedButton.icon(
                            icon: const Icon(Icons.download_outlined),
                            label: const Text('הורדת הקובץ'),
                            onPressed: () => _downloadChatFile(
                                context, widget.fileUrl, widget.fileName)),
                      ])));
            }
            final data = snapshot.data!;
            final content = data['kind'] == 'word'
                ? SingleChildScrollView(
                    padding: const EdgeInsets.all(20),
                    child: Center(
                        child: ConstrainedBox(
                      constraints: const BoxConstraints(maxWidth: 850),
                      child: SelectableText(
                          data['text']?.toString().isNotEmpty == true
                              ? data['text'].toString()
                              : 'המסמך ריק',
                          textDirection: TextDirection.rtl,
                          style: const TextStyle(fontSize: 16, height: 1.65)),
                    )))
                : _excelView(data);
            return Column(children: [
              if (data['truncated'] == true)
                Container(
                    width: double.infinity,
                    color: const Color(0xFFFFF3CD),
                    padding: const EdgeInsets.all(8),
                    child: const Text('מוצגת תצוגה חלקית של מסמך גדול',
                        textAlign: TextAlign.center)),
              Expanded(child: content),
            ]);
          },
        ),
      );
}

Future<void> _showReportDialog({
  required BuildContext context,
  required String token,
  required String targetType,
  required String targetId,
  required String targetLabel,
}) async {
  if (targetId.isEmpty || targetId.startsWith('temp_')) return;
  const reasons = <String, String>{
    'spam': 'ספאם או פרסום מטעה',
    'harassment': 'הטרדה או בריונות',
    'inappropriate': 'תוכן פוגעני או לא הולם',
    'fraud': 'התחזות, הונאה או תרמית',
    'illegal': 'פעילות או תוכן בלתי חוקיים',
    'other': 'סיבה אחרת',
  };
  var selectedReason = 'inappropriate';
  final detailsController = TextEditingController();
  final submit = await showDialog<bool>(
    context: context,
    builder: (dialogContext) => StatefulBuilder(
      builder: (_, setDialogState) => AlertDialog(
        title: Text('דיווח על $targetLabel'),
        content: SizedBox(
          width: 440,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            DropdownButtonFormField<String>(
              initialValue: selectedReason,
              decoration: const InputDecoration(
                labelText: 'סיבת הדיווח',
                border: OutlineInputBorder(),
              ),
              items: reasons.entries
                  .map((entry) => DropdownMenuItem(
                      value: entry.key, child: Text(entry.value)))
                  .toList(),
              onChanged: (value) {
                if (value != null) setDialogState(() => selectedReason = value);
              },
            ),
            const SizedBox(height: 12),
            TextField(
              controller: detailsController,
              maxLength: 1000,
              maxLines: 4,
              textDirection: TextDirection.rtl,
              decoration: const InputDecoration(
                labelText: 'פרטים נוספים (לא חובה)',
                border: OutlineInputBorder(),
              ),
            ),
            const Text(
              'הדיווח יועבר למנהלי בתשובה לבדיקה. המשתמש שעליו דווח לא יקבל את פרטיך.',
              style: TextStyle(fontSize: 12, color: kSubtext),
              textDirection: TextDirection.rtl,
            ),
          ]),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('ביטול')),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(dialogContext, true),
            icon: const Icon(Icons.flag_outlined, color: Colors.white),
            label: const Text('שליחת דיווח',
                style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    ),
  );
  final details = detailsController.text.trim();
  detailsController.dispose();
  if (submit != true || !context.mounted) return;
  try {
    final response = await http.post(
      Uri.parse('$kApi/reports'),
      headers: {
        'Authorization': 'Bearer $token',
        'Content-Type': 'application/json',
      },
      body: jsonEncode({
        'targetType': targetType,
        'targetId': targetId,
        'reason': selectedReason,
        if (details.isNotEmpty) 'details': details,
      }),
    );
    if (!context.mounted) return;
    if (response.statusCode == 201) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('הדיווח התקבל ויועבר לבדיקה'),
        backgroundColor: kPrimary,
      ));
    } else {
      var message = 'לא ניתן היה לשלוח את הדיווח';
      try {
        message = (jsonDecode(response.body)['error'] as String?) ?? message;
      } catch (_) {}
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text(message)));
    }
  } catch (_) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('שגיאת תקשורת בשליחת הדיווח')),
      );
    }
  }
}

bool _hasImageExtension(String? value) {
  if (value == null || value.isEmpty) return false;
  final v = value.toLowerCase();
  return v.endsWith('.jpg') ||
      v.endsWith('.jpeg') ||
      v.endsWith('.png') ||
      v.endsWith('.gif') ||
      v.endsWith('.webp');
}

bool _hasVideoExtension(String? value) {
  if (value == null || value.isEmpty) return false;
  final v = value.toLowerCase();
  return v.endsWith('.mp4') || v.endsWith('.webm') || v.endsWith('.mov');
}

String? _normalizeIncomingFileType(String? fileType,
    {String? fileUrl, String? fileName}) {
  final t = (fileType ?? '').trim().toLowerCase();
  // Web voice recordings use the WebM container too. An explicit audio type
  // must win over the ambiguous .webm extension, which can also contain video.
  if (t == 'audio' || t.startsWith('audio/')) return 'audio';
  // Extension check takes priority — DB may store 'text' even for image messages
  if (_hasImageExtension(fileUrl) || _hasImageExtension(fileName)) {
    return 'image';
  }
  if (_hasVideoExtension(fileUrl) || _hasVideoExtension(fileName)) {
    return 'video';
  }
  if (t.isEmpty) return null;
  if (t == 'image' || t.startsWith('image/')) return 'image';
  return t;
}

