void _showImageBatchSummary(
    BuildContext context, List<_FileUploadResult> results) {
  final approved = results
      .where((result) =>
          result.outcome == _FileUploadOutcome.approved ||
          result.outcome == _FileUploadOutcome.scanBot)
      .length;
  final rejected = results
      .where((result) => result.outcome == _FileUploadOutcome.rejected)
      .length;
  final pending = results
      .where((result) => result.outcome == _FileUploadOutcome.pending)
      .length;
  final failed = results
      .where((result) => result.outcome == _FileUploadOutcome.failed)
      .length;
  final parts = <String>[
    if (approved > 0) '$approved אושרו',
    if (rejected > 0) '$rejected נחסמו',
    if (pending > 0) '$pending ממתינות לסריקה',
    if (failed > 0) '$failed נכשלו',
  ];
  final hasProblem = rejected > 0 || pending > 0 || failed > 0;
  String? firstError;
  for (final result in results) {
    if (result.outcome == _FileUploadOutcome.failed && result.error != null) {
      firstError = result.error;
      break;
    }
  }
  ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(
      content: Text(
          'העלאת התמונות הסתיימה: ${parts.join(' · ')}'
          '${firstError == null ? '' : '\n$firstError'}',
          textDirection: TextDirection.rtl),
      backgroundColor: hasProblem ? Colors.orange.shade800 : kPrimary,
      duration: const Duration(seconds: 5),
    ));
}

String _absoluteMediaUrl(String url) =>
    Uri.parse(url).hasScheme ? url : Uri.parse(kServer).resolve(url).toString();

final Map<String, Future<Uint8List?>> _activeMediaLoads = {};

Future<Uint8List?> _loadPersistentMedia(String url) {
  final absoluteUrl = _absoluteMediaUrl(url);
  final existing = _activeMediaLoads[absoluteUrl];
  if (existing != null) return existing;
  final future = () async {
    final cached = await readMediaCache(absoluteUrl);
    if (cached != null && cached.isNotEmpty) return cached;
    final response = await http
        .get(Uri.parse(absoluteUrl))
        .timeout(const Duration(seconds: 30));
    if (response.statusCode < 200 || response.statusCode >= 300) return null;
    final bytes = response.bodyBytes;
    if (bytes.isEmpty) return null;
    await writeMediaCache(absoluteUrl, bytes);
    return bytes;
  }();
  _activeMediaLoads[absoluteUrl] = future;
  void removeActiveLoad() {
    if (identical(_activeMediaLoads[absoluteUrl], future)) {
      _activeMediaLoads.remove(absoluteUrl);
    }
  }

  future.then((_) => removeActiveLoad(), onError: (_) => removeActiveLoad());
  return future;
}

class _PersistentMediaImage extends StatefulWidget {
  final String url;
  final double? width;
  final double? height;
  final BoxFit fit;
  final WidgetBuilder? loadingBuilder;
  final WidgetBuilder? errorBuilder;

  const _PersistentMediaImage({
    required this.url,
    this.width,
    this.height,
    this.fit = BoxFit.cover,
    this.loadingBuilder,
    this.errorBuilder,
  });

  @override
  State<_PersistentMediaImage> createState() => _PersistentMediaImageState();
}

class _PersistentMediaImageState extends State<_PersistentMediaImage> {
  late Future<Uint8List?> _bytes;
  Timer? _retryTimer;
  int _retryAttempt = 0;

  @override
  void initState() {
    super.initState();
    _bytes = _loadPersistentMedia(widget.url);
  }

  @override
  void didUpdateWidget(covariant _PersistentMediaImage oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.url != widget.url) {
      _retryTimer?.cancel();
      _retryAttempt = 0;
      _bytes = _loadPersistentMedia(widget.url);
    }
  }

  @override
  void dispose() {
    _retryTimer?.cancel();
    super.dispose();
  }

  void _scheduleRetry() {
    if (_retryAttempt >= 4 || _retryTimer?.isActive == true) return;
    final delay = Duration(seconds: 1 << _retryAttempt);
    _retryAttempt++;
    _retryTimer = Timer(delay, () {
      if (!mounted) return;
      setState(() => _bytes = _loadPersistentMedia(widget.url));
    });
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Uint8List?>(
      future: _bytes,
      builder: (context, snapshot) {
        final bytes = snapshot.data;
        if (bytes != null && bytes.isNotEmpty) {
          _retryTimer?.cancel();
          return Image.memory(
            bytes,
            width: widget.width,
            height: widget.height,
            fit: widget.fit,
            gaplessPlayback: true,
            errorBuilder: (_, __, ___) =>
                widget.errorBuilder?.call(context) ?? const SizedBox.shrink(),
          );
        }
        if (snapshot.connectionState != ConnectionState.done) {
          return widget.loadingBuilder?.call(context) ??
              SizedBox(width: widget.width, height: widget.height);
        }
        _scheduleRetry();
        return widget.errorBuilder?.call(context) ?? const SizedBox.shrink();
      },
    );
  }
}

class _BlockedImagePreview extends StatefulWidget {
  final String url;
  final String token;
  final DateTime expiresAt;

  const _BlockedImagePreview(
      {required this.url, required this.token, required this.expiresAt});

  @override
  State<_BlockedImagePreview> createState() => _BlockedImagePreviewState();
}

class _BlockedImagePreviewState extends State<_BlockedImagePreview> {
  Uint8List? _bytes;
  bool _loading = true;
  Timer? _expiryTimer;

  int get _secondsLeft => math.max(
      0, widget.expiresAt.difference(DateTime.now().toUtc()).inSeconds);

  @override
  void initState() {
    super.initState();
    _load();
    _expiryTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted) return;
      if (_secondsLeft <= 0) {
        _expiryTimer?.cancel();
        setState(() => _bytes = null);
      } else {
        setState(() {});
      }
    });
  }

  Future<void> _load() async {
    try {
      final response = await http.get(Uri.parse(_absoluteMediaUrl(widget.url)),
          headers: {'Authorization': 'Bearer ${widget.token}'}).timeout(
        const Duration(seconds: 30),
      );
      if (!mounted) return;
      setState(() {
        _bytes = response.statusCode == 200 && response.bodyBytes.isNotEmpty
            ? response.bodyBytes
            : null;
        _loading = false;
      });
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  void dispose() {
    _expiryTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_secondsLeft <= 0) {
      return const Text('תצוגת התמונה הסתיימה והקובץ נמחק',
          textAlign: TextAlign.right,
          textDirection: TextDirection.rtl,
          style: TextStyle(fontSize: 11, color: Colors.red));
    }
    final minutes = _secondsLeft ~/ 60;
    final seconds = (_secondsLeft % 60).toString().padLeft(2, '0');
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Container(
        width: double.infinity,
        height: 180,
        clipBehavior: Clip.antiAlias,
        decoration: BoxDecoration(
          color: const Color(0xFFF2F4F7),
          borderRadius: BorderRadius.circular(10),
        ),
        child: _loading
            ? const Center(child: CircularProgressIndicator(strokeWidth: 2))
            : _bytes == null
                ? const Center(child: Icon(Icons.broken_image_outlined))
                : Image.memory(_bytes!,
                    fit: BoxFit.contain, gaplessPlayback: true),
      ),
      const SizedBox(height: 5),
      Text('מוצגת רק לך ותימחק בעוד $minutes:$seconds',
          textAlign: TextAlign.right,
          textDirection: TextDirection.rtl,
          style: const TextStyle(fontSize: 10, color: Colors.red)),
    ]);
  }
}

Future<void> _persistRecentImageUrls(
    Iterable<Map<String, dynamic>> records) async {
  final urls = <String>{};
  for (final record in records.toList().reversed) {
    final fileUrl = record['fileUrl'] as String? ??
        record['file_url'] as String? ??
        record['image_url'] as String?;
    final fileType = _normalizeIncomingFileType(
      record['fileType'] as String? ?? record['type'] as String?,
      fileUrl: fileUrl,
      fileName: record['fileName'] as String? ?? record['file_name'] as String?,
    );
    if (fileUrl == null ||
        (fileType != 'image' && record['image_url'] == null)) {
      continue;
    }
    urls.add(fileUrl);
    if (urls.length >= 20) break;
  }
  for (final url in urls) {
    try {
      await _loadPersistentMedia(url);
    } catch (_) {}
  }
}

String _groupMessagesCacheKey(Object? userId, Object? groupId) =>
    'cache_group_msgs_${userId ?? ''}_${groupId ?? ''}';

Future<void> _clearGroupMessagesCache(Object? userId, Object? groupId) async {
  if (userId == null || groupId == null) return;
  final prefs = await SharedPreferences.getInstance();
  await prefs.remove(_groupMessagesCacheKey(userId, groupId));
}

Future<void> _forwardChatMessage(BuildContext context, String token,
        io.Socket? socket, Map<String, dynamic> message) =>
    _forwardChatMessages(context, token, socket, [message]);

Future<void> _requestImageReclassification(
    BuildContext context, String token, Map<String, dynamic> image) async {
  final fileUrl = image['fileUrl']?.toString();
  if (fileUrl == null || fileUrl.isEmpty) return;
  ScaffoldMessenger.of(context).showSnackBar(
    const SnackBar(content: Text('הסריקה הנוספת התחילה…')),
  );
  try {
    final response = await http.post(
      Uri.parse('$kApi/media/reclassify'),
      headers: {
        'Authorization': 'Bearer $token',
        'Content-Type': 'application/json',
      },
      body: jsonEncode({'fileUrl': fileUrl}),
    );
    final body = jsonDecode(response.body) as Map<String, dynamic>;
    if (!context.mounted) return;
    if (response.statusCode == 200) {
      image['classification'] = body['classification'];
      if (body['status'] == 'rejected') {
        image['status'] = 'rejected_scan';
        image['scanReason'] = body['reason'];
        image['blockedPreviewUrl'] = body['blockedPreviewUrl'];
        image['previewExpiresAt'] = body['previewExpiresAt'];
      }
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(body['status'] == 'rejected'
            ? 'התמונה נחסמה בסריקה הנוספת והוסרה מהמקומות שבהם הופיעה'
            : 'הסריקה הנוספת הושלמה והתמונה אושרה.'),
      ));
    } else {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(body['error']?.toString() ?? 'הסריקה הנוספת נכשלה'),
      ));
    }
  } catch (_) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('שגיאת תקשורת בסריקה הנוספת')),
      );
    }
  }
}

Future<void> _forwardChatMessages(BuildContext context, String token,
    io.Socket? socket, List<Map<String, dynamic>> messages) async {
  if (messages.isEmpty) return;
  if (messages.any((message) {
    final status = message['status'] as String?;
    return status == 'pending_scan' ||
        (status == 'rejected_scan' && message['forwardAllowed'] != true);
  })) {
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text(
            'לא ניתן להעביר קובץ שנכשל בבדיקת הבטיחות או שעדיין נמצא בסריקה')));
    return;
  }
  try {
    Future<http.Response> loadTargets(String path) async {
      try {
        return await http.get(Uri.parse('$kApi/$path'), headers: {
          'Authorization': 'Bearer $token',
        }).timeout(const Duration(seconds: 15));
      } catch (_) {
        return http.Response('', 599);
      }
    }

    final responses = await Future.wait([
      loadTargets('users'),
      loadTargets('groups'),
      loadTargets('users/directory'),
    ]);
    if (!context.mounted) return;
    List<Map<String, dynamic>> responseList(http.Response response) {
      if (response.statusCode != 200) return <Map<String, dynamic>>[];
      final decoded = jsonDecode(response.body);
      if (decoded is! List) return <Map<String, dynamic>>[];
      return decoded.whereType<Map>().map(Map<String, dynamic>.from).toList();
    }

    final usersById = <String, Map<String, dynamic>>{};
    for (final user in responseList(responses[0])) {
      usersById[user['id'].toString()] = user;
    }
    // The directory is a safe fallback when the conversation list endpoint is
    // temporarily unavailable. Only already-saved contacts are added.
    for (final user in responseList(responses[2])) {
      if (user['saved'] == true) {
        usersById.putIfAbsent(user['id'].toString(), () => user);
      }
    }
    final users = usersById.values.toList();
    final groups = responseList(responses[1]);
    final targetLoadFailed =
        responses.every((response) => response.statusCode != 200);
    final targets = await showModalBottomSheet<List<Map<String, dynamic>>>(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (sheetContext) {
        final selected = <String, Map<String, dynamic>>{};
        return StatefulBuilder(builder: (context, setSheetState) {
          Widget targetTile(Map<String, dynamic> item, String kind) {
            final key = '$kind:${item['id']}';
            final checked = selected.containsKey(key);
            return CheckboxListTile(
              value: checked,
              secondary: UserAvatar(
                  picUrl: item['profile_pic_url'] as String?,
                  name: item['name'] as String? ?? ''),
              title: Text(item['name'] as String? ??
                  (kind == 'user' ? 'משתמש' : 'קבוצה')),
              onChanged: (_) => setSheetState(() {
                if (checked) {
                  selected.remove(key);
                } else {
                  selected[key] = {
                    'kind': kind,
                    'id': item['id'],
                    'name': item['name'],
                  };
                }
              }),
            );
          }

          return SafeArea(
            child: SizedBox(
              height: MediaQuery.sizeOf(sheetContext).height * .78,
              child: Column(children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(18, 18, 18, 8),
                  child: Column(children: [
                    const Text('העבר אל',
                        style: TextStyle(
                            fontSize: 18, fontWeight: FontWeight.bold)),
                    const SizedBox(height: 4),
                    Text('${messages.length} פריטים • ${selected.length} יעדים',
                        style: const TextStyle(color: kSubtext)),
                  ]),
                ),
                Expanded(
                  child: users.isEmpty && groups.isEmpty
                      ? Center(
                          child: Padding(
                            padding: const EdgeInsets.all(24),
                            child: Text(
                              targetLoadFailed
                                  ? 'לא ניתן לטעון כרגע את המשתתפים והקבוצות. נסו שוב.'
                                  : 'לא נמצאו משתתפים או קבוצות שניתן להעביר אליהם.',
                              textAlign: TextAlign.center,
                              style: const TextStyle(color: kSubtext),
                            ),
                          ),
                        )
                      : ListView(children: [
                          if (users.isNotEmpty)
                            const _SectionHeader(title: 'משתמשים'),
                          ...users.map((user) => targetTile(user, 'user')),
                          if (groups.isNotEmpty)
                            const _SectionHeader(title: 'קבוצות'),
                          ...groups.map((group) => targetTile(group, 'group')),
                        ]),
                ),
                Padding(
                  padding: const EdgeInsets.all(12),
                  child: SizedBox(
                    width: double.infinity,
                    child: FilledButton.icon(
                      onPressed: selected.isEmpty
                          ? null
                          : () => Navigator.pop(
                              sheetContext, selected.values.toList()),
                      icon: const Icon(Icons.forward),
                      label: Text(selected.isEmpty
                          ? 'בחרו יעד אחד לפחות'
                          : 'העבר ל־${selected.length} יעדים'),
                    ),
                  ),
                ),
              ]),
            ),
          );
        });
      },
    );
    if (targets == null || targets.isEmpty || !context.mounted) return;
    var sentCount = 0;
    final forwardingErrors = <String>[];
    String responseError(http.Response response) {
      try {
        final body = jsonDecode(response.body);
        if (body is Map && body['error'] != null) {
          return body['error'].toString();
        }
      } catch (_) {}
      return 'ההעברה נחסמה על ידי השרת';
    }

    for (final target in targets) {
      for (final message in messages) {
        var fileUrl = message['fileUrl'] as String?;
        var fileName = message['fileName'] as String?;
        var fileType = message['fileType'] as String?;
        final localPath = message['localPath'] as String?;
        final localBytes = message['localBytes'] as Uint8List?;
        // A server-hosted, already approved file is forwarded by reference. The
        // server reuses its immutable moderation result and applies only the new
        // destination filter. Local files still require a normal upload/scan.
        if (localPath != null || localBytes != null) {
          final request =
              http.MultipartRequest('POST', Uri.parse('$kApi/upload'))
                ..headers['Authorization'] = 'Bearer $token'
                ..fields[target['kind'] == 'group' ? 'groupId' : 'toUserId'] =
                    target['id'].toString();
          if (localBytes != null) {
            request.files.add(http.MultipartFile.fromBytes('file', localBytes,
                filename: fileName ?? 'screenshot.png',
                contentType: MediaType('image', 'png')));
          } else {
            request.files.add(await http.MultipartFile.fromPath(
                'file', localPath!,
                filename: fileName,
                contentType: _mimeFromFileName(fileName ?? localPath)));
          }
          final upload =
              await request.send().timeout(const Duration(seconds: 60));
          final uploadBody = await upload.stream.bytesToString();
          if (upload.statusCode != 200) {
            var uploadError = 'העלאת התמונה נכשלה';
            try {
              uploadError =
                  (jsonDecode(uploadBody) as Map)['error']?.toString() ??
                      uploadError;
            } catch (_) {}
            if (context.mounted) {
              ScaffoldMessenger.of(context)
                  .showSnackBar(SnackBar(content: Text(uploadError)));
            }
            return;
          }
          final uploaded = jsonDecode(uploadBody) as Map<String, dynamic>;
          if (uploaded['status'] == 'rejected') {
            final reason = uploaded['reason']?.toString() ??
                'התמונה נחסמה לפי הגדרות הסינון';
            if (context.mounted) {
              ScaffoldMessenger.of(context)
                  .showSnackBar(SnackBar(content: Text(reason)));
            }
            return;
          }
          if (uploaded['status'] == 'pending') {
            if (context.mounted) {
              ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
                  content: Text('התמונה נשלחה לסריקה ותועבר לאחר אישור')));
            }
            return;
          }
          fileUrl = uploaded['url'] as String?;
          fileName = uploaded['fileName'] as String? ?? fileName;
          fileType = uploaded['fileType'] as String? ?? 'image';
        }
        final payload = <String, dynamic>{
          'text': fileUrl == null ? (message['text'] as String? ?? '') : null,
          if (fileUrl != null) 'fileUrl': fileUrl,
          if (fileUrl != null) 'fileName': fileName,
          if (fileUrl != null) 'fileType': fileType,
        };
        var sent = false;
        if (target['kind'] == 'user') {
          final response = await http.post(Uri.parse('$kApi/messages'),
              headers: {
                'Authorization': 'Bearer $token',
                'Content-Type': 'application/json'
              },
              body: jsonEncode({...payload, 'toUserId': target['id']}));
          sent = response.statusCode == 200;
          if (!sent) forwardingErrors.add(responseError(response));
        } else {
          final response = await http.post(
            Uri.parse('$kApi/groups/${target['id']}/messages'),
            headers: {
              'Authorization': 'Bearer $token',
              'Content-Type': 'application/json',
            },
            body: jsonEncode(payload),
          );
          sent = response.statusCode == 200;
          if (!sent) forwardingErrors.add(responseError(response));
        }
        if (sent) sentCount++;
      }
    }
    if (context.mounted) {
      final totalDeliveries = messages.length * targets.length;
      final allSent = sentCount == totalDeliveries;
      final uniqueErrors = forwardingErrors.toSet().join(' • ');
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(forwardingErrors.isNotEmpty
            ? (sentCount == 0
                ? uniqueErrors
                : '$uniqueErrors (הושלמו $sentCount מתוך $totalDeliveries שליחות)')
            : allSent
                ? (messages.length == 1 && targets.length == 1
                    ? 'ההודעה הועברה'
                    : '${messages.length} פריטים הועברו ל־${targets.length} יעדים')
                : 'הושלמו $sentCount מתוך $totalDeliveries שליחות'),
      ));
    }
  } catch (error) {
    debugPrint('Forward message failed: $error');
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('שגיאת תקשורת בהעברת ההודעה')));
    }
  }
}

