                        textCapitalization: TextCapitalization.words,
                        decoration: const InputDecoration(
                          labelText: 'שם מלא',
                          helperText: 'חובה בהרשמה חדשה בלבד',
                          prefixIcon: Icon(Icons.person_outline),
                        ),
                      ),
                      const SizedBox(height: 14),
                      _BirthDateField(
                        value: _birthDate,
                        onChanged: (value) =>
                            setState(() => _birthDate = value),
