                    ClipRRect(
                      borderRadius: BorderRadius.circular(22),
                      child: Image.asset(
                        'icon_source.png',
                        width: 88,
                        height: 88,
                        fit: BoxFit.cover,
                      ),
                    ),
                    const SizedBox(height: 20),
                    const Text('בתשובה',
                        style: TextStyle(
                            fontSize: 34,
                            fontWeight: FontWeight.bold,
                            color: kPrimary)),
                    const SizedBox(height: 4),
                    _israelFlag(),
                    const SizedBox(height: 6),
                    Text(_isLogin ? 'כניסה לחשבון' : 'יצירת חשבון חדש',
                        style: const TextStyle(fontSize: 15, color: kSubtext)),
                    const SizedBox(height: 32),
                    // Toggle
                    Container(
                      decoration: BoxDecoration(
                          color: kBorder,
                          borderRadius: BorderRadius.circular(10)),
                      child: Row(children: [
                        _TabBtn(
                            label: 'כניסה',
                            active: _isLogin,
                            onTap: () => setState(() {
                                  _isLogin = true;
                                  _choosingVerification = false;
                                  _error = null;
                                })),
                        _TabBtn(
                            label: 'הרשמה',
                            active: !_isLogin,
                            onTap: () => setState(() {
                                  _isLogin = false;
                                  _choosingVerification = false;
                                  _error = null;
                                })),
                      ]),
                    ),
                    const SizedBox(height: 24),
                    if (!_isLogin)
                      _RegistrationProgress(
                          current: _choosingVerification ? 2 : 1),
                    if (!_isLogin) ...[
                      TextField(
                        controller: _nameCtrl,
                        textDirection: TextDirection.rtl,
                        decoration: const InputDecoration(
                            labelText: 'שם מלא',
                            prefixIcon: Icon(Icons.person_outline)),
                      ),
                      const SizedBox(height: 14),
                      _BirthDateField(
                        value: _birthDate,
                        onChanged: (value) =>
                            setState(() => _birthDate = value),
                      ),
                      const SizedBox(height: 14),
                      DropdownButtonFormField<String>(
                        initialValue: _gender,
                        decoration: const InputDecoration(
                          labelText: 'מגדר',
                          prefixIcon: Icon(Icons.wc_outlined),
                        ),
                        items: const [
                          DropdownMenuItem(value: 'male', child: Text('זכר')),
                          DropdownMenuItem(
                              value: 'female', child: Text('נקבה')),
                        ],
                        onChanged: (value) => setState(() => _gender = value),
                      ),
                      const SizedBox(height: 14),
                    ],
                    if (!_isLogin) ...[
                      TextField(
                        controller: _phoneCtrl,
                        keyboardType: TextInputType.phone,
                        textDirection: TextDirection.ltr,
                        decoration: const InputDecoration(
                          labelText: 'מספר טלפון',
                          hintText: '05X-XXX-XXXX',
                          prefixIcon: Icon(Icons.phone_android),
                        ),
                      ),
                      const SizedBox(height: 14),
                    ],
                    TextField(
                      controller: _emailCtrl,
                      keyboardType: TextInputType.emailAddress,
                      textDirection: TextDirection.ltr,
                      decoration: const InputDecoration(
                          labelText: 'כתובת אימייל',
                          prefixIcon: Icon(Icons.email_outlined)),
                    ),
                    const SizedBox(height: 14),
                    TextField(
                      controller: _passCtrl,
                      obscureText: true,
                      textDirection: TextDirection.ltr,
                      decoration: const InputDecoration(
                          labelText: 'סיסמה',
                          prefixIcon: Icon(Icons.lock_outline)),
                    ),
                    if (!_isLogin && _choosingVerification) ...[
                      const SizedBox(height: 18),
                      const Align(
                        alignment: Alignment.centerRight,
                        child: Text('הפרטים תקינים — איך תרצה לאמת?',
                            style: TextStyle(
                                fontSize: 13, fontWeight: FontWeight.w600)),
                      ),
                      const SizedBox(height: 8),
                      Container(
                        decoration: BoxDecoration(
                            color: kBorder,
                            borderRadius: BorderRadius.circular(10)),
                        child: Row(children: [
                          _TabBtn(
                            label: 'באימייל',
                            active: _verificationMethod == 'email',
                            onTap: () =>
                                setState(() => _verificationMethod = 'email'),
                          ),
                          _TabBtn(
                            label: 'בטלפון',
                            active: _verificationMethod == 'phone',
                            onTap: () =>
                                setState(() => _verificationMethod = 'phone'),
                          ),
                        ]),
                      ),
                    ],
                    if (!_isLogin) ...[
                      _RegistrationFilterSelector(
                        filter: _registrationFilter,
                        confirmed: _filterConfirmed,
                        onChanged: (value) => setState(() {
                          _registrationFilter = value;
                          _filterConfirmed = false;
                        }),
                        onConfirmed: (value) =>
                            setState(() => _filterConfirmed = value),
                      ),
                      const _BetaNotice(),
                      const SizedBox(height: 6),
                      CheckboxListTile(
                        contentPadding: EdgeInsets.zero,
                        controlAffinity: ListTileControlAffinity.leading,
                        value: _ageConfirmed,
                        onChanged: (value) =>
                            setState(() => _ageConfirmed = value == true),
                        title: const Text('אני בן/בת 13 ומעלה',
                            style: TextStyle(fontSize: 13)),
                      ),
                      _TermsAgreementTile(
                        value: _acceptedTerms,
                        onChanged: (value) =>
                            setState(() => _acceptedTerms = value == true),
                      ),
                    ],
                    if (_isLogin) ...[
                      Align(
                        alignment: Alignment.centerLeft,
                        child: TextButton(
                          onPressed: () => Navigator.push(
                            context,
                            MaterialPageRoute(
                                builder: (_) => const ForgotPasswordScreen()),
                          ),
                          child: const Text('שכחתי סיסמה',
                              style: TextStyle(color: kSubtext, fontSize: 13)),
                        ),
                      ),
                    ] else
                      const SizedBox(height: 12),
                    if (_error != null)
                      Container(
                        width: double.infinity,
                        padding: const EdgeInsets.all(10),
