class GoogleDriveBackupOfferScreen extends StatefulWidget {
  final String token;
  const GoogleDriveBackupOfferScreen({super.key, required this.token});

  @override
  State<GoogleDriveBackupOfferScreen> createState() =>
      _GoogleDriveBackupOfferScreenState();
}

class _GoogleDriveBackupOfferScreenState
    extends State<GoogleDriveBackupOfferScreen> {
  bool _loading = false;
  bool _statusLoading = true;
  bool _connected = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    _loadStatus();
  }

  Future<void> _loadStatus() async {
    try {
      final headers = {'Authorization': 'Bearer ${widget.token}'};
      final responses = await Future.wait([
        http.get(Uri.parse('$kApi/backup/google/status'), headers: headers),
        http.get(Uri.parse('$kApi/backup'), headers: headers),
      ]);
      if (!mounted) return;
      if (responses.any((response) => response.statusCode != 200)) {
        throw Exception('status failed');
      }
      final drive = jsonDecode(responses[0].body) as Map<String, dynamic>;
      final backup = jsonDecode(responses[1].body) as Map<String, dynamic>;
      final settings = backup['settings'] as Map<String, dynamic>? ?? const {};
      final connected = drive['connected'] == true;
      final enabled = settings['enabled'] == true;
      if (connected && enabled) {
        await _continue();
        return;
      }
      if (mounted) {
        setState(() {
          _connected = connected;
          _statusLoading = false;
        });
      }
    } catch (_) {
      if (mounted) setState(() => _statusLoading = false);
    }
  }

  Future<void> _continue() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('token', widget.token);
    if (!mounted) return;
    Navigator.pushReplacement(context,
        MaterialPageRoute(builder: (_) => MainShell(token: widget.token)));
  }

  Future<void> _enableBackup() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      if (_connected) {
        final response = await http.post(Uri.parse('$kApi/backup/automatic'),
            headers: {
              'Authorization': 'Bearer ${widget.token}',
              'Content-Type': 'application/json'
            },
            body: jsonEncode({'enabled': true}));
        if (response.statusCode != 200) {
          final body = jsonDecode(response.body) as Map<String, dynamic>;
          throw Exception(body['error'] ?? 'הפעלת הגיבוי נכשלה');
        }
        await _continue();
        return;
      }
      final response = await http.get(
          Uri.parse('$kApi/backup/google/connect?autoEnable=true'),
          headers: {'Authorization': 'Bearer ${widget.token}'});
      final body = jsonDecode(response.body) as Map<String, dynamic>;
      if (response.statusCode != 200) {
        throw Exception(body['error'] ?? 'חיבור Google Drive אינו זמין');
      }
      final opened = await launchUrl(
          Uri.parse(body['authorizationUrl'] as String),
          mode: LaunchMode.externalApplication);
      if (!opened) throw Exception('לא ניתן לפתוח את מסך האישור של Google');
    } catch (error) {
      if (mounted) {
        setState(() {
          _error = error.toString().replaceFirst('Exception: ', '');
          _loading = false;
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
        backgroundColor: kBg,
        body: SafeArea(
          child: Center(
            child: _statusLoading
                ? const CircularProgressIndicator()
                : ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 460),
                    child: Padding(
                      padding: const EdgeInsets.all(28),
                      child: Column(mainAxisSize: MainAxisSize.min, children: [
                        const Icon(Icons.cloud_sync_outlined,
                            size: 72, color: kPrimary),
                        const SizedBox(height: 18),
                        const Text('גיבוי מוצפן ב־Google Drive',
                            textAlign: TextAlign.center,
                            style: TextStyle(
                                fontSize: 24, fontWeight: FontWeight.bold)),
                        const SizedBox(height: 12),
                        Text(
                          _connected
                              ? 'Google Drive כבר מחובר. אפשר להפעיל עכשיו גיבוי אוטומטי מוצפן.'
                              : 'באישורך נחבר תיקייה פרטית ומוסתרת של בתשובה ב־Google Drive ונפעיל גיבוי אוטומטי מוצפן.',
                          textAlign: TextAlign.center,
                        ),
                        const SizedBox(height: 8),
                        const Text('ניתן לנתק או לכבות בכל עת בהגדרות.',
                            style: TextStyle(color: kSubtext)),
                        if (_error != null) ...[
                          const SizedBox(height: 12),
                          Text(_error!,
                              style: const TextStyle(color: Colors.red)),
                        ],
                        const SizedBox(height: 22),
                        SizedBox(
                          width: double.infinity,
                          child: ElevatedButton.icon(
                            onPressed: _loading ? null : _enableBackup,
                            icon: _loading
                                ? const SizedBox(
                                    width: 18,
                                    height: 18,
                                    child: CircularProgressIndicator(
                                        strokeWidth: 2))
                                : const Icon(Icons.cloud_done_outlined),
                            label: const Text('אישור והפעלת גיבוי'),
                          ),
                        ),
                        TextButton(
                            onPressed: _loading ? null : _continue,
                            child: const Text('לא עכשיו')),
                      ]),
                    ),
                  ),
          ),
        ),
      );
}

class GooglePhoneSetupScreen extends StatefulWidget {
  final String token;
  final bool requireVerification;
  const GooglePhoneSetupScreen(
      {super.key, required this.token, this.requireVerification = true});
  @override
  State<GooglePhoneSetupScreen> createState() => _GooglePhoneSetupScreenState();
}

class _GooglePhoneSetupScreenState extends State<GooglePhoneSetupScreen> {
  final _phoneCtrl = TextEditingController();
  final _otpCtrl = TextEditingController();
  bool _sentOtp = false;
  bool _loading = false;
  String? _error;

  bool get _supportsAutomaticSms =>
      !kIsWeb && defaultTargetPlatform == TargetPlatform.android;

  Future<String?> _startAutomaticSmsReading() async {
    if (!_supportsAutomaticSms) return null;
    final signatureResult = await SmartAuth.instance.getAppSignature();
    if (!signatureResult.hasData) return null;
    unawaited(_readAndVerifySmsCode());
    return signatureResult.requireData;
  }

  Future<void> _readAndVerifySmsCode() async {
    final result = await SmartAuth.instance.getSmsWithRetrieverApi();
    if (!mounted || !result.hasData) return;
    final code = result.requireData.code;
    if (code == null || !RegExp(r'^\d{6}$').hasMatch(code)) return;
    _otpCtrl.text = code;
    setState(() => _sentOtp = true);
    await _verify();
  }

  @override
  void dispose() {
    if (_supportsAutomaticSms) {
      unawaited(SmartAuth.instance.removeSmsRetrieverApiListener());
    }
    _phoneCtrl.dispose();
    _otpCtrl.dispose();
    super.dispose();
  }

  Future<void> _sendOtp() async {
    final phone = _normalizeIsraeliMobile(_phoneCtrl.text);
    if (!_isValidIsraeliMobile(phone)) {
      setState(() => _error = 'נא להזין מספר טלפון תקין');
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    if (!widget.requireVerification) {
      try {
        final res = await http
            .post(
              Uri.parse('$kApi/link-phone'),
              headers: {
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ${widget.token}',
              },
              body: jsonEncode({'phone': phone}),
            )
            .timeout(const Duration(seconds: 20));
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        if (!mounted) return;
        if (res.statusCode == 200) {
          final token = data['token'] as String? ?? widget.token;
          final prefs = await SharedPreferences.getInstance();
          await prefs.setString('token', token);
          if (!mounted) return;
          Navigator.pushReplacement(
              context,
              MaterialPageRoute(
                  builder: (_) => GoogleDriveBackupOfferScreen(token: token)));
        } else {
          setState(() {
            _error = data['error'] as String? ?? 'שמירת המספר נכשלה';
            _loading = false;
          });
        }
      } catch (_) {
        if (mounted) {
          setState(() {
            _error = 'שגיאת חיבור';
            _loading = false;
          });
        }
      }
      return;
    }
    try {
      final appSignature = await _startAutomaticSmsReading();
      final res = await http
          .post(
            Uri.parse('$kApi/send-otp'),
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ${widget.token}',
            },
            body: jsonEncode({
              'phone': phone,
              if (appSignature != null) 'appSignature': appSignature,
            }),
          )
          .timeout(const Duration(seconds: 20));
      if (res.statusCode == 200) {
        setState(() {
          _sentOtp = true;
          _loading = false;
        });
      } else {
        final d = jsonDecode(res.body);
        setState(() {
          _error = d['error'] ?? 'שגיאה';
          _loading = false;
        });
      }
    } catch (_) {
      setState(() {
        _error = 'שגיאת חיבור';
        _loading = false;
      });
    }
  }

  Future<void> _verify() async {
    final phone = _normalizeIsraeliMobile(_phoneCtrl.text);
    final code = _otpCtrl.text.trim();
    if (code.length != 6) {
      setState(() => _error = 'נא להזין קוד בן 6 ספרות');
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final res = await http
          .post(
            Uri.parse('$kApi/link-phone'),
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ${widget.token}'
            },
            body: jsonEncode({'phone': phone, 'code': code}),
          )
          .timeout(const Duration(seconds: 20));
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        final token = data['token'] as String? ?? widget.token;
        final prefs = await SharedPreferences.getInstance();
        await prefs.setString('token', token);
        if (!mounted) return;
        Navigator.pushReplacement(
            context,
            MaterialPageRoute(
                builder: (_) => GoogleDriveBackupOfferScreen(token: token)));
      } else {
        final d = jsonDecode(res.body);
        setState(() {
          _error = d['error'] ?? 'שגיאה';
          _loading = false;
        });
      }
    } catch (_) {
      setState(() {
        _error = 'שגיאת חיבור';
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kIsWeb ? const Color(0xFFF2F7FB) : kBg,
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 520),
            child: Container(
              width: double.infinity,
              margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 24),
              decoration: BoxDecoration(
                color: kBg,
                borderRadius: BorderRadius.circular(24),
                boxShadow: kIsWeb
                    ? const [
                        BoxShadow(
                            color: Color(0x1A0D4F82),
                            blurRadius: 28,
                            offset: Offset(0, 10))
                      ]
                    : null,
              ),
              child: SingleChildScrollView(
                padding:
                    const EdgeInsets.symmetric(horizontal: 32, vertical: 28),
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.center,
                    children: [
                      const SizedBox(height: 48),
                      Container(
                        width: 80,
                        height: 80,
                        decoration: BoxDecoration(
                            color: kPrimary,
                            borderRadius: BorderRadius.circular(20)),
                        child: const Icon(Icons.phone_android,
                            size: 44, color: Colors.white),
                      ),
                      const SizedBox(height: 20),
                      Text(
                          widget.requireVerification
                              ? 'הוסף ואמת מספר טלפון'
                              : 'הוסף מספר טלפון',
                          style: const TextStyle(
                              fontSize: 26,
                              fontWeight: FontWeight.bold,
                              color: kPrimary)),
                      const SizedBox(height: 8),
                      const Text(
                          'אפליקציית בתשובה משתמשת במספר הטלפון\nכדי לחבר אותך עם אנשי הקשר שלך',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                              fontSize: 14, color: kSubtext, height: 1.5)),
                      const SizedBox(height: 36),
                      if (!_sentOtp) ...[
                        TextField(
                          controller: _phoneCtrl,
                          keyboardType: TextInputType.phone,
                          textDirection: TextDirection.ltr,
                          decoration: const InputDecoration(
                              labelText: 'מספר טלפון',
                              hintText: '05X-XXX-XXXX',
                              prefixIcon: Icon(Icons.phone_android)),
                        ),
                        const SizedBox(height: 20),
                        SizedBox(
                          width: double.infinity,
                          child: ElevatedButton(
                            onPressed: _loading ? null : _sendOtp,
                            child: _loading
                                ? const SizedBox(
                                    height: 22,
                                    width: 22,
                                    child: CircularProgressIndicator(
                                        strokeWidth: 2, color: Colors.white))
                                : Text(
                                    widget.requireVerification
                                        ? 'שלח קוד אימות'
                                        : 'שמור והיכנס',
                                    style: const TextStyle(
                                        fontSize: 16,
                                        fontWeight: FontWeight.bold)),
                          ),
                        ),
                      ] else ...[
                        const _SmsCodeWaitingAnimation(),
                        Text('נשלח קוד SMS ל-${_phoneCtrl.text}',
                            style:
                                const TextStyle(color: kSubtext, fontSize: 13)),
                        const SizedBox(height: 16),
                        TextField(
                          controller: _otpCtrl,
                          autofillHints: const [AutofillHints.oneTimeCode],
                          keyboardType: TextInputType.number,
                          textDirection: TextDirection.ltr,
                          maxLength: 6,
                          decoration: const InputDecoration(
                              labelText: 'קוד אימות',
                              hintText: '123456',
                              prefixIcon: Icon(Icons.sms_outlined)),
                        ),
                        SizedBox(
                          width: double.infinity,
                          child: ElevatedButton(
                            onPressed: _loading ? null : _verify,
                            child: _loading
                                ? const SizedBox(
                                    height: 22,
                                    width: 22,
                                    child: CircularProgressIndicator(
                                        strokeWidth: 2, color: Colors.white))
                                : const Text('אמת וכנס',
                                    style: TextStyle(
                                        fontSize: 16,
                                        fontWeight: FontWeight.bold)),
                          ),
                        ),
                        TextButton(
                          onPressed: () => setState(() {
                            _sentOtp = false;
                            _otpCtrl.clear();
                          }),
                          child: const Text('חזור לשינוי מספר',
                              style: TextStyle(color: kSubtext, fontSize: 13)),
                        ),
                      ],
                      if (_error != null) ...[
                        const SizedBox(height: 12),
                        Container(
                          width: double.infinity,
                          padding: const EdgeInsets.all(10),
                          decoration: BoxDecoration(
                              color: Colors.red.shade50,
                              borderRadius: BorderRadius.circular(8)),
                          child: Text(_error!,
                              style: const TextStyle(
                                  color: Colors.red, fontSize: 13)),
                        ),
                      ],
                      const SizedBox(height: 16),
                      TextButton(
                        onPressed: () async {
                          final prefs = await SharedPreferences.getInstance();
                          await prefs.setString('token', widget.token);
                          if (!context.mounted) return;
                          Navigator.of(context).pushAndRemoveUntil(
                            MaterialPageRoute(
                                builder: (_) => MainShell(token: widget.token)),
                            (route) => false,
                          );
                        },
                        child: const Text('דלג על שלב זה',
                            style: TextStyle(color: kSubtext, fontSize: 13)),
                      ),
                    ]),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

