// Returns true if stored value is an emoji avatar
bool _isEmojiAvatar(String? url) => url != null && url.startsWith('emoji:');
String _emojiFromAvatar(String url) => url.substring(6);

class UserAvatar extends StatelessWidget {
  final String? picUrl;
  final String name;
  final double radius;
  const UserAvatar(
      {super.key, this.picUrl, required this.name, this.radius = 22});

  void _showExpandedImage(BuildContext context) {
    if (picUrl == null || _isEmojiAvatar(picUrl)) return;
    showDialog<void>(
      context: context,
      barrierColor: Colors.black87,
      builder: (dialogContext) => Dialog(
        backgroundColor: Colors.transparent,
        insetPadding: const EdgeInsets.all(24),
        child: Stack(
          alignment: Alignment.topRight,
          children: [
            GestureDetector(
              onTap: () => Navigator.pop(dialogContext),
              child: InteractiveViewer(
                minScale: 0.8,
                maxScale: 4,
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(16),
                  child: Image.network(
                    _absoluteMediaUrl(picUrl!),
                    fit: BoxFit.contain,
                    errorBuilder: (_, __, ___) => const SizedBox(
                      width: 280,
                      height: 280,
                      child: Center(
                        child: Icon(Icons.broken_image_outlined,
                            color: Colors.white, size: 56),
                      ),
                    ),
                  ),
                ),
              ),
            ),
            IconButton(
              tooltip: 'סגור',
              onPressed: () => Navigator.pop(dialogContext),
              icon: const Icon(Icons.close, color: Colors.white, size: 30),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_isEmojiAvatar(picUrl)) {
      final emoji = _emojiFromAvatar(picUrl!);
      return CircleAvatar(
        radius: radius,
        backgroundColor: kBorder,
        child: Text(emoji, style: TextStyle(fontSize: radius * 0.9)),
      );
    }
    return GestureDetector(
      onTap: picUrl != null && !_isEmojiAvatar(picUrl)
          ? () => _showExpandedImage(context)
          : null,
      child: CircleAvatar(
        radius: radius,
        backgroundColor: kPrimary,
        backgroundImage:
            picUrl != null ? NetworkImage(_absoluteMediaUrl(picUrl!)) : null,
        child: picUrl == null
            ? Text(name.isNotEmpty ? name[0].toUpperCase() : '?',
                style: TextStyle(
                    color: Colors.white,
                    fontSize: radius * 0.9,
                    fontWeight: FontWeight.bold))
            : null,
      ),
    );
  }
}

