// ── Verify Screen (SMS + Email after registration) ────────────────
class VerifyScreen extends StatefulWidget {
  final String phone;
  final String email;
  final String method;
  const VerifyScreen(
      {super.key,
      required this.phone,
      required this.email,
      this.method = 'phone'});
  @override
  State<VerifyScreen> createState() => _VerifyScreenState();
}

class _VerifyScreenState extends State<VerifyScreen> {
  final _codeCtrl = TextEditingController();
  bool _loading = false;

  bool _waitingEmail = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    _waitingEmail = widget.method == 'email';
  }

  @override
  void dispose() {
    _codeCtrl.dispose();
    super.dispose();
  }

  Future<void> _verifyPhone() async {
    final code = _codeCtrl.text.trim();
    if (code.length < 6) {
      setState(() => _error = 'נא להזין קוד בן 6 ספרות');
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final res = await http
          .post(
            Uri.parse('$kApi/verify-phone'),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({'phone': widget.phone, 'code': code}),
          )
          .timeout(const Duration(seconds: 30));
      final data = jsonDecode(res.body);
      if (res.statusCode != 200) {
        setState(() {
          _error = data['error'] ?? 'קוד שגוי';
          _loading = false;
        });
        return;
      }
      if (data['token'] != null) {
        if (!mounted) return;
        Navigator.pushReplacement(
            context,
            MaterialPageRoute(
                builder: (_) => AuthScreen(initialEmail: widget.email)));
      } else {
        setState(() {
          _waitingEmail = true;
          _loading = false;
        });
      }
    } catch (_) {
      setState(() {
        _error = 'שגיאת חיבור. נסה שוב.';
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kBg,
      appBar: AppBar(title: const Text('אימות חשבון')),
      body: Padding(
        padding: const EdgeInsets.all(28),
        child: _waitingEmail
            ? Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  const Icon(Icons.mark_email_read_outlined,
                      size: 80, color: kAccent),
                  const SizedBox(height: 24),
                  Text(
                      widget.method == 'email'
                          ? 'אימות באימייל'
                          : 'הטלפון אומת ✅',
                      style: TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color: kPrimary),
                      textAlign: TextAlign.center),
                  const SizedBox(height: 12),
                  Text(
                    'נשלח קישור אימות ל-${widget.email}\nלחץ על הקישור במייל להשלמת ההרשמה.',
                    style: const TextStyle(
                        color: kSubtext, fontSize: 14, height: 1.6),
                    textAlign: TextAlign.center,
                  ),
                  const SizedBox(height: 32),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: () => Navigator.pushReplacement(
                          context,
                          MaterialPageRoute(
                              builder: (_) => const AuthScreen())),
                      child: const Text('חזור לכניסה'),
                    ),
                  ),
                ],
              )
            : Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const SizedBox(height: 16),
                  Container(
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      color: kAccent.withValues(alpha: 0.1),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(color: kAccent.withValues(alpha: 0.3)),
                    ),
                    child: Row(children: [
                      const Icon(Icons.info_outline, color: kPrimary, size: 20),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          'שלחנו קוד SMS ל-${widget.phone}',
                          style: const TextStyle(
                              fontSize: 13, color: kPrimary, height: 1.4),
                        ),
                      ),
                    ]),
                  ),
                  const SizedBox(height: 28),
                  const _SmsCodeWaitingAnimation(),
                  const Text('אימות טלפון',
                      style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.bold,
                          color: kPrimary)),
                  const SizedBox(height: 4),
                  const Text('הזן את קוד ה-SMS שקיבלת',
                      style: TextStyle(color: kSubtext, fontSize: 13)),
                  const SizedBox(height: 14),
                  TextField(
                    controller: _codeCtrl,
                    keyboardType: TextInputType.number,
                    maxLength: 6,
                    textAlign: TextAlign.center,
                    textDirection: TextDirection.ltr,
                    style: const TextStyle(
                        fontSize: 32,
                        letterSpacing: 12,
                        fontWeight: FontWeight.bold),
                    decoration: const InputDecoration(
                        labelText: 'קוד אימות', counterText: ''),
                  ),
                  if (_error != null) ...[
                    const SizedBox(height: 8),
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                          color: Colors.red.shade50,
                          borderRadius: BorderRadius.circular(8)),
                      child: Text(_error!,
                          style:
                              const TextStyle(color: Colors.red, fontSize: 13)),
                    ),
                  ],
                  const SizedBox(height: 20),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: _loading ? null : _verifyPhone,
                      child: _loading
                          ? const SizedBox(
                              height: 22,
                              width: 22,
                              child: CircularProgressIndicator(
                                  strokeWidth: 2, color: Colors.white))
                          : const Text('אמת טלפון',
                              style: TextStyle(
                                  fontSize: 16, fontWeight: FontWeight.bold)),
                    ),
                  ),
                ],
              ),
      ),
    );
  }
}

// ── Forgot Password Screen ────────────────────────────────────────
class ForgotPasswordScreen extends StatefulWidget {
  const ForgotPasswordScreen({super.key});
  @override
  State<ForgotPasswordScreen> createState() => _ForgotPasswordScreenState();
}

class _ForgotPasswordScreenState extends State<ForgotPasswordScreen> {
  final _emailCtrl = TextEditingController();
  bool _loading = false;
  bool _sent = false;
  String? _error;

  @override
  void dispose() {
    _emailCtrl.dispose();
    super.dispose();
  }

  Future<void> _send() async {
    final email = _emailCtrl.text.trim();
    if (email.isEmpty || !email.contains('@')) {
      setState(() => _error = 'נא להזין כתובת אימייל תקינה');
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      await http.post(
        Uri.parse('$kApi/forgot-password'),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({'email': email}),
      );
      setState(() {
        _sent = true;
        _loading = false;
      });
    } catch (_) {
      setState(() {
        _error = 'שגיאת חיבור. נסה שוב.';
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kBg,
      appBar: AppBar(
        title: const Text('שכחתי סיסמה'),
        leading: BackButton(
            color: Colors.white, onPressed: () => Navigator.pop(context)),
      ),
      body: Padding(
        padding: const EdgeInsets.all(28),
        child: _sent
            ? Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  const Icon(Icons.mark_email_read_outlined,
                      size: 72, color: kAccent),
                  const SizedBox(height: 20),
                  const Text('נשלח מייל לאיפוס הסיסמה',
                      style: TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.bold,
                          color: kPrimary),
                      textAlign: TextAlign.center),
                  const SizedBox(height: 12),
                  Text(
                    'בדוק את תיבת הדואר שלך ב-${_emailCtrl.text.trim()} ולחץ על הקישור לאיפוס.',
                    style: const TextStyle(color: kSubtext, fontSize: 14),
                    textAlign: TextAlign.center,
                  ),
                  const SizedBox(height: 32),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: () => Navigator.pop(context),
                      child: const Text('חזור לכניסה'),
                    ),
                  ),
                ],
              )
            : Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const SizedBox(height: 20),
                  const Text(
                    'הזן את כתובת האימייל שלך ונשלח לך קישור לאיפוס הסיסמה.',
                    style: TextStyle(color: kSubtext, fontSize: 15),
                  ),
                  const SizedBox(height: 24),
                  TextField(
                    controller: _emailCtrl,
                    keyboardType: TextInputType.emailAddress,
                    textDirection: TextDirection.ltr,
                    decoration: const InputDecoration(
                        labelText: 'כתובת אימייל',
                        prefixIcon: Icon(Icons.email_outlined)),
                  ),
                  if (_error != null) ...[
                    const SizedBox(height: 8),
                    Text(_error!,
                        style:
                            const TextStyle(color: Colors.red, fontSize: 13)),
                  ],
                  const SizedBox(height: 20),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: _loading ? null : _send,
                      child: _loading
                          ? const SizedBox(
                              height: 22,
                              width: 22,
                              child: CircularProgressIndicator(
                                  strokeWidth: 2, color: Colors.white))
                          : const Text('שלח קישור לאיפוס',
                              style: TextStyle(
                                  fontSize: 16, fontWeight: FontWeight.bold)),
                    ),
                  ),
                ],
              ),
      ),
    );
  }
}

// ── Mandatory age completion for legacy beta accounts ────────────
class MainShell extends StatefulWidget {
  final String token;
  const MainShell({super.key, required this.token});
  @override
  State<MainShell> createState() => _MainShellState();
}

class _MainShellState extends State<MainShell> {
  late Future<bool> _birthDateReady;
  bool _exitDialogOpen = false;

  @override
  void initState() {
    super.initState();
    _birthDateReady = _checkBirthDate();
  }

  Future<bool> _checkBirthDate() async {
    try {
      final response = await http.get(
        Uri.parse('$kApi/registration-status'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      ).timeout(const Duration(seconds: 15));
      if (response.statusCode != 200) return false;
      final status = jsonDecode(response.body) as Map<String, dynamic>;
      return status['birthDateMissing'] != true;
    } catch (_) {
      return false;
    }
  }

  Future<void> _confirmExit() async {
    if (_exitDialogOpen || !mounted) return;
    _exitDialogOpen = true;
    final shouldExit = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('יציאה מהאפליקציה'),
        content: const Text('האם אתם בטוחים שברצונכם לצאת?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('ביטול'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('יציאה'),
          ),
        ],
      ),
    );
    _exitDialogOpen = false;
    if (shouldExit == true) await SystemNavigator.pop();
  }

  @override
  Widget build(BuildContext context) => PopScope(
        canPop: kIsWeb,
        onPopInvokedWithResult: (didPop, _) {
          if (!didPop && !kIsWeb) _confirmExit();
        },
        child: FutureBuilder<bool>(
          future: _birthDateReady,
          builder: (context, snapshot) {
            if (snapshot.connectionState != ConnectionState.done) {
              return const Scaffold(
                body: Center(child: CircularProgressIndicator()),
              );
            }
            if (snapshot.data != true) {
              return _CompleteBirthDateScreen(
                token: widget.token,
                onCompleted: () => setState(() {
                  _birthDateReady = Future.value(true);
                }),
              );
            }
            return _MainShellContent(token: widget.token);
          },
        ),
      );
}

class _CompleteBirthDateScreen extends StatefulWidget {
  final String token;
  final VoidCallback onCompleted;

  const _CompleteBirthDateScreen({
    required this.token,
    required this.onCompleted,
  });

  @override
  State<_CompleteBirthDateScreen> createState() =>
      _CompleteBirthDateScreenState();
}

class _CompleteBirthDateScreenState extends State<_CompleteBirthDateScreen> {
  DateTime? _birthDate;
  bool _loading = false;
  String? _error;

  Future<void> _save() async {
    if (_birthDate == null) {
      setState(() => _error = 'יש לבחור תאריך לידה');
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final response = await http
          .put(
            Uri.parse('$kApi/profile/birth-date'),
            headers: {
              'Authorization': 'Bearer ${widget.token}',
              'Content-Type': 'application/json',
            },
            body: jsonEncode({'birthDate': _formatBirthDate(_birthDate!)}),
          )
          .timeout(const Duration(seconds: 20));
      final data = jsonDecode(response.body) as Map<String, dynamic>;
      if (!mounted) return;
      if (response.statusCode == 200) {
        widget.onCompleted();
      } else if (response.statusCode == 409 &&
          data['code'] == 'BIRTH_DATE_ALREADY_SET') {
        // The initial status request may have failed during a brief restart.
        // A 409 here is an authenticated confirmation that this account
        // already has an immutable birth date, so do not trap it in the
        // legacy completion screen.
        widget.onCompleted();
      } else {
        setState(() {
          _error = data['error'] as String? ?? 'שמירת תאריך הלידה נכשלה';
          _loading = false;
        });
      }
    } catch (_) {
      if (mounted) {
        setState(() {
          _error = 'שגיאת חיבור. נסה שוב.';
          _loading = false;
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
        backgroundColor: kBg,
        body: SafeArea(
          child: Center(
            child: SingleChildScrollView(
              padding: const EdgeInsets.all(28),
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 440),
                child: Column(children: [
                  const Icon(Icons.shield_outlined, size: 72, color: kPrimary),
                  const SizedBox(height: 20),
                  const Text('השלמת הגנת גיל',
                      style:
                          TextStyle(fontSize: 24, fontWeight: FontWeight.bold)),
                  const SizedBox(height: 12),
                  const Text(
                    'כדי להמשיך יש להזין תאריך לידה אמיתי. לא ניתן לשנות אותו באפליקציה לאחר השמירה. בגיל 13–17 יופעל אוטומטית חשבון נוער מוגן.',
                    textAlign: TextAlign.center,
                  ),
                  const SizedBox(height: 24),
                  _BirthDateField(
                    value: _birthDate,
                    onChanged: (value) => setState(() => _birthDate = value),
                  ),
                  if (_error != null) ...[
                    const SizedBox(height: 12),
                    Text(_error!,
                        textAlign: TextAlign.center,
                        style: const TextStyle(color: Colors.red)),
                  ],
                  const SizedBox(height: 20),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: _loading ? null : _save,
                      child: _loading
                          ? const SizedBox(
                              width: 20,
                              height: 20,
                              child: CircularProgressIndicator(
                                  strokeWidth: 2, color: Colors.white),
                            )
                          : const Text('שמירה והמשך'),
                    ),
                  ),
                  const SizedBox(height: 12),
                  const Text('לסיוע: support@betshuva.com',
                      style: TextStyle(color: kSubtext)),
                ]),
              ),
            ),
          ),
        ),
      );
}

// ── Main Shell (Bottom Nav) ───────────────────────────────────────
class _MainShellContent extends StatefulWidget {
  final String token;
  const _MainShellContent({required this.token});
  @override
  State<_MainShellContent> createState() => _MainShellContentState();
}

class _MainShellContentState extends State<_MainShellContent> {
  int _idx = 0;
  int _conversationFilterIndex = 0;
  final GlobalKey<_ConversationsScreenState> _conversationsKey =
      GlobalKey<_ConversationsScreenState>();
  Map<String, dynamic>? _desktopRecipient;
  Map<String, dynamic>? _desktopGroup;
  Map<String, dynamic>? _desktopListing;
  Widget? _desktopDocument;
  String? _desktopIssueId;
  bool _openGroupMembersOnSelect = false;
  io.Socket? _socket;
  VoiceCallCoordinator? _voiceCalls;
  Map<String, dynamic>? _me;
  List<Map<String, dynamic>> _users = [];
  String? _adminPerm;
  late final _AppLifecycleObserver _lifecycleObserver;
  Timer? _usersRefreshTimer;
  Map<String, int> _unreadCounts = {}; // userId → count of unread incoming msgs
  Map<String, int> _groupUnreadCounts = {}; // groupId → unread count
  final Map<String, String> _groupTypingNames = {};
  final Map<String, Timer> _groupTypingTimers = {};
  final Set<String> _typingUserIds = {};
  final Map<String, Timer> _userTypingTimers = {};
  final List<Map<String, dynamic>> _messageRequests = [];
  bool _showingMessageRequest = false;
  bool _directAdminScreenOpened = false;

  String? get _accountId => _me?['id']?.toString();
  String? get _usersCacheKey =>
      _accountId == null ? null : 'cache_users_$_accountId';

  Future<void> _clearLocalAccountState() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove('token');
    await prefs.remove('cache_users'); // Legacy, unscoped cache.
    final cacheKey = _usersCacheKey;
    if (cacheKey != null) await prefs.remove(cacheKey);
  }

  List<Map<String, dynamic>> _withoutScanBot(List<Map<String, dynamic>> users) {
    final sorted =
        users.where((user) => user['id']?.toString() != kScanBotId).toList();
    sorted.sort((a, b) {
      final aTime = DateTime.tryParse(a['last_message_at']?.toString() ?? '');
      final bTime = DateTime.tryParse(b['last_message_at']?.toString() ?? '');
      if (aTime != null || bTime != null) {
        return (bTime ?? DateTime.fromMillisecondsSinceEpoch(0))
            .compareTo(aTime ?? DateTime.fromMillisecondsSinceEpoch(0));
      }
      return (a['name']?.toString() ?? '')
          .compareTo(b['name']?.toString() ?? '');
    });
    return sorted;
  }

  @override
  void initState() {
    super.initState();
    registerAppScreenshotMenu(this, _openScreenshotThroughIsrael);
    appScreenshotToken.value = widget.token;
    appScreenshotDestination.value =
        const AppScreenshotDestination.user(kSystemGuideId);
    appScreenshotIssueOpened = (issueId) async {
      if (!mounted) return;
      if (MediaQuery.sizeOf(context).width >= 900) {
        setState(() {
          _idx = 0;
          _desktopIssueId = issueId;
          _desktopDocument = null;
          _desktopListing = null;
        });
        return;
      }
      await Navigator.of(context).push(MaterialPageRoute(
          builder: (_) =>
              OpenIssuesScreen(token: widget.token, initialIssueId: issueId)));
    };
    appScreenshotTargetSender = (senderContext, bytes, name) =>
        _forwardChatMessage(senderContext, widget.token, _socket, {
          'localBytes': bytes,
          'fileName': name,
          'fileType': 'image',
        });
    _lifecycleObserver = _AppLifecycleObserver(onResume: _handleAppResume);
    _decodeMe();
    _loadMyProfile();
    _connectSocket();
    _loadUsers();
    _loadUnreadCounts();
    _loadGroupUnreadCounts();
    _registerFcmToken();
    _loadAdminPerm();
    _loadMessageRequests();
    WidgetsBinding.instance.addObserver(_lifecycleObserver);
    // Reconcile badges periodically in case a browser tab missed a socket event.
    _usersRefreshTimer = Timer.periodic(
      const Duration(seconds: 10),
      (_) => _refreshConversationState(),
    );
    _initNotificationOpenHandlers();
    _initAndroidSharing();
  }

  Future<void> _initAndroidSharing() async {
    if (kIsWeb || defaultTargetPlatform != TargetPlatform.android) return;
    _shareChannel.setMethodCallHandler((call) async {
      if (call.method == 'sharedContent' && call.arguments is Map) {
        _handleSharedContent(Map<String, dynamic>.from(call.arguments as Map));
      }
    });
    try {
      final initial = await _shareChannel
          .invokeMapMethod<String, dynamic>('getInitialShare');
      if (initial != null) _handleSharedContent(initial);
    } catch (_) {}
  }

  void _handleSharedContent(Map<String, dynamic> shared) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final text = shared['text'] as String?;
      final path = shared['path'] as String?;
      if ((text == null || text.trim().isEmpty) && path == null) return;
      _forwardChatMessage(context, widget.token, _socket, {
        if (text != null) 'text': text,
        if (path != null) 'localPath': path,
        if (path != null) 'fileName': shared['name'] ?? 'shared_image.jpg',
        if (path != null) 'fileType': 'image',
      });
    });
  }

  // Firebase is optional on web. Accessing FirebaseMessaging.instance when
  // Firebase initialization failed throws synchronously during initState and
  // leaves Flutter rendering a blank screen, so keep all notification setup
  // behind a guarded async boundary.
  Future<void> _initNotificationOpenHandlers() async {
    try {
      if (Firebase.apps.isEmpty) return;
      final initialMessage =
          await FirebaseMessaging.instance.getInitialMessage();
      _handleNotificationOpen(initialMessage);
      FirebaseMessaging.onMessageOpenedApp.listen(_handleNotificationOpen);
    } catch (error) {
      debugPrint('Push notification initialization skipped: $error');
    }
  }

  @override
  void dispose() {
    unregisterAppScreenshotMenu(this);
    appScreenshotIssueOpened = null;
    appScreenshotTargetSender = null;
    if (appScreenshotToken.value == widget.token) {
      appScreenshotToken.value = null;
    }
    _shareChannel.setMethodCallHandler(null);
    _usersRefreshTimer?.cancel();
    for (final timer in _groupTypingTimers.values) {
      timer.cancel();
    }
    for (final timer in _userTypingTimers.values) {
      timer.cancel();
    }
    WidgetsBinding.instance.removeObserver(_lifecycleObserver);
    _voiceCalls?.dispose();
    _socket?.disconnect();
    super.dispose();
  }

  Future<void> _loadAdminPerm() async {
    try {
      final res = await http.get(
        Uri.parse('$kApi/admin/db'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (res.statusCode == 200 && mounted) {
        final data = jsonDecode(res.body);
        final permission = data['permission'] as String?;
        setState(() => _adminPerm = permission);
        if (kOpenClassificationStats &&
            permission != null &&
            !_directAdminScreenOpened) {
          _directAdminScreenOpened = true;
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (!mounted) return;
            Navigator.of(context).push(MaterialPageRoute(
              builder: (_) => AdminScreen(
                token: widget.token,
                perm: permission,
                initialTab: 3,
              ),
            ));
          });
        }
      }
    } catch (_) {}
  }

  void _openScreenshotThroughIsrael() {
    final guide = _users.cast<Map<String, dynamic>?>().firstWhere(
          (user) => user?['id']?.toString() == kSystemGuideId,
          orElse: () => <String, dynamic>{
            'id': kSystemGuideId,
            'name': 'מידע בטוח · AI',
          },
        )!;
    final isDesktop = MediaQuery.sizeOf(context).width >= 900;
    if (isDesktop) {
      setState(() {
        _idx = 0;
        _desktopRecipient = guide;
        _desktopGroup = null;
        _desktopListing = null;
        _desktopDocument = null;
      });
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) openRegisteredAppScreenshotMenu();
      });
      return;
    }
    Navigator.of(context).push(MaterialPageRoute(
      builder: (_) => ChatScreen(
        token: widget.token,
        me: _me,
        recipient: guide,
        socket: _socket,
        openScreenshotMenuOnStart: true,
      ),
    ));
  }

  Future<void> _loadMessageRequests() async {
    try {
      final response = await http.get(Uri.parse('$kApi/message-requests'),
          headers: {'Authorization': 'Bearer ${widget.token}'});
      if (response.statusCode != 200 || !mounted) return;
      _messageRequests
        ..clear()
        ..addAll(
          (jsonDecode(response.body) as List)
              .cast<Map<String, dynamic>>()
              .where((request) =>
                  request['sender_id']?.toString() != _me?['id']?.toString()),
        );
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _showNextMessageRequest();
      });
    } catch (_) {}
  }

  Future<void> _showNextMessageRequest() async {
    if (!mounted || _showingMessageRequest || _messageRequests.isEmpty) return;
    _showingMessageRequest = true;
    final request = _messageRequests.first;
    final senderName =
        request['sender_name'] ?? request['senderName'] ?? 'משתמש';
    Map<String, bool> readFilter(dynamic raw) => raw is Map
        ? raw.map((key, value) => MapEntry(key.toString(), value == true))
        : <String, bool>{};
    var selectedFilter = _newAccountFilter();
    final counterpartFilter = readFilter(request['expected_filter']);
    Map<String, dynamic>? decision;
    try {
      decision = await showDialog<Map<String, dynamic>>(
        context: context,
        barrierDismissible: false,
        builder: (dialogContext) => StatefulBuilder(
          builder: (context, setDialogState) => AlertDialog(
            title: Row(children: [
              const Icon(Icons.person_add_outlined, color: kPrimary),
              const SizedBox(width: 9),
              Expanded(
                child: Text('בקשת חברות מאת $senderName',
                    textAlign: TextAlign.right),
              ),
            ]),
            content: SizedBox(
              width: 760,
              child: SingleChildScrollView(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      '$senderName רוצה להוסיף אותך כחבר ולשלוח לך הודעה. לפני האישור ניתן לבחור מה יוצג עבורך בקשר זה.',
                      textAlign: TextAlign.right,
                      style: const TextStyle(height: 1.4),
                    ),
                    const SizedBox(height: 12),
                    _InvitationFilterComparisonTable(
                      groupName: senderName.toString(),
                      groupFilter: counterpartFilter,
                      personalFilter: selectedFilter,
                      counterpartKind: 'החבר',
                      counterpartIcon: Icons.person_outline,
                      onPersonalFilterChanged: (updated) =>
                          setDialogState(() => selectedFilter = updated),
                    ),
                  ],
                ),
              ),
            ),
            actions: [
              FilledButton.icon(
                onPressed: () => Navigator.pop(dialogContext, {
                  'accepted': true,
                  'filter': selectedFilter,
                }),
                icon: const Icon(Icons.person_add_outlined),
                label: const Text('אשר והוסף כחבר'),
              ),
              TextButton(
                onPressed: () =>
                    Navigator.pop(dialogContext, {'accepted': false}),
                style: TextButton.styleFrom(foregroundColor: Colors.red),
                child: const Text('דחה'),
              ),
            ],
          ),
        ),
      );
    } catch (_) {
      // A request can arrive while the first frame or another route transition
      // is still being built. Release the guard so the next reconciliation can
      // show the still-pending server request instead of hiding it forever.
      _showingMessageRequest = false;
      return;
    }
    final accepted = decision?['accepted'] == true;
    final chosenFilter = decision?['filter'];
    try {
      final id = request['id'];
      late final http.Response response;
      if (accepted) {
        response =
            await http.post(Uri.parse('$kApi/message-requests/$id/accept'),
                headers: {
                  'Authorization': 'Bearer ${widget.token}',
                  'Content-Type': 'application/json',
                },
                body: jsonEncode({'filter': chosenFilter}));
        if (response.statusCode != 200) throw Exception('accept failed');
        await _refreshConversationState();
      } else {
        response = await http.delete(Uri.parse('$kApi/message-requests/$id'),
            headers: {'Authorization': 'Bearer ${widget.token}'});
        if (response.statusCode != 200) throw Exception('decline failed');
      }
    } catch (_) {
      _showingMessageRequest = false;
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text('לא ניתן להשלים כעת את אישור החבר. נסה שוב.'),
        ));
      }
      return;
    }
    if (accepted) {
      final senderId = request['sender_id'] ?? request['senderId'];
      _messageRequests.removeWhere(
          (item) => (item['sender_id'] ?? item['senderId']) == senderId);
    } else {
      _messageRequests.removeAt(0);
    }
    _showingMessageRequest = false;
    _showNextMessageRequest();
  }

  Future<void> _registerFcmToken() async {
    try {
      final messaging = FirebaseMessaging.instance;
      await messaging.requestPermission(alert: true, badge: true, sound: true);
      final token =
          kIsWeb ? await getBetshuvaWebPushToken() : await messaging.getToken();
      if (token == null) return;
      await http.post(
        Uri.parse('$kApi/fcm-token'),
        headers: {
          'Authorization': 'Bearer ${widget.token}',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'token': token,
          'deviceId': kIsWeb ? 'web:$token' : 'android:$token',
        }),
      );
      // Refresh token when it changes
      messaging.onTokenRefresh.listen((newToken) {
        http.post(
          Uri.parse('$kApi/fcm-token'),
          headers: {
            'Authorization': 'Bearer ${widget.token}',
            'Content-Type': 'application/json',
          },
          body: jsonEncode({
            'token': newToken,
            'deviceId': kIsWeb ? 'web:$newToken' : 'android:$newToken',
          }),
        );
      });
    } catch (_) {}
  }

  void _decodeMe() {
    final parts = widget.token.split('.');
    if (parts.length == 3) {
      final payload = jsonDecode(
          utf8.decode(base64Url.decode(base64Url.normalize(parts[1]))));
      setState(() => _me = payload as Map<String, dynamic>);
    }
  }

  Future<void> _loadMyProfile() async {
    try {
      final res = await http.get(
        Uri.parse('$kApi/profile'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (res.statusCode == 200 && mounted) {
        final profile = jsonDecode(res.body) as Map<String, dynamic>;
        setState(() => _me = {...?_me, ...profile});
      }
    } catch (_) {}
  }

  Future<void> _loadUnreadCounts() async {
    try {
      final res = await http.get(
        Uri.parse('$kApi/messages/unread'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (res.statusCode == 200 && mounted) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        setState(() => _unreadCounts = data.map((k, v) => MapEntry(
            k, v is num ? v.toInt() : int.tryParse(v.toString()) ?? 0)));
      }
    } catch (_) {}
  }

  Future<void> _loadGroupUnreadCounts() async {
    try {
      final res = await http.get(
        Uri.parse('$kApi/groups/unread'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (res.statusCode == 200 && mounted) {
        final data = jsonDecode(res.body) as Map<String, dynamic>;
        setState(() => _groupUnreadCounts = data.map((k, v) => MapEntry(
            k, v is num ? v.toInt() : int.tryParse(v.toString()) ?? 0)));
      }
    } catch (_) {}
  }

  Future<void> _refreshConversationState() async {
    await Future.wait([
      _loadUsers(),
      _loadUnreadCounts(),
      _loadGroupUnreadCounts(),
      _loadMessageRequests(),
    ]);
  }

  void _handleAppResume() {
    final socket = _socket;
    if (socket != null && !socket.connected) socket.connect();
    _refreshConversationState();
  }

  void _openGroup(Map<String, dynamic> group, bool openMembers) {
    final groupId = group['id'] as String;
    setState(() {
      _desktopRecipient = null;
      _desktopGroup = group;
      _desktopListing = null;
      _desktopDocument = null;
      _desktopIssueId = null;
      _openGroupMembersOnSelect = openMembers;
      _groupUnreadCounts.remove(groupId);
    });
  }

  void _openDesktopDocument(String fileUrl, String? fileName, bool isPdf) {
    if (!kIsWeb || MediaQuery.sizeOf(context).width < 900) return;
    final name = fileName?.trim().isNotEmpty == true ? fileName! : 'מסמך';
    setState(() {
      _desktopIssueId = null;
      _desktopDocument = isPdf
          ? _InAppPdfScreen(
              url: _absoluteMediaUrl(fileUrl),
              fileName: name,
              embedded: true,
              onClose: () => setState(() => _desktopDocument = null),
            )
          : _OfficeDocumentScreen(
              fileUrl: fileUrl,
              fileName: name,
              token: widget.token,
              embedded: true,
              onClose: () => setState(() => _desktopDocument = null),
            );
    });
  }

  Future<void> _openMarketplaceConversation(
      Map<String, dynamic> recipient) async {
    await _loadUsers();
    if (!mounted) return;
    final recipientId = recipient['id']?.toString();
    final refreshed = _users.where(
      (user) => user['id']?.toString() == recipientId,
    );
    setState(() {
      _idx = 0;
      _desktopRecipient = refreshed.isNotEmpty
          ? refreshed.first
          : Map<String, dynamic>.from(recipient);
      _desktopGroup = null;
      _desktopListing = null;
      _desktopDocument = null;
      _openGroupMembersOnSelect = false;
    });
    if (MediaQuery.sizeOf(context).width < 900) {
      final selectedRecipient = _desktopRecipient!;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        Navigator.of(context).push(MaterialPageRoute(
          builder: (_) => ChatScreen(
            token: widget.token,
            me: _me,
            recipient: selectedRecipient,
            socket: _socket,
            onVoiceCall: () => _voiceCalls?.startCall(
              selectedRecipient['id'] as String,
              selectedRecipient['name']?.toString() ?? 'משתמש',
            ),
          ),
        ));
      });
    }
  }

  void _handleNotificationOpen(RemoteMessage? msg) {
    if (msg == null || !mounted) return;
    final fromUserId = msg.data['fromUserId'] as String?;
    final type = msg.data['type'] as String?;
    if (type == 'chat' && fromUserId != null) {
      final user = _users.firstWhere(
        (u) => u['id'] == fromUserId,
        orElse: () => {
          'id': fromUserId,
          'name': msg.notification?.title ?? 'משתמש',
        },
      );
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        setState(() => _unreadCounts.remove(fromUserId));
        Navigator.of(context).push(MaterialPageRoute(
          builder: (_) => ChatScreen(
            token: widget.token,
            me: _me,
            recipient: user,
            socket: _socket,
            onVoiceCall: () => _voiceCalls?.startCall(
              user['id'] as String,
              user['name']?.toString() ?? 'משתמש',
            ),
          ),
        ));
      });
    }
  }

  Future<void> _loadUsers() async {
    // Load from cache first for instant offline display
    try {
      final prefs = await SharedPreferences.getInstance();
      // Never reuse the old global cache: it may belong to a deleted account.
      await prefs.remove('cache_users');
      final cacheKey = _usersCacheKey;
      final cached = cacheKey == null ? null : prefs.getString(cacheKey);
      if (cached != null && _users.isEmpty) {
        setState(() => _users = _withoutScanBot(
            (jsonDecode(cached) as List).cast<Map<String, dynamic>>()));
      }
    } catch (_) {}
    // Then fetch from server and update cache
    try {
      final res = await http.get(
        Uri.parse('$kApi/users'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as List;
        if (mounted) {
          setState(() =>
              _users = _withoutScanBot(data.cast<Map<String, dynamic>>()));
        }
        final prefs = await SharedPreferences.getInstance();
        final cacheKey = _usersCacheKey;
        if (cacheKey != null) await prefs.setString(cacheKey, res.body);
      } else if (res.statusCode == 403) {
        _requirePhoneSetup();
      } else if (res.statusCode == 401) {
        // משתמש לא קיים ב-DB — ghost session → יציאה אוטומטית
        _forceLogout();
      }
    } catch (_) {}
  }

  void _connectSocket() {
    _socket = io.io(
      kSocketOrigin,
      io.OptionBuilder().setPath(kSocketPath).setTransports(
          ['websocket']).setAuth({'token': widget.token}).build(),
    );
    _voiceCalls = VoiceCallCoordinator(
      socket: _socket!,
      contextProvider: () => mounted ? context : null,
      token: widget.token,
      apiBase: kApi,
    );
    // רענן רשימת משתמשים כשהסוקט מתחבר מחדש
    _socket!.on('connect', (_) {
      _loadUsers();
      _loadUnreadCounts();
      _loadGroupUnreadCounts();
    });

    // טיפול בשגיאת חיבור — משתמש לא קיים ב-DB → יציאה אוטומטית
    _socket!.on('connect_error', (err) {
      final msg = err?.toString() ?? '';
      if (msg.contains('verification_required') ||
          msg.contains('phone_required')) {
        _requirePhoneSetup(
            requireVerification: msg.contains('verification_required'));
      } else if (msg.contains('registration_incomplete') ||
          msg.contains('user_not_found')) {
        _forceLogout(showRegistration: true);
      } else if (msg.contains('unauthorized')) {
        _forceLogout();
      }
    });

    // אדמין מחק את המשתמש בזמן שהוא מחובר
    _socket!.on('force_logout', (data) {
      final reason = data is Map ? data['reason']?.toString() ?? '' : '';
      _forceLogout(showRegistration: reason.contains('נמחק'));
    });
    _socket!.on('message:request', (data) {
      if (!mounted || data is! Map) return;
      // The realtime event is intentionally small. Reload the complete request
      // so the approval screen always has both filter columns, exactly like a
      // group invitation, instead of silently defaulting missing values.
      _loadMessageRequests();
    });

    // הודעה חדשה בזמן שהאפליקציה פתוחה — עדכן badge
    _socket!.on('chat:message', (data) {
      if (!mounted) return;
      final fromId = data['fromUserId'] as String?;
      final myId = _me?['id'] as String?;
      if (fromId == null || fromId == myId || fromId == kScanBotId) return;
      setState(() => _unreadCounts[fromId] = (_unreadCounts[fromId] ?? 0) + 1);
      _loadUsers();
    });
    _socket!.on('chat:typing', (data) {
      if (!mounted) return;
      final userId = data['fromUserId'] as String?;
      if (userId == null || userId == _me?['id']) return;
      _userTypingTimers[userId]?.cancel();
      setState(() => _typingUserIds.add(userId));
      _userTypingTimers[userId] = Timer(const Duration(seconds: 3), () {
        if (mounted) setState(() => _typingUserIds.remove(userId));
      });
    });
    _socket!.on('group:message', (data) {
      if (!mounted) return;
      final groupId = data['groupId'] as String?;
      final fromId = data['fromUserId'] as String?;
      if (groupId == null || fromId == _me?['id']) return;
      if (_desktopGroup?['id'] == groupId) return;
      setState(() =>
          _groupUnreadCounts[groupId] = (_groupUnreadCounts[groupId] ?? 0) + 1);
    });
    _socket!.on('group:typing', (data) {
      if (!mounted) return;
      final groupId = data['groupId'] as String?;
      final userId = data['fromUserId'] as String?;
      final name = data['fromName'] as String?;
      if (groupId == null || name == null || userId == _me?['id']) return;
      _groupTypingTimers[groupId]?.cancel();
      setState(() => _groupTypingNames[groupId] = name);
      _groupTypingTimers[groupId] = Timer(const Duration(seconds: 3), () {
        if (mounted) setState(() => _groupTypingNames.remove(groupId));
      });
    });
  }

  Future<void> _logout() async {
    await _leaveAccount(showRegistration: false);
  }

  Future<void> _logoutAfterAccountDeletion() async {
    await _leaveAccount(showRegistration: true);
  }

  Future<void> _leaveAccount({required bool showRegistration}) async {
    _socket?.disconnect();
    await _clearLocalAccountState();
    if (!mounted) return;
    Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
      MaterialPageRoute(
          builder: (_) => AuthScreen(initialRegistration: showRegistration)),
      (_) => false,
    );
  }

  Future<void> _forceLogout({bool showRegistration = false}) async {
    _socket?.disconnect();
    await _clearLocalAccountState();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(showRegistration
            ? 'החשבון נמחק — ניתן להירשם מחדש'
            : 'הפגישה פגה — נא להתחבר מחדש'),
        backgroundColor: showRegistration ? Colors.blue : Colors.orange,
        duration: const Duration(seconds: 3),
      ),
    );
    Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
      MaterialPageRoute(
          builder: (_) => AuthScreen(initialRegistration: showRegistration)),
      (route) => false,
    );
  }

  void _requirePhoneSetup({bool requireVerification = false}) {
    _socket?.disconnect();
    if (!mounted) return;
    Navigator.of(context).pushAndRemoveUntil(
      MaterialPageRoute(
        builder: (_) => GooglePhoneSetupScreen(
          token: widget.token,
          requireVerification: requireVerification,
        ),
      ),
      (route) => false,
    );
  }

  @override
  Widget build(BuildContext context) {
    final totalUnreadMessages = _unreadCounts.values
        .where((count) => count > 0)
        .fold<int>(0, (total, count) => total + count);
    final totalUnreadGroups = _groupUnreadCounts.values
        .where((count) => count > 0)
        .fold<int>(0, (total, count) => total + count);

    Widget navigationIcon(IconData icon, int unreadCount) => Stack(
          clipBehavior: Clip.none,
          children: [
            Icon(icon),
            if (unreadCount > 0)
              Positioned.directional(
                textDirection: Directionality.of(context),
                top: -9,
                end: -13,
                child: Semantics(
                  label: '$unreadCount הודעות שלא נקראו',
                  child: Container(
                    constraints:
                        const BoxConstraints(minWidth: 20, minHeight: 20),
                    padding: const EdgeInsets.symmetric(horizontal: 5),
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: kPrimaryMid,
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(color: Colors.white, width: 1.5),
                    ),
                    child: Text(
                      unreadCount > 99 ? '99+' : '$unreadCount',
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 10,
                        height: 1,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                ),
              ),
          ],
        );

    final conversations = ConversationsScreen(
      key: _conversationsKey,
      users: _users,
      token: widget.token,
      me: _me,
      socket: _socket,
      unreadCounts: _unreadCounts,
      groupUnreadCounts: _groupUnreadCounts,
      groupTypingNames: _groupTypingNames,
      typingUserIds: _typingUserIds,
      onLogout: _logout,
      onSettings: () => setState(() => _idx = 3),
      onContactsChanged: _loadUsers,
      onVoiceCall: (user) {
        _voiceCalls?.startCall(
          user['id'] as String,
          user['name']?.toString() ?? 'משתמש',
        );
      },
      currentMainNavigationIndex: _idx.clamp(0, 2),
      onMainNavigationSelected: (index) => setState(() => _idx = index),
      onFilterChanged: (index) =>
          setState(() => _conversationFilterIndex = index),
      selectedUserId: _desktopRecipient?['id'] as String?,
      onUserSelected: (user) {
        final userId = user['id'] as String;
        if (_unreadCounts.containsKey(userId)) {
          setState(() => _unreadCounts.remove(userId));
        }
        setState(() {
          _desktopRecipient = user;
          _desktopGroup = null;
          _desktopListing = null;
          _desktopDocument = null;
          _desktopIssueId = null;
          _openGroupMembersOnSelect = false;
        });
      },
      selectedGroupId: _desktopGroup?['id'] as String?,
      onGroupSelected: _openGroup,
      onChatOpened: (userId) {
        if (_unreadCounts.containsKey(userId)) {
          setState(() => _unreadCounts.remove(userId));
        }
      },
    );
    final groups = GroupsScreen(
      token: widget.token,
      me: _me,
      socket: _socket,
      groupTypingNames: _groupTypingNames,
      selectedGroupId: _desktopGroup?['id'] as String?,
      onGroupSelected: _openGroup,
      currentMainNavigationIndex: _idx.clamp(0, 2),
      onMainNavigationSelected: (index) => setState(() => _idx = index),
    );
    final screens = [
      conversations,
      groups,
      ListingsScreen(
        token: widget.token,
        me: _me,
        socket: _socket,
        onConversationStarted: _openMarketplaceConversation,
        currentMainNavigationIndex: _idx.clamp(0, 2),
        onMainNavigationSelected: (index) => setState(() => _idx = index),
      ),
      SettingsScreen(
          me: _me,
          token: widget.token,
          onBack: () => setState(() => _idx = 0),
          onLogout: _logout,
          onAccountDeleted: _logoutAfterAccountDeletion,
          onProfileChanged: _loadMyProfile,
          adminPerm: _adminPerm),
    ];

    final isDesktop = MediaQuery.sizeOf(context).width >= 900;
    final body = isDesktop && (_idx == 0 || _idx == 1)
        ? Row(
            children: [
              SizedBox(width: 410, child: _idx == 0 ? conversations : groups),
              const VerticalDivider(
                  width: 1, thickness: 1, color: Color(0xFFD9DEE1)),
              Expanded(
                child: _desktopIssueId != null
                    ? OpenIssuesScreen(
                        key: ValueKey('desktop-issue:$_desktopIssueId'),
                        token: widget.token,
                        initialIssueId: _desktopIssueId,
                        embedded: true,
                        onClose: () => setState(() => _desktopIssueId = null),
                      )
                    : _desktopDocument != null
                        ? _desktopDocument!
                        : _desktopListing != null
                            ? ListingDetailScreen(
                                key: ValueKey(
                                    'chat-listing:${_desktopListing!['id']}'),
                                item: _desktopListing!,
                                token: widget.token,
                                me: _me,
                                socket: _socket,
                                embedded: true,
                                onClose: () =>
                                    setState(() => _desktopListing = null),
                                onConversationStarted:
                                    _openMarketplaceConversation,
                              )
                            : _idx == 0
                                ? (_desktopGroup != null
                                    ? GroupChatScreen(
                                        key: ValueKey(
                                            'chat-tab:${_desktopGroup!['id']}:$_openGroupMembersOnSelect'),
                                        group: _desktopGroup!,
                                        me: _me,
                                        token: widget.token,
                                        socket: _socket,
                                        embedded: true,
                                        onDocumentOpen: _openDesktopDocument,
                                        openAddMembersOnStart:
                                            _openGroupMembersOnSelect,
                                        onMembersChanged: (count) =>
                                            setState(() {
                                          _desktopGroup?['member_count'] =
                                              count;
                                        }),
                                        onClose: () => setState(() {
                                          _desktopGroup = null;
                                          _desktopDocument = null;
                                          _openGroupMembersOnSelect = false;
                                        }),
                                      )
                                    : _desktopRecipient == null
                                        ? const _DesktopChatWelcome()
                                        : ChatScreen(
                                            key: ValueKey(
                                                _desktopRecipient!['id']),
                                            token: widget.token,
                                            me: _me,
                                            recipient: _desktopRecipient!,
                                            socket: _socket,
                                            onVoiceCall: () =>
                                                _voiceCalls?.startCall(
                                              _desktopRecipient!['id']
                                                  as String,
                                              _desktopRecipient!['name']
                                                      ?.toString() ??
                                                  'משתמש',
                                            ),
                                            embedded: true,
                                            onDocumentOpen:
                                                _openDesktopDocument,
                                            onBlocked: () {
                                              final blockedId =
                                                  _desktopRecipient!['id']
                                                      ?.toString();
                                              setState(() {
                                                _users.removeWhere((user) =>
                                                    user['id']?.toString() ==
                                                    blockedId);
                                                _unreadCounts.remove(blockedId);
                                              });
                                              _loadUsers();
                                            },
                                            onClose: () => setState(() {
                                              _desktopRecipient = null;
                                              _desktopDocument = null;
                                            }),
                                          ))
                                : (_desktopGroup == null
                                    ? const _DesktopGroupWelcome()
                                    : GroupChatScreen(
                                        key: ValueKey(
                                            '${_desktopGroup!['id']}:$_openGroupMembersOnSelect'),
                                        group: _desktopGroup!,
                                        me: _me,
                                        token: widget.token,
                                        socket: _socket,
                                        embedded: true,
                                        onDocumentOpen: _openDesktopDocument,
                                        openAddMembersOnStart:
                                            _openGroupMembersOnSelect,
                                        onMembersChanged: (count) =>
                                            setState(() {
                                          _desktopGroup?['member_count'] =
                                              count;
                                        }),
                                        onClose: () => setState(() {
                                          _desktopGroup = null;
                                          _desktopDocument = null;
                                          _openGroupMembersOnSelect = false;
                                        }),
                                      )),
              ),
            ],
          )
        : screens[_idx];

    final navigationBar = BottomNavigationBar(
      currentIndex: _conversationFilterIndex,
      onTap: (i) {
        setState(() {
          _idx = 0;
          _conversationFilterIndex = i;
        });
        _conversationsKey.currentState?.selectFilter(i);
      },
      selectedItemColor: kPrimary,
      unselectedItemColor: kSubtext,
      backgroundColor: Colors.white,
      elevation: 8,
      type: BottomNavigationBarType.fixed,
      items: [
        BottomNavigationBarItem(
          icon: navigationIcon(Icons.chat_bubble_outline, totalUnreadMessages),
          activeIcon: navigationIcon(Icons.chat_bubble, totalUnreadMessages),
          label: 'כל השיחות',
        ),
        BottomNavigationBarItem(
          icon: navigationIcon(Icons.mark_chat_unread_outlined,
              totalUnreadMessages + totalUnreadGroups),
          activeIcon: navigationIcon(
              Icons.mark_chat_unread, totalUnreadMessages + totalUnreadGroups),
          label: 'לא נקרא',
        ),
        BottomNavigationBarItem(
          icon: navigationIcon(Icons.group_outlined, totalUnreadGroups),
          activeIcon: navigationIcon(Icons.group, totalUnreadGroups),
          label: 'קבוצות',
        ),
      ],
    );

    return Scaffold(
      body: NotificationListener<_OpenIssuesNotification>(
        onNotification: (notification) {
          if (!isDesktop) return false;
          notification.handledInDesktopPane = true;
          setState(() {
            _idx = 0;
            _desktopIssueId = notification.issueId;
            _desktopDocument = null;
            _desktopListing = null;
          });
          return true;
        },
        child: NotificationListener<_OpenListingNotification>(
          onNotification: (notification) {
            if (!isDesktop || (_idx != 0 && _idx != 1)) return false;
            notification.handledInDesktopPane = true;
            setState(() => _desktopListing = notification.listing);
            return true;
          },
          child: NotificationListener<_OpenSharedContactChatNotification>(
            onNotification: (notification) {
              if (!isDesktop) return false;
              notification.handledInDesktopPane = true;
              final recipient = notification.recipient;
              final recipientId = recipient['id']?.toString();
              setState(() {
                _idx = 0;
                _desktopGroup = null;
                _desktopListing = null;
                _openGroupMembersOnSelect = false;
                _desktopRecipient = _users.firstWhere(
                  (user) => user['id']?.toString() == recipientId,
                  orElse: () => recipient,
                );
                if (recipientId != null) _unreadCounts.remove(recipientId);
              });
              return true;
            },
            child: body,
          ),
        ),
      ),
      bottomNavigationBar: _idx == 3
          ? null
          : isDesktop
              ? Align(
                  alignment: Alignment.centerRight,
                  heightFactor: 1,
                  child: SizedBox(width: 410, child: navigationBar),
                )
              : navigationBar,
    );
  }
}

