String _listingPublishedAt(dynamic value, {bool compact = false}) {
  final parsed = DateTime.tryParse(value?.toString() ?? '')?.toLocal();
  if (parsed == null) return '';
  final day = parsed.day.toString().padLeft(2, '0');
  final month = parsed.month.toString().padLeft(2, '0');
  if (compact) return '$day/$month/${parsed.year.toString().substring(2)}';
  final hour = parsed.hour.toString().padLeft(2, '0');
  final minute = parsed.minute.toString().padLeft(2, '0');
  return 'פורסם ב־$day/$month/${parsed.year} בשעה $hour:$minute';
}

String normalizeListingSearchText(String value) =>
    value.toLowerCase().replaceAll(RegExp(r'[^a-z0-9\u0590-\u05ff]+'), '');

class _PopularValueField extends StatefulWidget {
  final TextEditingController controller;
  final String label;
  final String? hint;
  final List<String> options;
  final ValueChanged<String>? onChanged;
  const _PopularValueField({
    super.key,
    required this.controller,
    required this.label,
    required this.options,
    this.onChanged,
    this.hint,
  });

  @override
  State<_PopularValueField> createState() => _PopularValueFieldState();
}

class _PopularValueFieldState extends State<_PopularValueField> {
  final _focusNode = FocusNode();

  Future<void> _showAllOptions() async {
    var query = '';
    final selected = await showModalBottomSheet<String>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(22)),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (context, setSheetState) {
          final normalizedQuery = normalizeListingSearchText(query);
          final filtered = widget.options
              .where((value) =>
                  normalizedQuery.isEmpty ||
                  normalizeListingSearchText(value).contains(normalizedQuery))
              .toList();
          return Directionality(
            textDirection: TextDirection.rtl,
            child: FractionallySizedBox(
              heightFactor: .78,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
                child: Column(children: [
                  Container(
                    width: 42,
                    height: 4,
                    decoration: BoxDecoration(
                      color: const Color(0xFFBDD0DF),
                      borderRadius: BorderRadius.circular(4),
                    ),
                  ),
                  const SizedBox(height: 12),
                  Text('בחירת ${widget.label}',
                      style: const TextStyle(
                          fontSize: 19, fontWeight: FontWeight.w800)),
                  const SizedBox(height: 12),
                  TextField(
                    autofocus: true,
                    textDirection: TextDirection.rtl,
                    onChanged: (value) => setSheetState(() => query = value),
                    decoration: InputDecoration(
                      hintText: 'חיפוש מתוך ${widget.options.length} אפשרויות',
                      prefixIcon: const Icon(Icons.search),
                      border: const OutlineInputBorder(),
                    ),
                  ),
                  const SizedBox(height: 8),
                  Expanded(
                    child: filtered.isEmpty
                        ? const Center(
                            child: Text(
                                'לא נמצאה אפשרות — אפשר להקליד ידנית בשדה'))
                        : ListView.separated(
                            itemCount: filtered.length,
                            separatorBuilder: (_, __) =>
                                const Divider(height: 1),
                            itemBuilder: (_, index) {
                              final value = filtered[index];
                              return ListTile(
                                title: Text(value),
                                trailing: widget.controller.text == value
                                    ? const Icon(Icons.check_circle,
                                        color: kPrimary)
                                    : null,
                                onTap: () => Navigator.pop(sheetContext, value),
                              );
                            },
                          ),
                  ),
                ]),
              ),
            ),
          );
        },
      ),
    );
    if (selected == null) return;
    widget.controller.text = selected;
    widget.onChanged?.call(selected);
  }

  @override
  void dispose() {
    _focusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (widget.options.isEmpty) {
      return TextField(
        controller: widget.controller,
        onChanged: widget.onChanged,
        textDirection: TextDirection.rtl,
        decoration: InputDecoration(
          labelText: widget.label,
          hintText: widget.hint,
          border: const OutlineInputBorder(),
        ),
      );
    }
    return RawAutocomplete<String>(
      textEditingController: widget.controller,
      focusNode: _focusNode,
      displayStringForOption: (option) => option,
      optionsBuilder: (value) {
        final query = normalizeListingSearchText(value.text);
        return widget.options.where((option) =>
            query.isEmpty ||
            normalizeListingSearchText(option).contains(query));
      },
      onSelected: (option) {
        widget.controller.text = option;
        widget.onChanged?.call(option);
      },
      fieldViewBuilder: (context, controller, focusNode, onSubmitted) =>
          TextField(
        controller: controller,
        focusNode: focusNode,
        onChanged: widget.onChanged,
        textDirection: TextDirection.rtl,
        decoration: InputDecoration(
          labelText: widget.label,
          hintText: widget.hint,
          helperText:
              '${widget.options.length} אפשרויות — אפשר גם להקליד ערך אחר',
          suffixIcon: IconButton(
            tooltip: 'הצג את כל האפשרויות',
            onPressed: _showAllOptions,
            icon: const Icon(Icons.arrow_drop_down_circle_outlined),
          ),
          border: const OutlineInputBorder(),
        ),
      ),
      optionsViewBuilder: (context, onSelected, options) => Align(
        alignment: Alignment.topRight,
        child: Material(
          elevation: 8,
          borderRadius: BorderRadius.circular(10),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxHeight: 250, maxWidth: 360),
            child: ListView.builder(
              padding: EdgeInsets.zero,
              shrinkWrap: true,
              itemCount: options.length,
              itemBuilder: (_, index) {
                final option = options.elementAt(index);
                return ListTile(
                  dense: true,
                  title: Text(option, textDirection: TextDirection.rtl),
                  onTap: () => onSelected(option),
                );
              },
            ),
          ),
        ),
      ),
    );
  }
}

class _LocationAutocompleteField extends StatefulWidget {
  final TextEditingController controller;
  final String label;
  final String? hint;
  final ValueChanged<String>? onChanged;
  const _LocationAutocompleteField({
    required this.controller,
    this.label = 'עיר או אזור',
    this.hint,
    this.onChanged,
  });

  @override
  State<_LocationAutocompleteField> createState() =>
      _LocationAutocompleteFieldState();
}

class _LocationAutocompleteFieldState
    extends State<_LocationAutocompleteField> {
  final _focusNode = FocusNode();
  Timer? _searchDebounce;
  List<String> _governmentLocations = const [];

  void _searchGovernmentLocations(String value) {
    _searchDebounce?.cancel();
    final query = value.trim();
    _searchDebounce = Timer(const Duration(milliseconds: 220), () async {
      try {
        final uri = Uri.parse('$kApi/localities')
            .replace(queryParameters: {if (query.isNotEmpty) 'q': query});
        final response = await http.get(uri);
        if (!mounted || response.statusCode != 200) return;
        final rows =
            (jsonDecode(response.body) as List).cast<Map<String, dynamic>>();
        setState(() => _governmentLocations = rows
            .map((row) => row['city']?.toString() ?? '')
            .where((city) => city.isNotEmpty)
            .toList());
      } catch (_) {}
    });
  }

  @override
  void dispose() {
    _searchDebounce?.cancel();
    _focusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => RawAutocomplete<String>(
        textEditingController: widget.controller,
        focusNode: _focusNode,
        displayStringForOption: (option) => option,
        optionsBuilder: (value) {
          final query = value.text.trim();
          final combined = <String>{
            ..._governmentLocations,
            ..._kIsraeliLocations
                .where((location) => query.isEmpty || location.contains(query)),
          };
          return combined.take(30);
        },
        onSelected: (option) {
          widget.controller.text = option;
          widget.onChanged?.call(option);
        },
        fieldViewBuilder: (context, controller, focusNode, onSubmitted) =>
            TextField(
          controller: controller,
          focusNode: focusNode,
          textDirection: TextDirection.rtl,
          onChanged: (value) {
            _searchGovernmentLocations(value);
            widget.onChanged?.call(value);
          },
          onSubmitted: (_) => onSubmitted(),
          decoration: InputDecoration(
            labelText: widget.label,
            hintText: widget.hint,
            prefixIcon: const Icon(Icons.location_city_outlined),
            border: const OutlineInputBorder(),
          ),
        ),
        optionsViewBuilder: (context, onSelected, options) => Align(
          alignment: Alignment.topRight,
          child: Material(
            elevation: 8,
            borderRadius: BorderRadius.circular(10),
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 260, maxWidth: 420),
              child: ListView.builder(
                padding: EdgeInsets.zero,
                shrinkWrap: true,
                itemCount: options.length,
                itemBuilder: (_, index) {
                  final option = options.elementAt(index);
                  return ListTile(
                    dense: true,
                    leading: Icon(
                      option.startsWith('אזור') || option == 'כל הארץ'
                          ? Icons.map_outlined
                          : Icons.location_on_outlined,
                      color: kPrimary,
                    ),
                    title: Text(option, textDirection: TextDirection.rtl),
                    onTap: () => onSelected(option),
                  );
                },
              ),
            ),
          ),
        ),
      );
}

class _StreetAutocompleteField extends StatefulWidget {
  final TextEditingController controller;
  final TextEditingController cityController;
  final ValueChanged<String>? onChanged;
  const _StreetAutocompleteField({
    required this.controller,
    required this.cityController,
    this.onChanged,
  });

  @override
  State<_StreetAutocompleteField> createState() =>
      _StreetAutocompleteFieldState();
}

class _StreetAutocompleteFieldState extends State<_StreetAutocompleteField> {
  final _focusNode = FocusNode();
  Timer? _debounce;
  List<String> _streets = const [];

  void _search(String value) {
    _debounce?.cancel();
    final city = widget.cityController.text.trim();
    if (city.isEmpty) {
      setState(() => _streets = const []);
      return;
    }
    _debounce = Timer(const Duration(milliseconds: 220), () async {
      try {
        final response = await http.get(Uri.parse('$kApi/streets').replace(
          queryParameters: {
            'city': city,
            if (value.trim().isNotEmpty) 'q': value.trim()
          },
        ));
        if (!mounted || response.statusCode != 200) return;
        final rows =
            (jsonDecode(response.body) as List).cast<Map<String, dynamic>>();
        setState(() => _streets = rows
            .map((row) => row['street']?.toString() ?? '')
            .where((street) => street.isNotEmpty)
            .toList());
      } catch (_) {}
    });
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _focusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => RawAutocomplete<String>(
        textEditingController: widget.controller,
        focusNode: _focusNode,
        optionsBuilder: (_) => _streets,
        onSelected: (street) {
          widget.controller.text = street;
          widget.onChanged?.call(street);
        },
        fieldViewBuilder: (context, controller, focusNode, onSubmitted) =>
            TextField(
          controller: controller,
          focusNode: focusNode,
          textDirection: TextDirection.rtl,
          onChanged: (value) {
            _search(value);
            widget.onChanged?.call(value);
          },
          decoration: const InputDecoration(hintText: 'הקלד שם רחוב'),
        ),
        optionsViewBuilder: (context, onSelected, options) => Align(
          alignment: Alignment.topRight,
          child: Material(
            elevation: 8,
            borderRadius: BorderRadius.circular(10),
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 260, maxWidth: 420),
              child: ListView.builder(
                padding: EdgeInsets.zero,
                shrinkWrap: true,
                itemCount: options.length,
                itemBuilder: (_, index) {
                  final street = options.elementAt(index);
                  return ListTile(
                    dense: true,
                    leading: const Icon(Icons.add_road, color: kPrimary),
                    title: Text(street, textDirection: TextDirection.rtl),
                    onTap: () => onSelected(street),
                  );
                },
              ),
            ),
          ),
        ),
      );
}

class ListingsScreen extends StatefulWidget {
  final String token;
  final Map<String, dynamic>? me;
  final io.Socket? socket;
  final Future<void> Function(Map<String, dynamic> recipient)?
      onConversationStarted;
  final int currentMainNavigationIndex;
  final ValueChanged<int> onMainNavigationSelected;
  const ListingsScreen(
      {super.key,
      required this.token,
      required this.me,
      required this.socket,
      required this.currentMainNavigationIndex,
      required this.onMainNavigationSelected,
      this.onConversationStarted});
  @override
  State<ListingsScreen> createState() => _ListingsScreenState();
}

class _ListingsScreenState extends State<ListingsScreen> {
  List<Map<String, dynamic>> _items = [];
  bool _loading = true;
  String _typeFilter = 'all'; // all / free / sale
  String _catFilter = 'הכל';
  String _cityFilter = '';
  String _queryFilter = '';
  final _searchCtrl = TextEditingController();
  Timer? _searchDebounce;
  Timer? _listingCatalogTimer;
  double? _minPrice;
  double? _maxPrice;
  String _sortFilter = 'newest';
  String _conditionFilter = 'all';
  Map<String, String> _detailFilters = {};
  double _radius = 0; // 0 = no radius filter
  Map<String, dynamic>? _selectedItem;
  bool _showPostForm = false;
  bool _showMyListings = false;

  @override
  void initState() {
    super.initState();
    _load();
    _refreshListingCatalog().then((changed) {
      if (changed && mounted) setState(() {});
    });
    _listingCatalogTimer = Timer.periodic(const Duration(minutes: 1), (_) {
      _refreshListingCatalog().then((changed) {
        if (changed && mounted) setState(() {});
      });
    });
  }

  @override
  void dispose() {
    _searchDebounce?.cancel();
    _listingCatalogTimer?.cancel();
    _searchCtrl.dispose();
    super.dispose();
  }

  void _onSearchChanged(String value) {
    setState(() {});
    _searchDebounce?.cancel();
    _searchDebounce = Timer(const Duration(milliseconds: 350), () {
      if (!mounted) return;
      _queryFilter = value.trim();
      _load();
    });
  }

  void _setQuickType(String type) {
    if (_typeFilter == type) return;
    setState(() => _typeFilter = type);
    _load();
  }

  void _clearAllFilters() {
    _searchDebounce?.cancel();
    _searchCtrl.clear();
    setState(() {
      _typeFilter = 'all';
      _catFilter = 'הכל';
      _cityFilter = '';
      _queryFilter = '';
      _minPrice = null;
      _maxPrice = null;
      _sortFilter = 'newest';
      _conditionFilter = 'all';
      _detailFilters = {};
      _radius = 0;
    });
    _load();
  }

  Future<void> _load() async {
    if (!mounted) return;
    setState(() => _loading = true);
    try {
      final params = <String, String>{'page': '1'};
      if (_typeFilter != 'all') params['type'] = _typeFilter;
      if (_catFilter != 'הכל') params['category'] = _catFilter;
      if (_cityFilter.isNotEmpty) params['city'] = _cityFilter;
      if (_queryFilter.isNotEmpty) params['q'] = _queryFilter;
      if (_minPrice != null) params['minPrice'] = _minPrice.toString();
      if (_maxPrice != null) params['maxPrice'] = _maxPrice.toString();
      if (_sortFilter != 'newest') params['sort'] = _sortFilter;
      if (_conditionFilter != 'all') params['condition'] = _conditionFilter;
      for (final entry in _detailFilters.entries) {
        if (entry.value.trim().isNotEmpty) {
          params['detail_${entry.key}'] = entry.value.trim();
        }
      }
      if (_radius > 0) params['radius'] = _radius.toStringAsFixed(0);
      final uri = Uri.parse('$kApi/listings').replace(queryParameters: params);
      final res = await http
          .get(uri, headers: {'Authorization': 'Bearer ${widget.token}'});
      if (!mounted) return;
      final data = jsonDecode(res.body);
      final items = List<Map<String, dynamic>>.from(data);
      _persistRecentImageUrls(items).ignore();
      setState(() {
        _items = items;
        if (_selectedItem != null) {
          final selectedId = _selectedItem!['id'];
          final refreshed = items.where((item) => item['id'] == selectedId);
          _selectedItem = refreshed.isEmpty ? null : refreshed.first;
        }
        _loading = false;
      });
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _openPost() async {
    if (MediaQuery.sizeOf(context).width >= 900) {
      setState(() {
        _selectedItem = null;
        _showPostForm = true;
        _showMyListings = false;
      });
      return;
    }
    final ok = await Navigator.push<bool>(
        context,
        MaterialPageRoute(
          builder: (_) => PostListingScreen(token: widget.token, me: widget.me),
        ));
    if (ok == true) {
      await _load();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('המודעה פורסמה בהצלחה')),
        );
      }
    }
  }

  Future<void> _openDetail(Map<String, dynamic> item) async {
    if (MediaQuery.sizeOf(context).width >= 900) {
      setState(() {
        _selectedItem = item;
        _showPostForm = false;
        _showMyListings = false;
      });
      return;
    }
    final updated = await Navigator.push<bool>(
        context,
        MaterialPageRoute(
          builder: (_) => ListingDetailScreen(
              item: item,
              token: widget.token,
              me: widget.me,
              socket: widget.socket,
              onConversationStarted: widget.onConversationStarted),
        ));
    if (updated == true) await _load();
  }

  @override
  Widget build(BuildContext context) {
    final listPane = Scaffold(
      backgroundColor: const Color(0xFFF5F7FA),
      appBar: AppBar(
        backgroundColor: kPrimary,
        elevation: 0,
        toolbarHeight: 72,
        titleSpacing: 16,
        title: _BrandAppBarTitle(me: widget.me),
        actions: [
          IconButton(
            icon: const Icon(Icons.format_list_bulleted, color: Colors.white),
            tooltip: 'המודעות שלי',
            onPressed: () {
              if (MediaQuery.sizeOf(context).width >= 900) {
                setState(() {
                  _selectedItem = null;
                  _showPostForm = false;
                  _showMyListings = true;
                });
              } else {
                Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => MyListingsScreen(token: widget.token),
                    ));
              }
            },
          ),
          TextButton.icon(
            onPressed: _openPost,
            icon: const Icon(Icons.add_business_outlined,
                color: Colors.white, size: 20),
            label: const Text('פרסום מתקדם',
                style: TextStyle(
                    color: Colors.white, fontWeight: FontWeight.bold)),
          ),
        ],
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(38),
          child: Container(
            color: kHeader,
            child: _MainNavigationTabs(
              currentIndex: widget.currentMainNavigationIndex,
              onSelected: widget.onMainNavigationSelected,
            ),
          ),
        ),
      ),
      body: Column(children: [
        Container(
          color: const Color(0xFFF5F7FA),
          padding: const EdgeInsets.fromLTRB(10, 10, 10, 8),
          child: Column(children: [
            TextField(
              controller: _searchCtrl,
              onChanged: _onSearchChanged,
              textDirection: TextDirection.rtl,
              decoration: InputDecoration(
                hintText: 'חיפוש במודעות... ',
                prefixIcon: const Icon(Icons.search, size: 21),
                suffixIcon: _searchCtrl.text.isEmpty
                    ? null
                    : IconButton(
                        tooltip: 'נקה חיפוש',
                        icon: const Icon(Icons.close, size: 19),
                        onPressed: () {
                          _searchCtrl.clear();
                          setState(() => _queryFilter = '');
                          _load();
                        },
                      ),
                filled: true,
                fillColor: Colors.white,
                isDense: true,
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
            const SizedBox(height: 7),
            Row(children: [
              _quickFilterChip('all', 'הכול'),
              const SizedBox(width: 5),
              _quickFilterChip('free', 'למסירה'),
              const SizedBox(width: 5),
              _quickFilterChip('sale', 'למכירה'),
              const Spacer(),
              TextButton.icon(
                onPressed: _showFilterSheet,
                icon: Icon(Icons.tune,
                    size: 18, color: _hasAdvancedFilters ? kPrimary : kSubtext),
                label: Text(
                  _hasAdvancedFilters ? 'סינון פעיל' : 'סינון',
                  style: TextStyle(
                      color: _hasAdvancedFilters ? kPrimary : kSubtext,
                      fontSize: 12),
                ),
              ),
            ]),
          ]),
        ),
        // ── List ────────────────────────────────────────────────────
        Expanded(
          child: _loading
              ? const Center(child: CircularProgressIndicator())
              : _items.isEmpty
                  ? Center(
                      child: Column(mainAxisSize: MainAxisSize.min, children: [
                      Icon(Icons.storefront_outlined,
                          size: 64, color: kSubtext),
                      const SizedBox(height: 12),
                      Text(
                          _hasAdvancedFilters
                              ? 'לא נמצאו מודעות לפי הסינון'
                              : 'אין מודעות כרגע',
                          style: TextStyle(color: kSubtext, fontSize: 16)),
                      const SizedBox(height: 8),
                      if (_hasAdvancedFilters)
                        ElevatedButton.icon(
                          onPressed: _clearAllFilters,
                          icon: const Icon(Icons.filter_alt_off_outlined),
                          label: const Text('נקה את כל המסננים'),
                        )
                      else
                        TextButton(
                            onPressed: _openPost,
                            child: const Text('פרסם ראשון!')),
                    ]))
                  : RefreshIndicator(
                      onRefresh: _load,
                      child: ListView.builder(
                        padding: const EdgeInsets.all(12),
                        itemCount: _items.length,
                        itemBuilder: (_, i) => _ListingCard(
                            item: _items[i],
                            selected: _selectedItem?['id'] == _items[i]['id'],
                            onTap: () => _openDetail(_items[i])),
                      ),
                    ),
        ),
      ]),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _openPost,
        backgroundColor: kPrimary,
        icon: const Icon(Icons.add, color: Colors.white),
        label: const Text('פרסום מתקדם', style: TextStyle(color: Colors.white)),
      ),
    );
    if (MediaQuery.sizeOf(context).width < 900) return listPane;
    return Row(children: [
      SizedBox(width: 410, child: listPane),
      const VerticalDivider(width: 1, thickness: 1, color: Color(0xFFD9DEE1)),
      Expanded(
        child: _showMyListings
            ? MyListingsScreen(
                token: widget.token,
                embedded: true,
                onClose: () => setState(() => _showMyListings = false),
              )
            : _showPostForm
                ? PostListingScreen(
                    token: widget.token,
                    me: widget.me,
                    embedded: true,
                    onClose: () => setState(() => _showPostForm = false),
                    onPublished: () async {
                      setState(() => _showPostForm = false);
                      await _load();
                      if (context.mounted) {
                        ScaffoldMessenger.of(context).showSnackBar(
                            const SnackBar(
                                content: Text('המודעה פורסמה בהצלחה')));
                      }
                    },
                  )
                : _selectedItem == null
                    ? const _DesktopListingWelcome()
                    : ListingDetailScreen(
                        key: ValueKey(_selectedItem!['id']),
                        item: _selectedItem!,
                        token: widget.token,
                        me: widget.me,
                        socket: widget.socket,
                        embedded: true,
                        onClose: () => setState(() => _selectedItem = null),
                        onUpdated: _load,
                        onConversationStarted: widget.onConversationStarted,
                      ),
      ),
    ]);
  }

  bool get _hasAdvancedFilters =>
      _typeFilter != 'all' ||
      _catFilter != 'הכל' ||
      _cityFilter.isNotEmpty ||
      _queryFilter.isNotEmpty ||
      _minPrice != null ||
      _maxPrice != null ||
      _radius > 0 ||
      _conditionFilter != 'all' ||
      _detailFilters.isNotEmpty ||
      _sortFilter != 'newest';

  Widget _quickFilterChip(String value, String label) {
    final selected = _typeFilter == value;
    return Material(
      color: selected ? kPrimary : Colors.white,
      borderRadius: BorderRadius.circular(9),
      child: InkWell(
        borderRadius: BorderRadius.circular(9),
        onTap: () => _setQuickType(value),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 7),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(9),
            border: Border.all(
                color: selected ? kPrimary : const Color(0xFFB8D4E8)),
          ),
          child: Text(label,
              style: TextStyle(
                color: selected ? Colors.white : kPrimary,
                fontSize: 12,
                fontWeight: FontWeight.w700,
              )),
        ),
      ),
    );
  }

  Widget _advancedDetailField(String category, (String, String, String) field,
      Map<String, TextEditingController> controllers,
      [VoidCallback? refresh]) {
    const options = <String, List<(String, String)>>{
      'deal_type': [('rent', 'השכרה'), ('sale', 'מכירה')],
      'property_type': [
        ('apartment', 'דירה'),
        ('house', 'בית פרטי'),
        ('garden', 'דירת גן'),
        ('penthouse', 'פנטהאוז'),
        ('duplex', 'דופלקס'),
        ('studio', 'יחידת דיור / סטודיו'),
        ('other', 'אחר')
      ],
      'transmission': [
        ('automatic', 'אוטומטית'),
        ('manual', 'ידנית'),
        ('robotic', 'רובוטית'),
        ('other', 'אחרת')
      ],
      'furniture': [
        ('none', 'ללא ריהוט'),
        ('partial', 'ריהוט חלקי'),
        ('full', 'מרוהט')
      ],
    };
    final controller =
        controllers.putIfAbsent(field.$1, () => TextEditingController());
    final values = options[field.$1];
    if (values != null) {
      final current = values.any((option) => option.$1 == controller.text)
          ? controller.text
          : null;
      return DropdownButtonFormField<String>(
        initialValue: current,
        decoration: InputDecoration(
            labelText: field.$2,
            isDense: true,
            border: const OutlineInputBorder()),
        items: [
          const DropdownMenuItem(value: '', child: Text('הכול')),
          for (final option in values)
            DropdownMenuItem(value: option.$1, child: Text(option.$2)),
        ],
        onChanged: (value) => controller.text = value ?? '',
      );
    }
    final currentValues = {
      for (final entry in controllers.entries) entry.key: entry.value.text,
    };
    return _PopularValueField(
      key: ValueKey(
          '$_listingCatalogVersion:${_popularFieldStateKey(category, field.$1, currentValues)}'),
      controller: controller,
      label: field.$2,
      hint: field.$3.isEmpty ? null : field.$3,
      options: _popularValuesFor(category, field.$1, currentValues),
      onChanged: (_) {
        _refreshCategoryDependencies(category, field.$1, controllers);
        refresh?.call();
      },
    );
  }

  void _showFilterSheet() {
    final cityCtrl = TextEditingController(text: _cityFilter);
    final queryCtrl = TextEditingController(text: _queryFilter);
    final minPriceCtrl = TextEditingController(
        text: _minPrice == null ? '' : _minPrice!.toStringAsFixed(0));
    final maxPriceCtrl = TextEditingController(
        text: _maxPrice == null ? '' : _maxPrice!.toStringAsFixed(0));
    String tmpType = _typeFilter;
    String tmpCategory = _catFilter;
    String tmpSort = _sortFilter;
    String tmpCondition = _conditionFilter;
    final detailCtrls = <String, TextEditingController>{
      for (final entry in _detailFilters.entries)
        entry.key: TextEditingController(text: entry.value),
    };
