class MyListingsScreen extends StatefulWidget {
  final String token;
  final bool embedded;
  final VoidCallback? onClose;
  const MyListingsScreen(
      {super.key, required this.token, this.embedded = false, this.onClose});
  @override
  State<MyListingsScreen> createState() => _MyListingsScreenState();
}

class _MyListingsScreenState extends State<MyListingsScreen> {
  List<Map<String, dynamic>> _items = [];
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    if (!mounted) return;
    setState(() => _loading = true);
    try {
      final res = await http.get(
        Uri.parse('$kApi/listings?mine=true'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (!mounted) return;
      setState(() {
        _items = List<Map<String, dynamic>>.from(jsonDecode(res.body));
        _loading = false;
      });
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _setStatus(String id, String status) async {
    await http.put(
      Uri.parse('$kApi/listings/$id/status'),
      headers: {
        'Authorization': 'Bearer ${widget.token}',
        'Content-Type': 'application/json'
      },
      body: jsonEncode({'status': status}),
    );
    _load();
  }

  Future<void> _edit(String id) async {
    final updated = await Navigator.push<bool>(
        context,
        MaterialPageRoute(
          builder: (_) => EditListingScreen(listingId: id, token: widget.token),
        ));
    if (updated == true) _load();
  }

  Future<void> _delete(String id) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('מחיקת מודעה'),
        content: const Text('למחוק את המודעה לצמיתות?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('ביטול')),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(context, true),
            child: const Text('מחק', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
    if (ok != true) return;
    await http.delete(
      Uri.parse('$kApi/listings/$id'),
      headers: {'Authorization': 'Bearer ${widget.token}'},
    );
    _load();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF5F7FA),
      appBar: AppBar(
        backgroundColor: kPrimary,
        title: const Text('המודעות שלי',
            style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
        leading: BackButton(
          color: Colors.white,
          onPressed: widget.embedded
              ? widget.onClose
              : () => Navigator.maybePop(context),
        ),
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _items.isEmpty
              ? Center(
                  child: Column(mainAxisSize: MainAxisSize.min, children: [
                  Icon(Icons.storefront_outlined, size: 64, color: kSubtext),
                  const SizedBox(height: 12),
                  Text('עדיין אין לך מודעות',
                      style: TextStyle(color: kSubtext, fontSize: 16)),
                ]))
              : RefreshIndicator(
                  onRefresh: _load,
                  child: ListView.builder(
                    padding: const EdgeInsets.all(12),
                    itemCount: _items.length,
                    itemBuilder: (_, i) => _MyListingCard(
                      item: _items[i],
                      onPause: () => _setStatus(_items[i]['id'], 'paused'),
                      onResume: () => _setStatus(_items[i]['id'], 'active'),
                      onComplete: () => _setStatus(_items[i]['id'],
                          _items[i]['type'] == 'free' ? 'given' : 'sold'),
                      onDelete: () => _delete(_items[i]['id']),
                      onEdit: () => _edit(_items[i]['id']),
                    ),
                  ),
                ),
    );
  }
}

