            Icon(Icons.visibility_outlined, size: 15, color: kSubtext),
            const SizedBox(width: 3),
            Text('${item['view_count'] ?? 0}',
                style: TextStyle(fontSize: 13, color: kSubtext)),
            const SizedBox(width: 12),
            Icon(Icons.chat_bubble_outline, size: 15, color: kSubtext),
            const SizedBox(width: 3),
            Text('${item['contact_count'] ?? 0}',
                style: TextStyle(fontSize: 13, color: kSubtext)),
            const Spacer(),
            _actionBtn('ערוך', const Color(0xFFE0F2FE), const Color(0xFF0369A1),
                onEdit),
            const SizedBox(width: 6),
            if (isActive) ...[
              _actionBtn('הקפא', const Color(0xFFFFF3CD),
                  const Color(0xFF7A5200), onPause),
              const SizedBox(width: 6),
              _actionBtn(isFree ? 'נמסר' : 'נמכר', const Color(0xFFD1FAE5),
                  const Color(0xFF065F46), onComplete),
              const SizedBox(width: 6),
            ] else if (status == 'paused') ...[
              _actionBtn('הפעל מחדש', const Color(0xFFD1FAE5),
                  const Color(0xFF065F46), onResume),
              const SizedBox(width: 6),
            ],
            _actionBtn('מחק', const Color(0xFFFEE2E2), const Color(0xFF991B1B),
                onDelete),
          ]),
        ]),
      ),
    );
  }

  Widget _imgPlaceholder() => Container(
      width: 66,
      height: 66,
      decoration: BoxDecoration(
          color: const Color(0xFFE8F4FD),
          borderRadius: BorderRadius.circular(8)),
      child: Icon(Icons.image_outlined, color: kSubtext, size: 28));

  Widget _badge(String text, Color bg, Color fg) => Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
      decoration:
          BoxDecoration(color: bg, borderRadius: BorderRadius.circular(10)),
      child: Text(text,
          style:
              TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: fg)));

  Widget _actionBtn(String label, Color bg, Color fg, VoidCallback onTap) =>
      GestureDetector(
          onTap: onTap,
          child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
              decoration: BoxDecoration(
                  color: bg, borderRadius: BorderRadius.circular(8)),
              child: Text(label,
                  style: TextStyle(
                      fontSize: 12, fontWeight: FontWeight.w600, color: fg))));
}

// ── Post Listing Screen ───────────────────────────────────────────
class _PropertyEntryDateField extends StatelessWidget {
  final TextEditingController controller;
  final VoidCallback onChanged;
  const _PropertyEntryDateField({
    required this.controller,
    required this.onChanged,
  });

  DateTime? _currentDate() {
    final parts = controller.text.split('/');
    if (parts.length != 3) return null;
    final day = int.tryParse(parts[0]);
    final month = int.tryParse(parts[1]);
    final year = int.tryParse(parts[2]);
    if (day == null || month == null || year == null) return null;
    final value = DateTime(year, month, day);
    return value.day == day && value.month == month && value.year == year
        ? value
        : null;
  }

  @override
  Widget build(BuildContext context) => Row(children: [
        Expanded(
          child: InkWell(
            onTap: () async {
              final now = DateTime.now();
              final selected = await showDatePicker(
                context: context,
                initialDate: _currentDate() ?? now,
                firstDate: now.subtract(const Duration(days: 365)),
                lastDate: DateTime(now.year + 10, 12, 31),
                helpText: 'בחירת תאריך כניסה',
                cancelText: 'ביטול',
                confirmText: 'בחירה',
              );
              if (selected == null) return;
              controller.text =
                  '${selected.day.toString().padLeft(2, '0')}/${selected.month.toString().padLeft(2, '0')}/${selected.year}';
              onChanged();
            },
            child: InputDecorator(
              decoration: const InputDecoration(
                labelText: 'תאריך כניסה',
                prefixIcon: Icon(Icons.event_outlined),
                border: OutlineInputBorder(),
              ),
              child: Text(
                controller.text.isEmpty ? 'בחר תאריך' : controller.text,
                textDirection: TextDirection.ltr,
              ),
            ),
          ),
        ),
        const SizedBox(width: 6),
        OutlinedButton(
          onPressed: () {
            controller.text = 'מיידי';
            onChanged();
          },
          child: const Text('מיידי'),
        ),
      ]);
}

