  final List<_FileUploadOutcome?> _imageOutcomes =
      List<_FileUploadOutcome?>.filled(8, null);
  final List<String?> _imageReasons = List<String?>.filled(8, null);
  bool _saving = false;
  bool _vehicleLookupLoading = false;
