  Widget _categoryDetailField((String, String, String) field) {
    final currentValues = {
      for (final entry in _categoryDetailCtrls.entries)
        entry.key: entry.value.text,
    };
    return _PopularValueField(
      key: ValueKey(
          '$_listingCatalogVersion:${_popularFieldStateKey(_category, field.$1, currentValues)}'),
      controller:
          _categoryDetailCtrls.putIfAbsent(field.$1, TextEditingController.new),
      label: field.$2,
      hint: field.$3.isEmpty ? null : field.$3,
      options: _popularValuesFor(_category, field.$1, currentValues),
      onChanged: (_) => setState(() {
        _refreshCategoryDependencies(_category, field.$1, _categoryDetailCtrls);
        _updateGeneratedCategoryText();
      }),
    );
  }

  Map<String, String> _vehicleTextValues() => {
        'manufacturer': _vehicleManufacturerCtrl.text,
        'model': _vehicleModelCtrl.text,
        'year': _vehicleYearCtrl.text,
        'mileage': _vehicleMileageCtrl.text,
        'hand': _vehicleHandCtrl.text,
        'fuel': _vehicleFuelCtrl.text,
        'color': _vehicleColorCtrl.text,
        'test_valid_until': _vehicleTestCtrl.text,
        'transmission': {
              'automatic': 'אוטומטית',
              'manual': 'ידנית',
              'robotic': 'רובוטית',
              'other': 'אחרת',
            }[_vehicleTransmission] ??
            _vehicleTransmission,
        for (final entry in _vehicleExtraCtrls.entries)
          entry.key: entry.value.text,
      };

  void _updateGeneratedVehicleText() {
    if (_category != 'רכב') return;
    final generated = _generatedVehicleListingText(_vehicleTextValues());
    final mayReplaceTitle = !_titleManuallyEdited;
    final mayReplaceDescription = !_descriptionManuallyEdited;
    _generatedVehicleTitle = generated.$1;
    _generatedVehicleDescription = generated.$2;
    if (mayReplaceTitle && generated.$1.isNotEmpty) {
      _titleCtrl.text = generated.$1;
    }
    if (mayReplaceDescription && generated.$2.isNotEmpty) {
      _descCtrl.value = TextEditingValue(
        text: generated.$2,
        selection: TextSelection.collapsed(offset: generated.$2.length),
      );
      _mirroredTitle = generated.$1;
    }
  }

  void _listenToVehicleFields() {
    for (final controller in <TextEditingController>[
      _vehicleManufacturerCtrl,
      _vehicleModelCtrl,
      _vehicleYearCtrl,
      _vehicleMileageCtrl,
      _vehicleHandCtrl,
      _vehicleFuelCtrl,
      _vehicleColorCtrl,
      _vehicleTestCtrl,
      ..._vehicleExtraCtrls.values,
    ]) {
      controller.addListener(_updateGeneratedVehicleText);
    }
  }

  void _updateGeneratedCategoryText() {
    if (_category == 'רכב') {
      _updateGeneratedVehicleText();
      return;
    }
    final values = <String, String>{
      for (final entry in _categoryDetailCtrls.entries)
        entry.key: entry.value.text,
    };
    (String, String) generated;
    if (_category == 'נדל״ן') {
      generated = _generatedPropertyListingText({
        'deal_type': _propertyDealType,
        'property_type': _propertyType,
        'street': _propertyStreetCtrl.text,
        'city': _cityCtrl.text,
        'rooms': _propertyRoomsCtrl.text,
        'area_sqm': _propertyAreaCtrl.text,
        'floor': _propertyFloorCtrl.text,
        'total_floors': _propertyTotalFloorsCtrl.text,
        'entry_date': _propertyEntryCtrl.text,
        'furniture': _propertyFurniture,
        'arnona': _propertyArnonaCtrl.text,
        'building_fee': _propertyVaadCtrl.text,
        'features': [
          if (_propertyParking) 'חניה',
          if (_propertyElevator) 'מעלית',
          if (_propertyMamad) 'ממ״ד',
          if (_propertyBalcony) 'מרפסת',
          if (_propertyAccessible) 'נגישות',
          if (_propertyStorage) 'מחסן',
          if (_propertyAirConditioning) 'מיזוג',
          if (_propertyPets) 'אפשר בעלי חיים',
        ].join(', '),
      });
    } else {
      generated = _generatedCategoryListingText(_category, values);
    }
    final replaceTitle = !_titleManuallyEdited;
    final replaceDescription = !_descriptionManuallyEdited;
    _generatedVehicleTitle = generated.$1;
    _generatedVehicleDescription = generated.$2;
    if (replaceTitle && generated.$1.isNotEmpty) _titleCtrl.text = generated.$1;
    if (replaceDescription && generated.$2.isNotEmpty) {
      _descCtrl.value = TextEditingValue(
        text: generated.$2,
        selection: TextSelection.collapsed(offset: generated.$2.length),
      );
      _mirroredTitle = generated.$1;
    }
  }

  void _listenToAllListingFields() {
    for (final controller in <TextEditingController>[
      ..._categoryDetailCtrls.values.toSet(),
      _cityCtrl,
      _propertyStreetCtrl,
      _propertyRoomsCtrl,
      _propertyFloorCtrl,
      _propertyTotalFloorsCtrl,
      _propertyAreaCtrl,
      _propertyEntryCtrl,
      _propertyArnonaCtrl,
      _propertyVaadCtrl,
    ]) {
      controller.addListener(_updateGeneratedCategoryText);
    }
  }

  void _changeCategory(String? category) {
    if (category == null || category == _category) return;
    setState(() {
      _category = category;
      _titleManuallyEdited = false;
      _descriptionManuallyEdited = false;
      _generatedVehicleTitle = '';
      _generatedVehicleDescription = '';
      _mirroredTitle = '';
      _titleCtrl.clear();
      _descCtrl.clear();
    });
  }

  @override
  void initState() {
    super.initState();
    _titleCtrl.addListener(_mirrorTitleIntoDescription);
    _listenToVehicleFields();
    _listenToAllListingFields();
    if (_cityCtrl.text.trim().isEmpty) _loadCityFromProfile();
    _refreshListingCatalog().then((changed) {
      if (changed && mounted) setState(() {});
    });
    _listingCatalogTimer = Timer.periodic(const Duration(minutes: 1), (_) {
      _refreshListingCatalog().then((changed) {
        if (changed && mounted) setState(() {});
      });
    });
  }

  void _mirrorTitleIntoDescription() {
    final title = _titleCtrl.text.trim();
    final current = _descCtrl.text;
    String? updated;
    if (_mirroredTitle.isEmpty && current.trim().isEmpty) {
      updated = title;
    } else if (current.trim() == _mirroredTitle) {
      updated = title;
    } else if (_mirroredTitle.isNotEmpty &&
        current.startsWith('$_mirroredTitle\n\n')) {
      final remainder = current.substring(_mirroredTitle.length + 2);
      updated = title.isEmpty ? remainder : '$title\n\n$remainder';
    }
    _mirroredTitle = title;
    if (updated != null && updated != current) {
      _descCtrl.value = TextEditingValue(
        text: updated,
        selection: TextSelection.collapsed(offset: updated.length),
      );
    }
  }

  Future<void> _loadCityFromProfile() async {
    try {
      final response = await http.get(Uri.parse('$kApi/profile'),
          headers: {'Authorization': 'Bearer ${widget.token}'});
      if (!mounted || response.statusCode != 200 || _cityCtrl.text.isNotEmpty) {
        return;
      }
      final profile = jsonDecode(response.body);
      final city = profile is Map ? profile['city']?.toString().trim() : null;
      if (city != null && city.isNotEmpty) {
        setState(() => _cityCtrl.text = city);
      } else {
        await _loadCityFromDevice();
      }
    } catch (_) {
      await _loadCityFromDevice();
    }
  }

  Future<void> _loadCityFromDevice() async {
    if (!mounted || _cityCtrl.text.trim().isNotEmpty) return;
    try {
      var permission = await Geolocator.checkPermission();
      if (permission == LocationPermission.denied) {
        permission = await Geolocator.requestPermission();
      }
      if (permission == LocationPermission.denied ||
          permission == LocationPermission.deniedForever) {
        return;
      }
      final position = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.low,
          timeLimit: Duration(seconds: 10),
        ),
      );
      final response = await http.put(
        Uri.parse('$kApi/location/city'),
        headers: {
          'Authorization': 'Bearer ${widget.token}',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'latitude': position.latitude,
          'longitude': position.longitude,
        }),
      );
      if (!mounted || response.statusCode != 200) return;
      final payload = jsonDecode(response.body);
      final city = payload is Map ? payload['city']?.toString().trim() : null;
      if (city != null && city.isNotEmpty && _cityCtrl.text.trim().isEmpty) {
        setState(() => _cityCtrl.text = city);
      }
    } catch (_) {
      // The locality can always be selected manually when location is denied.
    }
  }

  Future<void> _lookupVehicle() async {
    final plate = _plateCtrl.text.replaceAll(RegExp(r'\D'), '');
    if (plate.length != 7 && plate.length != 8) {
      setState(() => _vehicleLookupMessage = 'יש להזין 7 או 8 ספרות');
      return;
    }
    setState(() {
      _vehicleLookupLoading = true;
      _vehicleLookupMessage = null;
    });
    try {
      final response = await http.get(
        Uri.parse('$kApi/vehicles/$plate'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      ).timeout(const Duration(seconds: 12));
      if (!mounted) return;
      final payload = jsonDecode(response.body);
      if (response.statusCode != 200 || payload is! Map) {
        setState(() => _vehicleLookupMessage = payload is Map
            ? (payload['error']?.toString() ?? 'הרכב לא נמצא')
            : 'הרכב לא נמצא');
        return;
      }
      final details = Map<String, dynamic>.from(payload['details'] as Map);
      _vehicleManufacturerCtrl.text = details['manufacturer']?.toString() ?? '';
      _vehicleModelCtrl.text = details['model']?.toString() ?? '';
      _vehicleYearCtrl.text = details['year']?.toString() ?? '';
      _vehicleFuelCtrl.text = details['fuel']?.toString() ?? '';
      _vehicleColorCtrl.text = details['color']?.toString() ?? '';
      _vehicleTestCtrl.text = details['test_valid_until']?.toString() ?? '';
      _vehicleExtraCtrls['trim']?.text = details['trim']?.toString() ?? '';
      _vehicleExtraCtrls['ownership']?.text =
          details['ownership']?.toString() ?? '';
      _vehicleExtraCtrls['registration_date']?.text =
          details['road_date']?.toString() ?? '';
      if (_titleCtrl.text.trim().isEmpty) {
        _titleCtrl.text = [
          _vehicleManufacturerCtrl.text,
          _vehicleModelCtrl.text,
          _vehicleYearCtrl.text,
        ].where((value) => value.trim().isNotEmpty).join(' ');
      }
      setState(() => _vehicleLookupMessage =
          'הפרטים אותרו במאגר משרד התחבורה — מומלץ לבדוק אותם');
    } catch (_) {
      if (mounted) {
        setState(() => _vehicleLookupMessage =
            'לא ניתן לבדוק כרגע; אפשר למלא את הפרטים ידנית');
      }
    } finally {
      if (mounted) setState(() => _vehicleLookupLoading = false);
    }
  }

  void _onPlateChanged(String value) {
    _plateLookupTimer?.cancel();
    final plate = value.replaceAll(RegExp(r'\D'), '');
    if (plate.length == 7 || plate.length == 8) {
      _plateLookupTimer =
          Timer(const Duration(milliseconds: 650), _lookupVehicle);
    }
  }

  Future<void> _pickImage(int slot) async {
    final picker = ImagePicker();
    final picked = await picker.pickMultiImage(imageQuality: 80);
    if (picked.isEmpty || !mounted) return;
    final availableSlots = <int>[
      slot,
      for (var i = 0; i < _imageUrls.length; i++)
        if (i != slot && _imageUrls[i] == null) i,
    ];
    final selected = picked.take(availableSlots.length).toList();
    if (picked.length > availableSlots.length) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('ניתן לצרף עד 8 תמונות למודעה'),
      ));
    }
    setState(() {
      for (var i = 0; i < selected.length; i++) {
        _uploadingSlot[availableSlots[i]] = true;
      }
    });
    final completed = ValueNotifier<int>(0);
    try {
      final results = await _runImageUploadQueue(
        selected,
        (file) => _uploadFileRequest(
          file: file,
          fileName: file.name,
          token: widget.token,
          fields: const {'listingImage': 'true'},
        ),
        completed,
      );
      if (!mounted) return;
      setState(() {
        for (var i = 0; i < results.length; i++) {
          final target = availableSlots[i];
          final result = results[i];
          final url = result.data['url']?.toString();
          _imageOutcomes[target] = result.outcome;
          _imageReasons[target] =
              result.data['reason']?.toString() ?? result.error;
          // The server keeps rejected/pending uploads for moderation. Show the
          // returned image to its owner, but only approved URLs are published.
          if (url != null && url.isNotEmpty) _imageUrls[target] = url;
        }
      });
      _showImageBatchSummary(context, results);
    } catch (error) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('שגיאה בהעלאת תמונה: $error')));
      }
    } finally {
      completed.dispose();
      if (mounted) {
        setState(() {
          for (var i = 0; i < selected.length; i++) {
            _uploadingSlot[availableSlots[i]] = false;
          }
        });
      }
    }
  }

  Future<void> _removeImage(int slot) async {
    if (_imageUrls[slot] == null) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('מחיקת תמונה'),
        content: const Text(
            'להסיר את התמונה מהמודעה? המחיקה תושלם לאחר לחיצה על „שמור שינויים”.'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('ביטול'),
          ),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(dialogContext, true),
            icon: const Icon(Icons.delete_outline, color: Colors.white),
            label:
                const Text('הסר תמונה', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
    if (confirmed == true && mounted) {
      setState(() {
        _imageUrls[slot] = null;
        _imageOutcomes[slot] = null;
        _imageReasons[slot] = null;
      });
    }
  }

  Future<void> _submit() async {
    if (!_contactInApp && !_contactEmail && !_contactPhone && !_contactPhone) {
      ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('יש לבחור לפחות דרך אחת ליצירת קשר')));
      return;
    }
    if (_titleCtrl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('נדרשת כותרת')));
      return;
    }
    if (_descCtrl.text.trim().length < 10) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text('יש להוסיף תיאור ברור של לפחות 10 תווים')));
      return;
    }
    final priceText = _priceCtrl.text.trim();
    final parsedPrice = priceText.isEmpty ? 0.0 : double.tryParse(priceText);
    if (parsedPrice == null || parsedPrice < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('יש להזין מחיר תקין, 0 או יותר')));
      return;
    }
    if (_category == 'נדל״ן' &&
        (parsedPrice <= 0 ||
            _propertyRoomsCtrl.text.trim().isEmpty ||
            _propertyAreaCtrl.text.trim().isEmpty)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text('במודעת נדל״ן נדרשים מחיר, מספר חדרים ושטח במ״ר')));
      return;
    }
    final listingType = parsedPrice == 0 ? 'free' : 'sale';
    if (_cityCtrl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('יש להזין עיר או אזור')));
      return;
    }
    setState(() => _saving = true);
    try {
      final urls = <String>[];
      for (var i = 0; i < _imageUrls.length; i++) {
        if (_imageUrls[i] != null &&
            _imageOutcomes[i] == _FileUploadOutcome.approved) {
          urls.add(_imageUrls[i]!);
        }
      }
      final city = _cityCtrl.text.trim();
      final title = _titleCtrl.text.trim();
      final enteredDescription = _descCtrl.text.trim();
      final description = enteredDescription.startsWith(title)
          ? enteredDescription
          : '$title\n\n$enteredDescription';
      final body = <String, dynamic>{
        'type': listingType,
        'title': title,
        'description': description,
        'category': _category,
        'item_condition': _condition,
        'negotiable': listingType == 'sale' && _negotiable,
        'quantity': int.tryParse(_quantityCtrl.text) ?? 1,
        'delivery_method': _deliveryMethod,
        'pickup_details': _pickupCtrl.text.trim(),
        'contact_phone_visible': _contactPhone,
        'contact_preferences': {
          'in_app': _contactInApp,
          'email': _contactEmail,
          'phone': _contactPhone,
          'contact_hours': _contactHoursCtrl.text.trim(),
        },
        'expires_in_days': _expiryDays,
        if (city.isNotEmpty) 'city': city,
        if (urls.isNotEmpty) 'image_urls': urls,
        if (_category == 'רכב' && _plateCtrl.text.trim().isNotEmpty)
          'license_plate': _plateCtrl.text,
        if (_category == 'רכב')
          'vehicle_details': {
            'manufacturer': _vehicleManufacturerCtrl.text.trim(),
            'model': _vehicleModelCtrl.text.trim(),
            'year': _vehicleYearCtrl.text.trim(),
            'mileage': _vehicleMileageCtrl.text.trim(),
            'hand': _vehicleHandCtrl.text.trim(),
            'transmission': _vehicleTransmission,
            'fuel': _vehicleFuelCtrl.text.trim(),
            'color': _vehicleColorCtrl.text.trim(),
            'test_valid_until': _vehicleTestCtrl.text.trim(),
            for (final entry in _vehicleExtraCtrls.entries)
              if (entry.value.text.trim().isNotEmpty)
                entry.key: entry.value.text.trim(),
          },
        if (_category == 'נדל״ן')
          'property_details': {
            'deal_type': _propertyDealType,
            'property_type': _propertyType,
            'street': _propertyStreetCtrl.text.trim(),
            'rooms': _propertyRoomsCtrl.text.trim(),
            'floor': _propertyFloorCtrl.text.trim(),
            'total_floors': _propertyTotalFloorsCtrl.text.trim(),
            'area_sqm': _propertyAreaCtrl.text.trim(),
            'entry_date': _propertyEntryCtrl.text.trim(),
            'arnona': _propertyArnonaCtrl.text.trim(),
            'building_fee': _propertyVaadCtrl.text.trim(),
            'furniture': _propertyFurniture,
            'parking': _propertyParking,
            'elevator': _propertyElevator,
            'mamad': _propertyMamad,
            'balcony': _propertyBalcony,
            'accessible': _propertyAccessible,
            'storage': _propertyStorage,
            'air_conditioning': _propertyAirConditioning,
            'pets_allowed': _propertyPets,
          },
        if (_category != 'רכב' && _category != 'נדל״ן')
          'category_details': _categoryDetailsPayload(),
      };
      body['price'] = parsedPrice;
      final res = await http
          .post(
            Uri.parse('$kApi/listings'),
            headers: {
              'Authorization': 'Bearer ${widget.token}',
              'Content-Type': 'application/json'
            },
            body: jsonEncode(body),
          )
          .timeout(const Duration(seconds: 30));
      if (!mounted) return;
      if (res.statusCode == 200) {
        if (widget.embedded) {
          await widget.onPublished?.call();
        } else {
          Navigator.pop(context, true);
        }
        return;
      }
      var message = 'פרסום המודעה נכשל';
      try {
        final response = jsonDecode(res.body);
        if (response is Map && response['error'] != null) {
          message = response['error'].toString();
        }
      } catch (_) {}
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('$message (${res.statusCode})')),
      );
    } catch (error) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('פרסום המודעה נכשל: $error')),
        );
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  void dispose() {
    _titleCtrl.removeListener(_mirrorTitleIntoDescription);
    _titleCtrl.dispose();
    _descCtrl.dispose();
    _priceCtrl.dispose();
    _quantityCtrl.dispose();
    _pickupCtrl.dispose();
    _contactHoursCtrl.dispose();
    _plateLookupTimer?.cancel();
    _listingCatalogTimer?.cancel();
    _plateCtrl.dispose();
    _vehicleManufacturerCtrl.dispose();
    _vehicleModelCtrl.dispose();
    _vehicleYearCtrl.dispose();
    _vehicleMileageCtrl.dispose();
    _vehicleHandCtrl.dispose();
    _vehicleFuelCtrl.dispose();
    _vehicleColorCtrl.dispose();
    _vehicleTestCtrl.dispose();
    for (final controller in _vehicleExtraCtrls.values) {
      controller.dispose();
    }
    _propertyStreetCtrl.dispose();
    _propertyRoomsCtrl.dispose();
    _propertyFloorCtrl.dispose();
    _propertyTotalFloorsCtrl.dispose();
    _propertyAreaCtrl.dispose();
    _propertyEntryCtrl.dispose();
    _propertyArnonaCtrl.dispose();
    _propertyVaadCtrl.dispose();
    for (final controller in _categoryDetailCtrls.values.toSet()) {
      controller.dispose();
    }
    _cityCtrl.dispose();
    super.dispose();
  }

