// Retained as the compact variant for narrow layouts.
// ignore: unused_element
class _BlockedReceivingFilterIcons extends StatelessWidget {
  final Map<String, bool>? filter;
  final bool forGroup;
  final bool onHeader;
  final bool blockedForSending;

  const _BlockedReceivingFilterIcons({
    required this.filter,
    // ignore: unused_element_parameter
    this.forGroup = false,
    // ignore: unused_element_parameter
    this.onHeader = true,
    // ignore: unused_element_parameter
    this.blockedForSending = false,
  });

  static const _items = <String, (IconData, String)>{
    'text': (Icons.comments_disabled_outlined, 'לא מוכן לקבל הודעות טקסט'),
    'video': (Icons.videocam_off_outlined, 'לא מוכן לקבל סרטוני וידאו'),
    'nonHumanImages': (
      Icons.image_not_supported_outlined,
      'לא מוכן לקבל תמונות נוף או חפצים'
    ),
    'men': (Icons.man, 'לא מוכן לקבל תמונות גברים'),
    'women': (Icons.woman, 'לא מוכן לקבל תמונות נשים'),
    'children': (Icons.child_care, 'לא מוכן לקבל תמונות ילדים'),
  };

  @override
  Widget build(BuildContext context) {
    final blocked =
        _items.entries.where((entry) => filter?[entry.key] == false).toList();
    if (blocked.isEmpty) return const SizedBox.shrink();
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: blocked
          .map((entry) => Tooltip(
                message: blockedForSending
                    ? entry.value.$2
                        .replaceFirst('לא מוכן לקבל', 'אי אפשר לשלוח')
                    : forGroup
                        ? entry.value.$2
                            .replaceFirst('לא מוכן', 'הקבוצה לא מוכנה')
                        : entry.value.$2,
                child: Padding(
                  padding: const EdgeInsetsDirectional.only(start: 3),
                  child: Container(
                    width: 22,
                    height: 22,
                    decoration: BoxDecoration(
                      color: onHeader
                          ? (blockedForSending
                              ? const Color(0xFFE58A00)
                              : const Color(0xFFD84343))
                          : (blockedForSending
                              ? const Color(0xFFFFF0D6)
                              : const Color(0xFFFFE7E7)),
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: onHeader ? Colors.white70 : Colors.red.shade300,
                        width: 0.8,
                      ),
                    ),
                    alignment: Alignment.center,
                    child: Icon(entry.value.$1,
                        size: 15,
                        color: onHeader
                            ? Colors.white
                            : blockedForSending
                                ? Colors.orange.shade800
                                : Colors.red.shade700),
                  ),
                ),
              ))
          .toList(),
    );
  }
}

Future<Map<String, bool>?> _chooseGroupInvitationFilter(
  BuildContext context, {
  required Map<String, bool> groupFilter,
  required Map<String, bool> initialFilter,
  String counterpart = 'הקבוצה',
  String? groupName,
}) {
  final selected = Map<String, bool>.from(initialFilter);
  final normalizedGroupName = groupName?.trim() ?? '';
  final targetLabel =
      normalizedGroupName.isEmpty ? counterpart : normalizedGroupName;
  return showDialog<Map<String, bool>>(
    context: context,
    barrierDismissible: false,
    builder: (dialogContext) => StatefulBuilder(
      builder: (context, setDialogState) => AlertDialog(
        title: Text('בחירת התוכן שאקבל מהקבוצה $targetLabel'),
        content: SizedBox(
          width: 760,
          child: SingleChildScrollView(
            child: _InvitationFilterComparisonTable(
              groupName: groupName,
              groupFilter: groupFilter,
              personalFilter: selected,
              onPersonalFilterChanged: (updated) => setDialogState(() {
                selected
                  ..clear()
                  ..addAll(updated);
              }),
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('ביטול'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.pop(dialogContext, selected),
            icon: const Icon(Icons.group_add_outlined),
            label: const Text('אשר והצטרף'),
          ),
        ],
      ),
    ),
  );
}

class _InvitationFilterComparisonTable extends StatelessWidget {
  final String? groupName;
  final Map<String, bool>? groupFilter;
  final Map<String, bool>? personalFilter;
  final ValueChanged<Map<String, bool>>? onPersonalFilterChanged;
  final ValueChanged<Map<String, bool>>? onCounterpartFilterChanged;
  final String counterpartKind;
  final IconData counterpartIcon;
  final bool showCounterpartFilter;
  final String? hiddenCounterpartExplanation;

  const _InvitationFilterComparisonTable({
    this.groupName,
    required this.groupFilter,
    required this.personalFilter,
    this.onPersonalFilterChanged,
    this.onCounterpartFilterChanged,
    this.counterpartKind = 'הקבוצה',
    this.counterpartIcon = Icons.groups_outlined,
    this.showCounterpartFilter = true,
    this.hiddenCounterpartExplanation,
  });

  static const _items = <String, (IconData, String, String)>{
    'text': (Icons.text_fields, 'טקסט', 'הודעות טקסט רגילות'),
    'nonHumanImages': (
      Icons.landscape_outlined,
      'תמונות נוף או חפצים',
      'חפצים, נוף, צמחים ובעלי חיים'
    ),
    'men': (Icons.man, 'גברים', 'תמונות שסווגו כתמונות גברים'),
    'women': (Icons.woman, 'נשים', 'תמונות שסווגו כתמונות נשים'),
    'children': (Icons.child_care, 'ילדים', 'תמונות שסווגו כתמונות ילדים'),
    'video': (Icons.videocam_outlined, 'וידאו', 'סרטונים שעברו סריקה וסיווג'),
  };

  List<String> get _visibleKeys {
    final available = <String>{
      ...?groupFilter?.keys,
      ...?personalFilter?.keys,
    };
    return [
      ..._items.keys.where(available.contains),
      ...available.where((key) => !_items.containsKey(key)).toList()..sort(),
    ];
  }

  (IconData, String, String) _itemFor(String key) =>
      _items[key] ??
      (Icons.filter_alt_outlined, key, 'סוג תוכן נוסף בהגדרות הסינון');

  @override
  Widget build(BuildContext context) {
    if (personalFilter == null ||
        (showCounterpartFilter && groupFilter == null)) {
      return const Padding(
        padding: EdgeInsets.symmetric(vertical: 10),
        child: Center(child: CircularProgressIndicator(strokeWidth: 2)),
      );
    }
    Widget cell(
      Widget child, {
      int flex = 1,
      AlignmentGeometry alignment = AlignmentDirectional.centerStart,
    }) =>
        Expanded(
          flex: flex,
          child: Container(
            alignment: alignment,
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 7),
            child: child,
          ),
        );

    final namedCounterpart = groupName?.trim() ?? '';
    final explanation = !showCounterpartFilter
        ? hiddenCounterpartExplanation ??
            (namedCounterpart.isEmpty
                ? 'בחרו איזה תוכן תהיו מוכנים לקבל מהחבר.'
                : 'בחרו איזה תוכן תהיו מוכנים לקבל מ$namedCounterpart.')
        : counterpartKind == 'החבר'
            ? namedCounterpart.isEmpty
                ? 'העמודה הראשונה מציגה מה מותר לשלוח לחבר. בעמודה השנייה תוכלו לבחור איזה תוכן תהיו מוכנים לקבל ממנו.'
                : 'העמודה הראשונה מציגה מה מותר לשלוח ל$namedCounterpart. בעמודה השנייה תוכלו לבחור איזה תוכן תהיו מוכנים לקבל ממנו.'
            : namedCounterpart.isEmpty
                ? 'העמודה הראשונה מציגה מה מותר לשלוח בקבוצה. בעמודה השנייה תוכלו לבחור איזה תוכן תהיו מוכנים לקבל ממנה.'
                : 'העמודה הראשונה מציגה מה מותר לשלוח בקבוצה $namedCounterpart. בעמודה השנייה תוכלו לבחור איזה תוכן תהיו מוכנים לקבל ממנה.';

    final counterpartTarget = counterpartKind == 'החבר'
        ? namedCounterpart.isEmpty
            ? 'ל - חבר'
            : 'ל - $namedCounterpart'
        : namedCounterpart.isEmpty
            ? 'ל - קבוצה'
            : 'ל - $namedCounterpart';
    final personalTarget = counterpartKind == 'החבר'
        ? namedCounterpart.isEmpty
            ? 'מ - חבר'
            : 'מ - $namedCounterpart'
        : namedCounterpart.isEmpty
            ? 'מ - קבוצה'
            : 'מ - $namedCounterpart';

    Widget filterHeader(String title, String target) => Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(title,
                textAlign: TextAlign.center,
                style: const TextStyle(
                    fontSize: 13, fontWeight: FontWeight.w800, height: 1.2)),
            const SizedBox(height: 2),
            Text(target,
                textAlign: TextAlign.center,
                style: const TextStyle(
                    fontSize: 12, fontWeight: FontWeight.w800, height: 1.2)),
          ],
        );

    Widget status(bool allowed, {bool editable = false, VoidCallback? onTap}) {
      if (!editable) {
        final color = allowed ? Colors.green.shade700 : Colors.red.shade700;
        return Semantics(
          label: allowed ? 'מותר, לקריאה בלבד' : 'חסום, לקריאה בלבד',
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Icon(allowed ? Icons.check_circle : Icons.block,
                size: 23, color: color),
            const SizedBox(width: 7),
            Text(allowed ? 'מותר' : 'חסום',
                style: TextStyle(
                    fontSize: 12, fontWeight: FontWeight.w700, color: color)),
          ]),
        );
      }
      final color = allowed ? kPrimary : Colors.red.shade600;
      return InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(10),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 3),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                width: 27,
                height: 27,
                decoration: BoxDecoration(
                  color: allowed ? kPrimary : Colors.white,
                  borderRadius: BorderRadius.circular(7),
                  border: Border.all(
                    color: allowed ? kPrimary : const Color(0xFFAFC9DA),
                    width: 1.5,
                  ),
                ),
                child: allowed
                    ? const Icon(Icons.check, size: 19, color: Colors.white)
                    : null,
              ),
              const SizedBox(width: 7),
              Text(allowed ? 'מותר' : 'חסום',
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: color,
                  )),
            ],
          ),
        ),
      );
    }

    return Directionality(
      textDirection: TextDirection.rtl,
      child: Align(
        alignment: Alignment.topCenter,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 680),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              if (groupName != null && groupName!.trim().isNotEmpty) ...[
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
                  decoration: BoxDecoration(
                    color: const Color(0xFFEAF6FD),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: const Color(0xFFB9D8ED)),
                  ),
                  child: Row(children: [
                    Icon(counterpartIcon, color: kPrimary, size: 20),
                    const SizedBox(width: 8),
                    Expanded(
                        child: Text('שם $counterpartKind: ${groupName!.trim()}',
                            textAlign: TextAlign.right,
                            style: const TextStyle(
                                color: kPrimary, fontWeight: FontWeight.w800))),
                  ]),
                ),
                const SizedBox(height: 10),
              ],
              Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
                decoration: BoxDecoration(
                  color: const Color(0xFFF3F8FC),
                  borderRadius: BorderRadius.circular(9),
                  border: Border.all(color: const Color(0xFFD8E7F1)),
                ),
                child: Text(
                  explanation,
                  textAlign: TextAlign.right,
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w600,
                    color: Color(0xFF526C80),
                    height: 1.35,
                  ),
                ),
              ),
              const SizedBox(height: 10),
              Container(
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: const Color(0xFFC9D9E5)),
                ),
                clipBehavior: Clip.antiAlias,
                child: Column(children: [
                  Container(
                    color: const Color(0xFFE8F3FA),
                    child: Row(children: [
                      cell(
                          const Text('סוג התוכן והסבר',
                              textAlign: TextAlign.right,
                              style: TextStyle(
                                  fontSize: 14, fontWeight: FontWeight.w800)),
                          flex: 3),
                      if (showCounterpartFilter)
                        cell(filterHeader('מה מותר לשלוח', counterpartTarget),
                            flex: 2, alignment: Alignment.center),
                      cell(
                          filterHeader(
                              'איזה תוכן אני מוכן לקבל', personalTarget),
                          flex: showCounterpartFilter ? 2 : 3,
                          alignment: Alignment.center),
                    ]),
                  ),
                  ..._visibleKeys.map((key) {
                    final item = _itemFor(key);
                    final mine = personalFilter![key] == true;
                    final groupAllows =
                        showCounterpartFilter && groupFilter?[key] == true;
                    void togglePersonal() {
                      if (onPersonalFilterChanged == null) return;
                      final updated = Map<String, bool>.from(personalFilter!);
                      updated[key] = !mine;
                      onPersonalFilterChanged!(updated);
                    }

                    void toggleCounterpart() {
                      if (!showCounterpartFilter ||
                          groupFilter == null ||
                          onCounterpartFilterChanged == null) {
                        return;
                      }
                      final updated = Map<String, bool>.from(groupFilter!);
                      updated[key] = !groupAllows;
                      onCounterpartFilterChanged!(updated);
                    }

                    return Container(
                      decoration: const BoxDecoration(
                        border:
                            Border(top: BorderSide(color: Color(0xFFE1E9EF))),
                      ),
                      child: Row(children: [
                        cell(
                            Row(children: [
                              Icon(item.$1, size: 20, color: kPrimary),
                              const SizedBox(width: 8),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(item.$2,
                                        textAlign: TextAlign.right,
                                        style: const TextStyle(
                                            fontWeight: FontWeight.w700)),
                                    const SizedBox(height: 2),
                                    Text(item.$3,
                                        textAlign: TextAlign.right,
                                        style: const TextStyle(
                                            fontSize: 11, color: kSubtext)),
                                  ],
                                ),
                              ),
                            ]),
                            flex: 3),
                        if (showCounterpartFilter)
                          cell(
                              status(groupAllows,
                                  editable: onCounterpartFilterChanged != null,
                                  onTap: toggleCounterpart),
                              flex: 2,
                              alignment: Alignment.center),
                        cell(
                            status(mine,
                                editable: onPersonalFilterChanged != null,
                                onTap: togglePersonal),
                            flex: showCounterpartFilter ? 2 : 3,
                            alignment: Alignment.center),
                      ]),
                    );
                  }),
                ]),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ── Chat Screen ───────────────────────────────────────────────────
class ChatScreen extends StatefulWidget {
  final String token;
  final Map<String, dynamic>? me;
  final Map<String, dynamic> recipient;
  final io.Socket? socket;
  final String? initialText;
  final String? listingId;
  final VoidCallback? onMessageSent;
  final bool embedded;
  final VoidCallback? onClose;
  final VoidCallback? onBlocked;
  final VoidCallback? onVoiceCall;
  final void Function(String fileUrl, String? fileName, bool isPdf)?
      onDocumentOpen;
  final bool openScreenshotMenuOnStart;

  const ChatScreen({
    super.key,
    required this.token,
    required this.me,
    required this.recipient,
    required this.socket,
    this.initialText,
    this.listingId,
    this.onMessageSent,
    this.embedded = false,
    this.onClose,
    this.onBlocked,
    this.onVoiceCall,
    this.onDocumentOpen,
    this.openScreenshotMenuOnStart = false,
  });

  @override
  State<ChatScreen> createState() => _ChatScreenState();
}

class _ChatScreenState extends State<ChatScreen> {
  final List<Map<String, dynamic>> _messages = [];
  final Set<String> _selectedMessageKeys = {};
  final _msgCtrl = TextEditingController();
  final _msgHistory = _MessageInputHistory();
  final _msgFocusNode = FocusNode();
  late final ClipboardImagePasteListener _clipboardImagePasteListener;
  final _scrollCtrl = ScrollController();
  Map<String, dynamic>? _replyTo;
  Map<String, dynamic>? _editingMsg;
  bool _loading = true;
  bool _isTyping = false;
  late final void Function(dynamic) _chatTypingHandler;
  late final void Function(dynamic) _scanRejectedSocketHandler;
  late final void Function(dynamic) _scanCancelledSocketHandler;
  late final void Function(dynamic) _messageRejectedSocketHandler;
  Timer? _messageRefreshTimer;
  String? _serverMessagesFingerprint;
  final AudioRecorder _audioRecorder = AudioRecorder();
  bool _isRecording = false;
  bool _voiceSubmissionInProgress = false;
  bool _cameraCaptureOpen = false;
  int _recordSeconds = 0;
  Timer? _recordTimer;
  String _voiceFileName = 'voice_message.webm';
  Map<String, bool>? _recipientReceivingFilter;
  Map<String, bool>? _outgoingFilter;
  bool _counterpartFilterAvailable = false;
  bool? _requiresFirstMessageFilterChoice;
  Future<void>? _initialMessagesFuture;
  Future<void>? _initialOutgoingFilterFuture;

  String _selectionKey(Map<String, dynamic> message) =>
      message['id']?.toString() ??
      message['clientMessageId']?.toString() ??
      message['client_message_id']?.toString() ??
      '${message['createdAt'] ?? message['created_at'] ?? ''}:${message['from'] ?? message['senderId'] ?? message['sender_id'] ?? ''}:${message['fileUrl'] ?? message['file_url'] ?? ''}:${message['text'] ?? ''}';

  void _toggleMessageSelection(Map<String, dynamic> message) {
    final key = _selectionKey(message);
    setState(() {
      if (!_selectedMessageKeys.add(key)) _selectedMessageKeys.remove(key);
    });
  }

  Future<void> _forwardSelectedMessages() async {
    final selected = _messages
        .where(
            (message) => _selectedMessageKeys.contains(_selectionKey(message)))
        .toList();
    if (selected.isEmpty) return;
    await _forwardChatMessages(context, widget.token, widget.socket, selected);
    if (mounted) setState(_selectedMessageKeys.clear);
  }

  bool get _recipientAllowsText =>
      widget.recipient['id'] == kScanBotId ||
      _recipientReceivingFilter?['text'] != false;
  bool get _recipientAllowsVideo =>
      widget.recipient['id'] == kScanBotId ||
      _recipientReceivingFilter?['video'] != false;
  bool get _recipientAllowsImages =>
      widget.recipient['id'] == kScanBotId ||
      _recipientReceivingFilter == null ||
      const ['nonHumanImages', 'men', 'women', 'children']
          .any((key) => _recipientReceivingFilter![key] == true);

  void _showRecipientFilterNotice(String contentType) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text('$contentType חסום בהגדרות הקבלה של הנמען'),
      backgroundColor: Colors.orange.shade800,
    ));
  }

  void _markBlockedContent(String messageId) {
    if (!mounted) return;
    setState(() {
      final index =
          _messages.indexWhere((message) => message['id'] == messageId);
      if (index == -1) return;
      _messages[index]['text'] = _blockedContentText;
      _messages[index]['status'] = 'blocked_content';
      _messages[index]['blockedContent'] = true;
    });
    Future.delayed(const Duration(minutes: 2), () {
      if (!mounted) return;
      setState(() => _messages.removeWhere((message) =>
          message['id'] == messageId && message['blockedContent'] == true));
    });
  }

  @override
  void initState() {
    super.initState();
    registerAppScreenshotMenu(this, _showAttachMenu);
    appScreenshotDestination.value = AppScreenshotDestination.user(
        widget.recipient['id']?.toString() ?? kSystemGuideId);
    _clipboardImagePasteListener = ClipboardImagePasteListener(
      focusNode: _msgFocusNode,
      onImage: (bytes, fileName, mimeType) => _uploadAndSend(
        XFile.fromData(bytes, name: fileName, mimeType: mimeType),
        fileName,
        'image',
        extraFields: const {'clipboardPaste': 'true'},
      ),
    );
    final prefill = (widget.initialText ?? '').trim();
    if (prefill.isNotEmpty) {
      _msgCtrl.text = prefill;
      _msgCtrl.selection = TextSelection.fromPosition(
        TextPosition(offset: _msgCtrl.text.length),
      );
    }
    _initialMessagesFuture = _loadMessages();
    _loadRecipientReceivingFilter();
    _initialOutgoingFilterFuture = _loadOutgoingFilter();
    _setupSocket();
    if (widget.openScreenshotMenuOnStart) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _showAttachMenu();
      });
    }
    // WebSocket delivery is best-effort (a browser can sleep or reconnect).
    // Quietly reconcile with the server so an incoming message can never stay
    // invisible until the user closes and reopens the conversation.
    _messageRefreshTimer = Timer.periodic(
      const Duration(seconds: 4),
      (_) => _loadMessages(silent: true),
    );
  }

  Future<void> _loadRecipientReceivingFilter() async {
    if (widget.recipient['id'] == kScanBotId) return;
    try {
      final response = await http.get(
        Uri.parse('$kApi/users/${widget.recipient['id']}/receiving-filter'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      ).timeout(const Duration(seconds: 10));
      if (!mounted || response.statusCode != 200) return;
      final body = jsonDecode(response.body);
      final raw = body is Map ? body['filter'] : null;
      if (raw is! Map) return;
      setState(() {
        _recipientReceivingFilter = raw.map(
          (key, value) => MapEntry(key.toString(), value == true),
        );
      });
    } catch (_) {}
  }

  Future<void> _loadOutgoingFilter() async {
    try {
      final response = await http.get(
        Uri.parse('$kApi/contacts/${widget.recipient['id']}/filter-settings'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      ).timeout(const Duration(seconds: 10));
      if (!mounted || response.statusCode != 200) return;
      final body = jsonDecode(response.body);
      final raw = body is Map ? body['filter'] : null;
      if (raw is! Map) return;
      setState(() {
        _outgoingFilter =
            raw.map((key, value) => MapEntry(key.toString(), value == true));
        _requiresFirstMessageFilterChoice =
            body is Map && body['requiresChoice'] == true;
      });
    } catch (_) {}
  }

  Future<bool> _loadContactFilterComparison() async {
    try {
      final response = await http.get(
        Uri.parse('$kApi/contacts/${widget.recipient['id']}/filter-comparison'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      ).timeout(const Duration(seconds: 10));
      if (!mounted || response.statusCode != 200) return false;
      final body = jsonDecode(response.body);
      final recipient = body is Map ? body['recipientFilter'] : null;
      final personal = body is Map ? body['personalFilter'] : null;
      final counterpartAvailable =
          body is Map && body['counterpartFilterAvailable'] == true;
      if (personal is! Map || (counterpartAvailable && recipient is! Map)) {
        return false;
      }
      setState(() {
        _counterpartFilterAvailable = counterpartAvailable;
        _recipientReceivingFilter = recipient is Map
            ? recipient.map(
                (key, value) => MapEntry(key.toString(), value == true),
              )
            : null;
        _outgoingFilter = personal.map(
          (key, value) => MapEntry(key.toString(), value == true),
        );
      });
      return true;
    } catch (_) {
      return false;
    }
  }

  Future<void> _loadMessages({bool silent = false}) async {
    final cacheKey = 'cache_msgs_${widget.me?['id']}_${widget.recipient['id']}';
    // Show cache immediately
    try {
      final prefs = await SharedPreferences.getInstance();
      final cached = prefs.getString(cacheKey);
      if (!silent && cached != null && mounted) {
        final list = (jsonDecode(cached) as List).cast<Map<String, dynamic>>();
        setState(() {
          _messages
            ..clear()
            ..addAll(list);
          _loading = false;
        });
        _scrollToBottom();
      }
    } catch (_) {}
    // Fetch from server and update
    try {
      final res = await http.get(
        Uri.parse('$kApi/messages/${widget.recipient['id']}'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (!mounted) return;
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body) as List;
        final normalized = data.map(_normalizeDbMessage).toList();
        _persistRecentImageUrls(normalized).ignore();
        final fingerprint = jsonEncode(normalized);
        if (silent && fingerprint == _serverMessagesFingerprint) return;
        _serverMessagesFingerprint = fingerprint;
        setState(() {
          final pending = _messages
              .where((m) => (m['id'] as String? ?? '').startsWith('temp_'))
              .toList();
          _messages.clear();
          _messages.addAll(normalized);
          for (final p in pending) {
            final alreadySaved = p['fileUrl'] != null
                ? _messages.any((message) => message['fileUrl'] == p['fileUrl'])
                : _messages.any((message) => message['text'] == p['text']);
            if (!alreadySaved) {
              _messages.add(p);
            }
          }
          _loading = false;
        });
        _scrollToBottom();
        _markAsRead();
        // Save to cache (last 50 messages)
        final prefs = await SharedPreferences.getInstance();
        final toCache = normalized.length > 50
            ? normalized.sublist(normalized.length - 50)
            : normalized;
        await prefs.setString(cacheKey, jsonEncode(toCache));
      } else {
        setState(() => _loading = false);
      }
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  Map<String, dynamic> _normalizeDbMessage(dynamic m) {
    final map = m as Map<String, dynamic>;
    final msgType = _normalizeIncomingFileType(
          map['type'] as String?,
          fileUrl: map['file_url'] as String?,
          fileName: map['file_name'] as String?,
        ) ??
        'text';
    final sticker =
        msgType == 'sticker' ? _avielStickerById(map['body']) : null;
    final isFile = (map['file_url'] != null) ||
        (msgType != 'text' && msgType != 'group_invite' && sticker == null);
    final privateFilter = map['private_filter'];
    return {
      'id': map['id'],
      'text': map['body'] ?? map['file_name'] ?? '',
      'from': map['sender_id'],
      'time': _formatTime(map['created_at']),
      'createdAt': map['created_at']?.toString(),
      'isUnread': map['sender_id'] != widget.me?['id'] &&
          map['is_read'] != true &&
          map['is_read'] != 1,
      'status': map['message_status'] == 'pending_scan'
          ? 'pending_scan'
          : map['message_status'] == 'rejected_scan'
              ? 'rejected_scan'
              : map['message_status'] == 'read'
                  ? 'read'
                  : map['message_status'] == 'delivered'
                      ? 'delivered'
                      : 'sent',
      if (map['scan_reason'] != null) 'scanReason': map['scan_reason'],
      if (map['forward_allowed'] == true) 'forwardAllowed': true,
      if (map['image_classification'] != null)
        'classification': map['image_classification'],
      if (map['audio_duration_seconds'] != null)
        'audioDurationSeconds':
            double.tryParse(map['audio_duration_seconds'].toString()),
      if (map['audio_transcript'] != null)
        'audioTranscript': map['audio_transcript'].toString(),
      if (map['audio_moderation_status'] != null)
        'audioModerationStatus': map['audio_moderation_status'].toString(),
      if (map['content_purged_at'] != null) 'contentPurged': true,
      if (map['blocked_preview_url'] != null)
        'blockedPreviewUrl': map['blocked_preview_url'].toString(),
      if (map['blocked_content_expires_at'] != null)
        'previewExpiresAt': map['blocked_content_expires_at'].toString(),
      if (map['delivery_summary'] != null)
        'deliverySummary': map['delivery_summary'],
      if (map['reply_to_id'] != null)
        'replyTo': {
          'id': map['reply_to_id'],
          'text': map['reply_body'] ?? '',
        },
      'isFile': isFile,
      'fileType': sticker != null ? 'sticker' : (isFile ? msgType : null),
      if (sticker != null) 'stickerId': sticker.id,
      'fileUrl': map['file_url'],
      'fileName': map['file_name'],
      'educationFormId': map['education_form_id'],
      'educationResponseStatus': map['education_response_status'],
      'isGroupInvite': msgType == 'group_invite',
      'isPrivateFilterEntry': msgType == 'private_filter',
      if (privateFilter is Map)
        'privateFilter': privateFilter.map(
          (key, value) => MapEntry(key.toString(), value == true),
        ),
      'meta': map['file_name'],
      'isEdited': map['is_edited'] == true || map['is_edited'] == 1,
    };
  }

  String _formatTime(dynamic raw) {
    if (raw == null) return '';
    final dt = DateTime.tryParse(raw.toString());
    if (dt == null) return '';
    final l = dt.toLocal();
    return '${l.hour.toString().padLeft(2, '0')}:${l.minute.toString().padLeft(2, '0')}';
  }

  void _setupSocket() {
    widget.socket?.on('chat:message', (data) {
      if (!mounted || data is! Map) return;
      final fileUrl = data['fileUrl'] as String?;
      final fileName = data['fileName'] as String?;
      final fromUserId = data['fromUserId'];
      final isIncoming = fromUserId == widget.recipient['id'];
      final pendingIndex = fileUrl == null
          ? -1
          : _messages.indexWhere((message) =>
              message['status'] == 'pending_scan' &&
              message['fileUrl'] == fileUrl);
      final recoveredFailedIndex =
          fromUserId != widget.me?['id'] || fileName == null
              ? -1
              : _messages.lastIndexWhere((message) =>
                  _matchesRecentFailedUpload(message, fileName, 'failed_'));
      final isDelayedOutgoing = fromUserId == widget.me?['id'] &&
          (pendingIndex != -1 || recoveredFailedIndex != -1);
      if (!isIncoming && !isDelayedOutgoing) return;
      final fileType = _normalizeIncomingFileType(
        data['fileType'] as String?,
        fileUrl: fileUrl,
        fileName: fileName,
      );
      final sticker = fileType == 'sticker'
          ? _avielStickerById(data['stickerId'] ?? data['text'])
          : null;
      final isFile = fileUrl != null ||
          (fileType != null && fileType != 'text' && sticker == null);
      final incoming = <String, dynamic>{
        'id': data['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        'text': data['text'] as String? ?? fileName ?? '',
        'from': isIncoming ? widget.recipient['id'] : widget.me?['id'],
        'time': data['createdAt'] != null
            ? _formatTime(data['createdAt'])
            : _nowTime(),
        'createdAt':
            data['createdAt']?.toString() ?? DateTime.now().toIso8601String(),
        'isUnread': false,
        'status': isIncoming ? 'received' : 'sent',
        'isFile': isFile,
        'fileType': fileType,
        if (sticker != null) 'stickerId': sticker.id,
        'educationFormId': data['formId'],
        'educationResponseStatus': data['educationResponseStatus'],
        'fileUrl': fileUrl,
        'fileName': fileName,
        if (data['classification'] != null)
          'classification': data['classification'],
        if (data['deliverySummary'] != null)
          'deliverySummary': data['deliverySummary'],
        if (data['audioTranscript'] != null)
          'audioTranscript': data['audioTranscript'].toString(),
        if (data['audioModerationStatus'] != null)
          'audioModerationStatus': data['audioModerationStatus'].toString(),
        if (data['replyToId'] != null)
          'replyTo': {'id': data['replyToId'], 'text': data['replyBody'] ?? ''},
      };
      setState(() {
        if (pendingIndex != -1) {
          _messages[pendingIndex] = incoming;
        } else if (recoveredFailedIndex != -1) {
          _messages[recoveredFailedIndex] = incoming;
        } else if (!_messages
            .any((message) => message['id'] == incoming['id'])) {
          _messages.add(incoming);
        }
        _isTyping = false;
      });
      _scrollToBottom();
      if (recoveredFailedIndex != -1) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
          content: Text('הסריקה הושלמה והתמונה נשלחה'),
          backgroundColor: Colors.green,
        ));
      }
      if (isIncoming) _markAsRead();
    });

    _scanRejectedSocketHandler = (data) {
      if (!mounted || data is! Map) return;
      final fileUrl = data['fileUrl'] as String?;
      if (fileUrl == null) return;
      final index = _messages.indexWhere((message) =>
          message['status'] == 'pending_scan' && message['fileUrl'] == fileUrl);
      if (index == -1) return;
      setState(() {
        _messages[index]['status'] = 'rejected_scan';
        _messages[index]['scanReason'] =
            data['reason']?.toString() ?? 'נדחתה בסריקה';
        _messages[index]['blockedPreviewUrl'] = data['blockedPreviewUrl'];
        _messages[index]['previewExpiresAt'] = data['previewExpiresAt'];
        if (data['audioTranscript'] != null) {
          _messages[index]['audioTranscript'] =
              data['audioTranscript'].toString();
        }
      });
    };
    widget.socket?.on('scan:rejected', _scanRejectedSocketHandler);
    _scanCancelledSocketHandler = (data) {
      if (!mounted || data is! Map) return;
      final fileUrl = data['fileUrl']?.toString();
      if (fileUrl == null) return;
      setState(() => _messages.removeWhere((message) =>
          message['fileUrl'] == fileUrl &&
          (message['status'] == 'uploading' ||
              message['status'] == 'pending_scan')));
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(data['reason']?.toString() ??
            'הסריקה בוטלה אוטומטית לאחר המתנה ממושכת'),
      ));
    };
    widget.socket?.on('scan:cancelled', _scanCancelledSocketHandler);

    _messageRejectedSocketHandler = (data) {
      if (!mounted || data is! Map) return;
      final targetId = data['toUserId']?.toString();
      if (targetId != null && targetId != widget.recipient['id']?.toString()) {
        return;
      }
      ScaffoldMessenger.of(context).showSnackBar(_contentWarningSnackBar(
          data['reason']?.toString() ?? 'ההודעה נחסמה'));
    };
    widget.socket?.on('message:rejected', _messageRejectedSocketHandler);

    _chatTypingHandler = (data) {
      if (data['fromUserId'] == widget.recipient['id'] && mounted) {
        setState(() => _isTyping = true);
        Future.delayed(const Duration(seconds: 3), () {
          if (mounted) setState(() => _isTyping = false);
        });
      }
    };
    widget.socket?.on('chat:typing', _chatTypingHandler);

    widget.socket?.on('messages:read', (_) {
      if (!mounted) return;
      setState(() {
        for (final msg in _messages) {
          if (msg['from'] == widget.me?['id']) msg['status'] = 'read';
        }
      });
    });

    widget.socket?.on('messages:delivered', (_) {
      if (!mounted) return;
      setState(() {
        for (final msg in _messages) {
          if (msg['from'] == widget.me?['id'] && msg['status'] != 'read') {
            msg['status'] = 'delivered';
          }
        }
      });
    });

    widget.socket?.on('message:delivered', (data) {
      if (!mounted) return;
      setState(() {
        final index = _messages.indexWhere((m) => m['id'] == data['id']);
        if (index != -1 && _messages[index]['status'] != 'read') {
          _messages[index]['status'] = 'delivered';
        }
      });
    });

    widget.socket?.on('message:deleted', (data) {
      if (!mounted) return;
      setState(() {
        final idx = _messages.indexWhere((m) => m['id'] == data['id']);
        if (idx != -1) {
          _messages[idx]['text'] = '🚫 הודעה נמחקה';
          _messages[idx]['isFile'] = false;
          _messages[idx]['fileUrl'] = null;
          _messages[idx]['fileName'] = null;
          _messages[idx]['fileType'] = 'text';
        }
      });
    });

    widget.socket?.on('message:edited', (data) {
      if (!mounted) return;
      setState(() {
        final idx = _messages.indexWhere((m) => m['id'] == data['id']);
        if (idx != -1) {
          _messages[idx]['text'] = data['body'] as String;
          _messages[idx]['isEdited'] = true;
        }
      });
    });
  }

  Future<void> _markAsRead() async {
    try {
      await http.put(
        Uri.parse('$kApi/messages/read'),
        headers: {
          'Authorization': 'Bearer ${widget.token}',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({'senderId': widget.recipient['id']}),
      );
    } catch (_) {}
  }

  @override
  void dispose() {
    unregisterAppScreenshotMenu(this);
    final screenshotDestination = AppScreenshotDestination.user(
        widget.recipient['id']?.toString() ?? kSystemGuideId);
    if (appScreenshotDestination.value.sameAs(screenshotDestination)) {
      appScreenshotDestination.value =
          const AppScreenshotDestination.user(kSystemGuideId);
    }
    _clipboardImagePasteListener.dispose();
    _messageRefreshTimer?.cancel();
    _recordTimer?.cancel();
    _audioRecorder.dispose();
    widget.socket?.off('chat:message');
    widget.socket?.off('scan:rejected', _scanRejectedSocketHandler);
    widget.socket?.off('scan:cancelled', _scanCancelledSocketHandler);
    widget.socket?.off('message:rejected', _messageRejectedSocketHandler);
    widget.socket?.off('chat:typing', _chatTypingHandler);
    widget.socket?.off('messages:read');
    widget.socket?.off('messages:delivered');
    widget.socket?.off('message:delivered');
    widget.socket?.off('message:deleted');
    widget.socket?.off('message:edited');
    _msgCtrl.dispose();
    _msgFocusNode.dispose();
    _scrollCtrl.dispose();
    super.dispose();
  }

  String _nowTime() {
    final n = DateTime.now();
    return '${n.hour.toString().padLeft(2, '0')}:${n.minute.toString().padLeft(2, '0')}';
  }

  Future<void> _toggleVoiceRecording() async {
    if (_voiceSubmissionInProgress) return;
    try {
      if (_isRecording) {
        _voiceSubmissionInProgress = true;
        try {
          _recordTimer?.cancel();
          final recordedSeconds = _recordSeconds;
          final path = await _audioRecorder.stop();
          if (mounted) setState(() => _isRecording = false);
          if (path == null || recordedSeconds < 1) {
            throw Exception('ההקלטה קצרה מדי או שלא נקלט בה קול');
          }
          final recording = XFile(
            path,
            name: _voiceFileName,
            mimeType:
                _voiceFileName.endsWith('.webm') ? 'audio/webm' : 'audio/wav',
          );
          final bytes = await recording.readAsBytes();
          if (bytes.length < 256) {
            throw Exception('ההקלטה ריקה ולא נשלחה');
          }
          await _uploadAndSend(recording, _voiceFileName, 'audio');
        } finally {
          _voiceSubmissionInProgress = false;
        }
        return;
      }
      if (!kIsWeb && !await _audioRecorder.hasPermission()) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(content: Text('יש לאפשר גישה למיקרופון')));
        }
        return;
      }
      final path = kIsWeb
          ? ''
          : '${(await getTemporaryDirectory()).path}/voice_${DateTime.now().millisecondsSinceEpoch}.wav';
      var encoder = AudioEncoder.wav;
      _voiceFileName = 'voice_message.wav';
      if (kIsWeb) {
        if (await _audioRecorder.isEncoderSupported(AudioEncoder.opus)) {
          encoder = AudioEncoder.opus;
          _voiceFileName = 'voice_message.webm';
        } else if (!await _audioRecorder.isEncoderSupported(AudioEncoder.wav)) {
          throw Exception('הדפדפן אינו תומך בהקלטת אודיו');
        }
      }
      await _audioRecorder.start(
          RecordConfig(
              encoder: encoder,
              numChannels: 1,
              sampleRate: 16000,
              bitRate: 32000),
          path: path);
      if (!await _audioRecorder.isRecording()) {
        throw Exception('המיקרופון לא התחיל להקליט');
      }
      if (!mounted) return;
      setState(() {
        _isRecording = true;
        _recordSeconds = 0;
      });
      _recordTimer = Timer.periodic(const Duration(seconds: 1), (_) {
        if (!mounted) return;
        setState(() => _recordSeconds++);
        if (_recordSeconds >= 120) {
          _recordTimer?.cancel();
          _toggleVoiceRecording();
          ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
            content: Text('ההקלטה נעצרה לאחר מגבלת שתי דקות'),
          ));
        }
      });
    } catch (error) {
      if (mounted) {
        setState(() => _isRecording = false);
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('ההקלטה נכשלה: $error')));
      }
    }
  }

  Future<void> _send({String? stickerId}) async {
    if (!_recipientAllowsText) {
      _showRecipientFilterNotice('תוכן טקסטואלי');
      return;
    }
    final sticker = _avielStickerById(stickerId);
    final text = sticker?.id ?? _msgCtrl.text.trim();
    if (text.isEmpty) return;
    if (sticker == null) _msgHistory.record(text);

    // Edit mode
    if (_editingMsg != null) {
      final msgId = _editingMsg!['id'] as String;
      final oldText = _editingMsg!['text'] as String;
      setState(() {
        final idx = _messages.indexWhere((m) => m['id'] == msgId);
        if (idx != -1) {
          _messages[idx]['text'] = text;
          _messages[idx]['isEdited'] = true;
        }
        _editingMsg = null;
        _msgCtrl.clear();
      });
      try {
        final res = await http.patch(
          Uri.parse('$kApi/messages/$msgId'),
          headers: {
            'Authorization': 'Bearer ${widget.token}',
            'Content-Type': 'application/json'
          },
          body: jsonEncode({'body': text}),
        );
        if (res.statusCode != 200 && mounted) {
          setState(() {
            final idx = _messages.indexWhere((m) => m['id'] == msgId);
            if (idx != -1) {
              _messages[idx]['text'] = oldText;
              _messages[idx]['isEdited'] = false;
            }
          });
        }
      } catch (_) {}
      return;
    }

    // The private per-contact filter must be persisted successfully before
    // the original message is added to the chat or sent to the recipient.
    if (!await _ensureFirstMessageFilterChoice()) return;

    // Normal send
    final replySnapshot = _replyTo;
    final tempId = 'temp_${DateTime.now().millisecondsSinceEpoch}';
    setState(() {
      _messages.add({
        'id': tempId,
        'text': text,
        'from': widget.me?['id'],
        'time': _nowTime(),
        'createdAt': DateTime.now().toIso8601String(),
        'status': 'sent',
        if (sticker != null) 'stickerId': sticker.id,
        if (sticker != null) 'fileType': 'sticker',
        if (replySnapshot != null)
          'replyTo': Map<String, dynamic>.from(replySnapshot),
      });
      _replyTo = null;
      _msgCtrl.clear();
    });
    // שליחה דרך HTTP — שומרת את ההודעה ב-DB ומעבירה ל-socket של הנמען
    // אם הוא מחובר, או שולחת push notification אחרת.
    // (בעבר השליחה הייתה רק דרך widget.socket?.emit — מה שגרם לאיבוד
    // הודעות כאשר המסך נפתח עם socket=null, למשל ממסך מודעה.)
    () async {
      try {
        final res = await http.post(
          Uri.parse('$kApi/messages'),
          headers: {
            'Authorization': 'Bearer ${widget.token}',
            'Content-Type': 'application/json',
          },
          body: jsonEncode({
            'toUserId': widget.recipient['id'],
            'text': text,
            if (sticker != null) 'stickerId': sticker.id,
            if (widget.listingId != null) 'listingId': widget.listingId,
            if (replySnapshot != null) 'replyToId': replySnapshot['id'],
          }),
        );
        if (!mounted) return;
        if (res.statusCode == 200) {
          final data = jsonDecode(res.body) as Map<String, dynamic>;
          if (data['requestPending'] == true) {
            setState(() => _messages.removeWhere((m) => m['id'] == tempId));
            ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
                content: Text('נשלחה בקשת הודעה — ההודעה תימסר לאחר אישור')));
            return;
          }
          setState(() {
            final idx = _messages.indexWhere((m) => m['id'] == tempId);
            if (idx != -1) {
              _messages[idx]['id'] = data['id'];
              _messages[idx]['status'] = data['status'] ?? 'sent';
            }
          });
          if (widget.listingId != null && widget.onMessageSent != null) {
            widget.onMessageSent!.call();
            return;
          }
        } else {
          setState(() {
            final idx = _messages.indexWhere((m) => m['id'] == tempId);
            if (idx != -1) _messages[idx]['status'] = 'failed';
          });
          var error = 'שליחת ההודעה נכשלה';
          String? errorCode;
          try {
            final payload = jsonDecode(res.body) as Map<String, dynamic>;
            error = (payload['error'] as String?) ?? error;
            errorCode = payload['code']?.toString();
          } catch (_) {}
          if (errorCode == 'CHAT_CONTENT_BLOCKED') {
            _markBlockedContent(tempId);
          }
          ScaffoldMessenger.of(context).showSnackBar(
            errorCode == 'CHAT_CONTENT_BLOCKED'
                ? _contentWarningSnackBar(error)
                : SnackBar(content: Text(error)),
          );
        }
      } catch (_) {
        if (!mounted) return;
        setState(() {
          final idx = _messages.indexWhere((m) => m['id'] == tempId);
          if (idx != -1) _messages[idx]['status'] = 'failed';
        });
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('אין חיבור לשרת — ההודעה לא נשלחה')),
        );
      }
    }();
    _scrollToBottom();
  }

  Future<bool> _ensureFirstMessageFilterChoice() async {
    if (widget.recipient['id'] == kScanBotId) return true;
    await Future.wait([
      if (_initialMessagesFuture != null) _initialMessagesFuture!,
      if (_initialOutgoingFilterFuture != null) _initialOutgoingFilterFuture!,
    ]);
    if (!mounted) return false;

    if (_requiresFirstMessageFilterChoice != true) return true;

    final loaded = await _loadContactFilterComparison();
    if (!mounted) return false;
    if (!loaded || _outgoingFilter == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('לא ניתן לטעון כעת את נתוני הסינון')),
      );
      return false;
    }

    final recipientName =
        widget.recipient['name']?.toString().trim().isNotEmpty == true
            ? widget.recipient['name'].toString().trim()
            : 'החבר';
    var selected = Map<String, bool>.from(_outgoingFilter!);
    final choice = await showDialog<Map<String, bool>>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: Row(
            children: [
              UserAvatar(
                picUrl: widget.recipient['profile_pic_url']?.toString(),
                name: recipientName,
                radius: 21,
              ),
              const SizedBox(width: 9),
              Expanded(
                child: Text(
                  'בחירת התוכן שאקבל מ$recipientName',
                  textAlign: TextAlign.right,
                ),
              ),
            ],
          ),
          content: SizedBox(
            width: 760,
            child: SingleChildScrollView(
              child: _InvitationFilterComparisonTable(
                groupName: recipientName,
                groupFilter: _recipientReceivingFilter,
                personalFilter: selected,
                counterpartKind: 'החבר',
                showCounterpartFilter: false,
                counterpartIcon: Icons.person_outline,
                onPersonalFilterChanged: (updated) =>
                    setDialogState(() => selected = updated),
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('ביטול'),
            ),
            FilledButton.icon(
              onPressed: () => Navigator.pop(dialogContext, selected),
              icon: const Icon(Icons.send_outlined),
              label: const Text('שמור והמשך'),
            ),
          ],
        ),
      ),
    );
    if (choice == null || !mounted) return false;

    try {
      final response = await http.put(
        Uri.parse('$kApi/contacts/${widget.recipient['id']}/filter-settings'),
        headers: {
          'Authorization': 'Bearer ${widget.token}',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({'filter': choice}),
      );
      if (!mounted) return false;
      if (response.statusCode != 200) throw Exception();
      final payload = jsonDecode(response.body);
      final privateEntry = payload is Map ? payload['privateEntry'] : null;
      setState(() {
        _outgoingFilter = Map<String, bool>.from(choice);
        _requiresFirstMessageFilterChoice = false;
        if (privateEntry is Map) {
          final normalized = _normalizeDbMessage(privateEntry);
          if (!_messages.any((message) => message['id'] == normalized['id'])) {
            _messages.add(normalized);
          }
        }
      });
      return true;
    } catch (_) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('שמירת הסינון נכשלה')),
        );
      }
      return false;
    }
  }

