  Future<void> _handleChatMenuAction(String action) async {
    switch (action) {
      case 'info':
        if (!mounted) return;
        await _showContactDetails();
        break;
      case 'screenshot':
        await openAppScreenshot(context,
            token: widget.token,
            destination: AppScreenshotDestination.user(
                widget.recipient['id']?.toString() ?? kSystemGuideId));
        break;
      case 'search':
        _searchInMessages();
        break;
      case 'mute':
        final prefs = await SharedPreferences.getInstance();
        await prefs.setBool('muted_chat_${widget.recipient['id']}', true);
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('ההתראות לשיחה הושתקו')),
          );
        }
        break;
      case 'report':
        if (mounted) {
          await _showReportDialog(
            context: context,
            token: widget.token,
            targetType: 'user',
            targetId: widget.recipient['id']?.toString() ?? '',
            targetLabel: 'המשתמש ${widget.recipient['name'] as String? ?? ''}',
          );
        }
        break;
      case 'block':
        _blockUser();
        break;
    }
  }

  Future<void> _searchInMessages() async {
    final controller = TextEditingController();
    await showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          final query = controller.text.trim().toLowerCase();
          final matches = query.isEmpty
              ? <Map<String, dynamic>>[]
              : _messages
                  .where((m) => (m['text'] as String? ?? '')
                      .toLowerCase()
                      .contains(query))
                  .toList();
          return AlertDialog(
            title: const Text('חיפוש בהודעות'),
            content: SizedBox(
              width: 420,
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                TextField(
                  controller: controller,
                  autofocus: true,
                  textDirection: TextDirection.rtl,
                  decoration: const InputDecoration(
                    hintText: 'הקלד טקסט לחיפוש...',
                    prefixIcon: Icon(Icons.search),
                  ),
                  onChanged: (_) => setDialogState(() {}),
                ),
                const SizedBox(height: 12),
                ConstrainedBox(
                  constraints: const BoxConstraints(maxHeight: 300),
                  child: query.isEmpty
                      ? const Text('')
                      : matches.isEmpty
                          ? const Text('לא נמצאו הודעות')
                          : ListView.builder(
                              shrinkWrap: true,
                              itemCount: matches.length,
                              itemBuilder: (_, i) => ListTile(
                                dense: true,
                                title:
                                    Text(matches[i]['text'] as String? ?? ''),
                                trailing:
                                    Text(matches[i]['time'] as String? ?? ''),
                              ),
                            ),
                ),
              ]),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('סגור'),
              )
            ],
          );
        },
      ),
    );
  }

  Future<void> _blockUser() async {
    final recipientName = widget.recipient['name'] as String? ?? 'משתמש זה';
    final confirm = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('חסימת משתמש'),
        content: Text('לחסום את $recipientName?\nלא יוכל לשלוח לך הודעות.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('ביטול')),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(context, true),
            child: const Text('חסום'),
          ),
        ],
      ),
    );
    if (confirm != true) return;
    try {
      final response = await http.post(
        Uri.parse('$kApi/block/${widget.recipient['id']}'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      ).timeout(const Duration(seconds: 10));
      if (!mounted) return;
      if (response.statusCode != 200) {
        var error = 'חסימת המשתמש נכשלה';
        try {
          final payload = jsonDecode(response.body);
          if (payload is Map && payload['error'] != null) {
            error = payload['error'].toString();
          }
        } catch (_) {}
        throw Exception(error);
      }
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('$recipientName נחסם בהצלחה')),
      );
      widget.onBlocked?.call();
      if (widget.embedded) {
        widget.onClose?.call();
      } else if (Navigator.of(context).canPop()) {
        Navigator.of(context).pop(true);
      }
    } catch (error) {
      if (!mounted) return;
      final message = error.toString().replaceFirst('Exception: ', '');
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(message), backgroundColor: Colors.red.shade700),
      );
    }
  }

  Future<void> _sharePhoneContact() async {
    await _loadRecipientReceivingFilter();
    if (!mounted) return;
    if (!_recipientAllowsText) {
      _showRecipientFilterNotice('שיתוף אנשי קשר');
      return;
    }
    final contact = await _pickSharedContact(context, widget.token);
    if (contact == null || !mounted) return;
    _msgCtrl.text = _sharedContactText(contact);
    await _send();
  }

