class _GroupInviteCard extends StatefulWidget {
  final Map<String, dynamic> message;
  final String token;
  final VoidCallback onJoined;
  const _GroupInviteCard(
      {required this.message, required this.token, required this.onJoined});
  @override
  State<_GroupInviteCard> createState() => _GroupInviteCardState();
}

class _GroupInviteCardState extends State<_GroupInviteCard> {
  bool _joined = false;
  bool _declined = false;
  bool _loading = false;

  Map<String, dynamic> get _meta {
    try {
      final raw = widget.message['meta'] as String? ?? '{}';
      return jsonDecode(raw) as Map<String, dynamic>;
    } catch (_) {
      return {};
    }
  }

  Future<void> _join() async {
    final groupId = _meta['groupId'] as String?;
    if (groupId == null) return;
    setState(() => _loading = true);
    try {
      final preview = await http.get(
        Uri.parse('$kApi/groups/$groupId/invitation-filter'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (!mounted || preview.statusCode != 200) {
        if (mounted) setState(() => _loading = false);
        return;
      }
      final previewData = jsonDecode(preview.body) as Map<String, dynamic>;
      Map<String, bool> readFilter(dynamic raw) => raw is Map
          ? raw.map((key, value) => MapEntry(key.toString(), value == true))
          : <String, bool>{};
      setState(() => _loading = false);
      final selected = await _chooseGroupInvitationFilter(
        context,
        groupFilter: readFilter(previewData['groupFilter']),
        initialFilter: _newAccountFilter(),
        counterpart: _meta['groupName']?.toString() ?? 'הקבוצה',
        groupName: _meta['groupName']?.toString(),
      );
      if (selected == null || !mounted) return;
      setState(() => _loading = true);
      final res = await http.post(
        Uri.parse('$kApi/groups/$groupId/join'),
        headers: {
          'Authorization': 'Bearer ${widget.token}',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({'filter': selected}),
      );
      if (res.statusCode == 200 && mounted) {
        setState(() {
          _joined = true;
          _loading = false;
        });
        widget.onJoined();
      } else {
        setState(() => _loading = false);
      }
    } catch (_) {
      setState(() => _loading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final groupName = _meta['groupName'] as String? ?? 'קבוצה';
    return Align(
      alignment: Alignment.centerRight,
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
        constraints:
            BoxConstraints(maxWidth: MediaQuery.of(context).size.width * 0.78),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: kPrimary.withValues(alpha: 0.3)),
          boxShadow: [
            BoxShadow(
                color: Colors.black.withValues(alpha: 0.06), blurRadius: 4)
          ],
        ),
        child: Padding(
          padding: const EdgeInsets.all(14),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(children: [
                const Icon(Icons.group_add_outlined, color: kPrimary, size: 20),
                const SizedBox(width: 8),
                const Text('הזמנה לקבוצה',
                    style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.bold,
                        color: kPrimary)),
              ]),
              const SizedBox(height: 8),
              Text('הוזמנת להצטרף לקבוצה\n"$groupName"',
                  textDirection: TextDirection.rtl,
                  style: const TextStyle(
                      fontSize: 14, fontWeight: FontWeight.w600)),
              const SizedBox(height: 12),
              if (_joined)
                const Text('✓ הצטרפת לקבוצה',
                    style: TextStyle(color: Colors.green, fontSize: 13))
              else if (_declined)
                const Text('ההזמנה נדחתה',
                    style: TextStyle(color: kSubtext, fontSize: 13))
              else
                Row(
                  children: [
                    Expanded(
                      child: ElevatedButton(
                        onPressed: _loading ? null : _join,
                        style: ElevatedButton.styleFrom(
                          backgroundColor: kPrimary,
                          padding: const EdgeInsets.symmetric(vertical: 8),
                          shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(8)),
                        ),
                        child: _loading
                            ? const SizedBox(
                                width: 16,
                                height: 16,
                                child: CircularProgressIndicator(
                                    strokeWidth: 2, color: Colors.white))
                            : const Text('הצטרף',
                                style: TextStyle(color: Colors.white)),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: OutlinedButton(
                        onPressed: () => setState(() => _declined = true),
                        style: OutlinedButton.styleFrom(
                          padding: const EdgeInsets.symmetric(vertical: 8),
                          side: const BorderSide(color: kSubtext),
                          shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(8)),
                        ),
                        child: const Text('דחה',
                            style: TextStyle(color: kSubtext)),
                      ),
                    ),
                  ],
                ),
            ],
          ),
        ),
      ),
    );
  }
}

// Opens a listing by its id fetched from the server.
Future<void> _openListingLink(BuildContext context, String listingId,
    String token, Map<String, dynamic>? me) async {
  try {
    final res = await http.get(
      Uri.parse('$kApi/listings/$listingId'),
      headers: {'Authorization': 'Bearer $token'},
    );
    if (res.statusCode == 200 && context.mounted) {
      final item = jsonDecode(res.body) as Map<String, dynamic>;
      final notification = _OpenListingNotification(item);
      notification.dispatch(context);
      if (notification.handledInDesktopPane) return;
      Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => ListingDetailScreen(
                item: item, token: token, me: me, socket: null),
          ));
    }
  } catch (_) {}
}

final Map<String, Future<Map<String, dynamic>?>> _listingPreviewCache = {};

Future<Map<String, dynamic>?> _loadListingMessagePreview(
    String listingId, String token) {
  return _listingPreviewCache.putIfAbsent(listingId, () async {
    try {
      final response = await http.get(
        Uri.parse('$kApi/listings/$listingId/preview'),
        headers: {'Authorization': 'Bearer $token'},
      ).timeout(const Duration(seconds: 10));
      if (response.statusCode != 200) return null;
      final decoded = jsonDecode(response.body);
      return decoded is Map<String, dynamic> ? decoded : null;
    } catch (_) {
      _listingPreviewCache.remove(listingId);
      return null;
    }
  });
}

