class VoiceMessagePlayer extends StatefulWidget {
  final String url;
  final bool isMe;
  final String? senderAvatarUrl;
  final String senderName;
  final double? initialDurationSeconds;
  const VoiceMessagePlayer({
    super.key,
    required this.url,
    required this.isMe,
    this.senderAvatarUrl,
    required this.senderName,
    this.initialDurationSeconds,
  });

  @override
  State<VoiceMessagePlayer> createState() => _VoiceMessagePlayerState();
}

class _VoiceMessagePlayerState extends State<VoiceMessagePlayer>
    with SingleTickerProviderStateMixin {
  final AudioPlayer _player = AudioPlayer();
  late final AnimationController _loadingController;
  Duration _position = Duration.zero;
  Duration _duration = Duration.zero;
  bool _playing = false;
  bool _sourcePrepared = false;
  bool _loading = true;
  bool _loadFailed = false;

  @override
  void initState() {
    super.initState();
    final initialDurationSeconds = widget.initialDurationSeconds;
    if (initialDurationSeconds != null && initialDurationSeconds > 0) {
      _duration =
          Duration(milliseconds: (initialDurationSeconds * 1000).round());
    }
    _loadingController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 900),
    )..repeat();
    _player.onPositionChanged.listen((value) {
      if (mounted) setState(() => _position = value);
    });
    _player.onDurationChanged.listen((value) {
      if (mounted && value > Duration.zero) {
        setState(() => _duration = value);
      }
    });
    _player.onPlayerStateChanged.listen((value) {
      if (mounted) setState(() => _playing = value == PlayerState.playing);
    });
    _player.onPlayerComplete.listen((_) {
      if (mounted) setState(() => _position = Duration.zero);
    });
    _prepareSource();
  }

  String _durationLabel(Duration value) =>
      '${value.inMinutes}:${(value.inSeconds % 60).toString().padLeft(2, '0')}';

  Future<void> _prepareSource() async {
    if (_sourcePrepared) return;
    if (mounted) {
      setState(() {
        _loading = true;
        _loadFailed = false;
      });
      _loadingController.repeat();
    }
    try {
      if (kIsWeb) {
        final response =
            await http.get(Uri.parse(_absoluteMediaUrl(widget.url)));
        if (response.statusCode != 200 || response.bodyBytes.length < 256) {
          throw Exception('audio download failed');
        }
        final lowerUrl = widget.url.toLowerCase();
        final mimeType = lowerUrl.endsWith('.webm')
            ? 'audio/webm'
            : lowerUrl.endsWith('.wav')
                ? 'audio/wav'
                : 'audio/mp4';
        await _player
            .setSource(BytesSource(response.bodyBytes, mimeType: mimeType));
      } else {
        await _player.setSourceUrl(_absoluteMediaUrl(widget.url));
      }
      _sourcePrepared = true;
      var duration = await _player.getDuration();
      if (duration == null || duration <= Duration.zero) {
        duration = await _player.onDurationChanged
            .firstWhere((value) => value > Duration.zero)
            .timeout(const Duration(seconds: 8),
                onTimeout: () => Duration.zero);
      }
      if (!mounted) return;
      _loadingController.stop();
      setState(() {
        if (duration != null && duration > Duration.zero) {
          _duration = duration;
        }
        _loading = false;
      });
    } catch (_) {
      _sourcePrepared = false;
      if (!mounted) return;
      _loadingController.stop();
      setState(() {
        _loading = false;
        _loadFailed = true;
      });
    }
  }

  Future<void> _toggle() async {
    try {
      if (_playing) {
        await _player.pause();
      } else {
        await _prepareSource();
        await _player.resume();
      }
    } catch (_) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('לא ניתן לנגן את ההודעה הקולית')));
      }
    }
  }

  @override
  void dispose() {
    _loadingController.dispose();
    _player.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final totalMs = _duration.inMilliseconds;
    final progress = totalMs == 0
        ? 0.0
        : (_position.inMilliseconds / totalMs).clamp(0.0, 1.0);
    return SizedBox(
      width: 245,
      child: Row(children: [
        UserAvatar(
          radius: 21,
          picUrl: widget.senderAvatarUrl,
          name: widget.senderName,
        ),
        IconButton(
          onPressed: _loading
              ? null
              : _loadFailed
                  ? _prepareSource
                  : _toggle,
          tooltip: _loadFailed ? 'נסה שוב' : null,
          icon: Icon(
            _loadFailed
                ? Icons.refresh
                : _playing
                    ? Icons.pause
                    : Icons.play_arrow,
            color: _loading ? kSubtext : kTextDark,
          ),
        ),
        Expanded(
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            AnimatedBuilder(
              animation: _loadingController,
              builder: (_, __) => Row(
                children: List.generate(
                    22,
                    (i) => Expanded(
                          child: Container(
                            margin: const EdgeInsets.symmetric(horizontal: 1),
                            height: _loading
                                ? 5.0 +
                                    (((i * 7) +
                                                (_loadingController.value * 20)
                                                    .round()) %
                                            15)
                                        .toDouble()
                                : 5.0 + ((i * 7) % 15),
                            color: _loading
                                ? kPrimaryMid.withValues(alpha: .55)
                                : i / 22 <= progress
                                    ? kPrimaryMid
                                    : const Color(0xFFCDD3D6),
                          ),
                        )),
              ),
            ),
            const SizedBox(height: 3),
            Text(
              _loading
                  ? 'טוען הקלטה...'
                  : _loadFailed
                      ? 'הטעינה נכשלה — לחצו לניסיון חוזר'
                      : '${_durationLabel(_position)} / ${_durationLabel(_duration)}',
              style: const TextStyle(fontSize: 10, color: kSubtext),
            ),
          ]),
        ),
      ]),
    );
  }
}

class _ChatVideoPlayer extends StatefulWidget {
  final String url;
  const _ChatVideoPlayer({required this.url});

  @override
  State<_ChatVideoPlayer> createState() => _ChatVideoPlayerState();
}

class _ChatVideoPlayerState extends State<_ChatVideoPlayer> {
  late VideoPlayerController _controller;
  late Future<void> _initialization;

  @override
  void initState() {
    super.initState();
    _createController();
  }

  void _createController() {
    _controller = VideoPlayerController.networkUrl(
      Uri.parse(_absoluteMediaUrl(widget.url)),
    );
    _initialization = _controller.initialize().then((_) {
      _controller.setLooping(false);
      if (mounted) setState(() {});
    });
  }

  @override
  void didUpdateWidget(covariant _ChatVideoPlayer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.url != widget.url) {
      _controller.dispose();
      _createController();
    }
  }

  Future<void> _toggle() async {
    if (!_controller.value.isInitialized) return;
    if (_controller.value.isPlaying) {
      await _controller.pause();
    } else {
      if (_controller.value.position >= _controller.value.duration) {
        await _controller.seekTo(Duration.zero);
      }
      await _controller.play();
    }
    if (mounted) setState(() {});
  }

  Future<void> _retry() async {
    await _controller.dispose();
    if (!mounted) return;
    setState(_createController);
  }

  Future<void> _openExternally() async {
    final uri = Uri.parse(_absoluteMediaUrl(widget.url));
    if (!await launchUrl(uri, mode: LaunchMode.externalApplication) &&
        mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('לא ניתן לפתוח את הסרטון בדפדפן')),
      );
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<void>(
      future: _initialization,
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return Container(
            width: 280,
            constraints: const BoxConstraints(minHeight: 150),
            padding: const EdgeInsets.all(14),
            color: Colors.black87,
            alignment: Alignment.center,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              const Icon(Icons.videocam_off_outlined,
                  color: Colors.white70, size: 34),
              const SizedBox(height: 8),
              const Text('הנגן המובנה לא הצליח לטעון את הסרטון',
                  textAlign: TextAlign.center,
                  style: TextStyle(color: Colors.white)),
              const SizedBox(height: 10),
              Wrap(spacing: 8, alignment: WrapAlignment.center, children: [
                OutlinedButton.icon(
                  onPressed: _retry,
                  icon: const Icon(Icons.refresh, size: 18),
                  label: const Text('נסה שוב'),
                  style:
                      OutlinedButton.styleFrom(foregroundColor: Colors.white),
                ),
                FilledButton.icon(
                  onPressed: _openExternally,
                  icon: const Icon(Icons.open_in_new, size: 18),
                  label: const Text('הפעל בדפדפן'),
                ),
              ]),
            ]),
          );
        }
        if (snapshot.connectionState != ConnectionState.done ||
            !_controller.value.isInitialized) {
          return Container(
            width: 260,
            height: 150,
            color: Colors.black87,
            alignment: Alignment.center,
            child: const CircularProgressIndicator(color: Colors.white),
          );
        }
        final ratio = _controller.value.aspectRatio > 0
            ? _controller.value.aspectRatio
            : 16 / 9;
        return SizedBox(
          width: 280,
          child: ClipRRect(
            borderRadius: BorderRadius.circular(10),
            child: ColoredBox(
              color: Colors.black,
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                GestureDetector(
                  onTap: _toggle,
                  child: Stack(alignment: Alignment.center, children: [
                    AspectRatio(
                      aspectRatio: ratio,
                      child: VideoPlayer(_controller),
                    ),
                    if (!_controller.value.isPlaying)
                      Container(
                        width: 54,
                        height: 54,
                        decoration: const BoxDecoration(
                            color: Colors.black54, shape: BoxShape.circle),
                        child: const Icon(Icons.play_arrow,
                            color: Colors.white, size: 38),
                      ),
                  ]),
                ),
                VideoProgressIndicator(
                  _controller,
                  allowScrubbing: true,
                  colors: const VideoProgressColors(
                    playedColor: kPrimaryMid,
                    bufferedColor: Colors.white38,
                    backgroundColor: Colors.white12,
                  ),
                  padding: const EdgeInsets.symmetric(vertical: 5),
                ),
              ]),
            ),
          ),
        );
      },
    );
  }
}

class _ImageStatusBadge extends StatelessWidget {
  final Map<String, dynamic> message;
  final bool isMe;

  const _ImageStatusBadge({required this.message, required this.isMe});

  @override
  Widget build(BuildContext context) {
    var status = message['status'] as String? ?? (isMe ? 'sent' : 'received');
    final reportText = message['text']?.toString() ?? '';
    if (reportText.contains('דוח סריקה:')) {
      if (reportText.contains('תוצאה: ⛔')) {
        status = 'rejected_scan';
      } else if (reportText.contains('תוצאה: ✅')) {
        status = 'scan_approved';
      } else if (reportText.contains('תוצאה: ⏳')) {
        status = 'pending_scan';
      }
    }
    late final String label;
    late final IconData icon;
    late final Color color;
    switch (status) {
      case 'pending_scan':
        label = 'נסרק';
        icon = Icons.document_scanner_outlined;
        color = Colors.orange;
        break;
      case 'awaiting_contact_approval':
        label = 'ממתין לאישור חברות';
        icon = Icons.person_add_alt_1;
        color = Colors.orange;
        break;
      case 'failed':
        label = 'השליחה נכשלה';
        icon = Icons.error_outline;
        color = Colors.red;
        break;
      case 'rejected_scan':
        label = 'נחסם';
        icon = Icons.block;
        color = Colors.red;
        break;
      case 'scan_approved':
        label = 'עבר סריקה';
        icon = Icons.verified_outlined;
        color = Colors.green.shade700;
        break;
      case 'received':
      case 'delivered':
      case 'read':
        label = 'התקבל';
        icon = Icons.done_all;
        color = kReadTick;
        break;
      default:
        label = isMe ? 'נשלח' : 'התקבל';
        icon = isMe ? Icons.done : Icons.done_all;
        color = kPrimary;
    }
    return Tooltip(
      message: label,
      child: Container(
        width: 27,
        height: 27,
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: 0.92),
          shape: BoxShape.circle,
          boxShadow: const [
            BoxShadow(color: Colors.black26, blurRadius: 3),
          ],
        ),
        alignment: Alignment.center,
        child: Icon(icon, size: 17, color: color),
      ),
    );
  }
}

class _GroupDeliverySummary extends StatelessWidget {
  final Map<String, dynamic> summary;
  const _GroupDeliverySummary(this.summary);

  List<String> _names(String key) {
    final raw = summary[key];
    if (raw is! List) return const [];
    return raw
        .whereType<Map>()
        .map((item) => item['name']?.toString() ?? '')
        .where((name) => name.isNotEmpty)
        .toList();
  }

  @override
  Widget build(BuildContext context) {
    final deliveredCount = summary['deliveredCount'] as int? ?? 0;
    final blockedCount = summary['blockedCount'] as int? ?? 0;
    final deliveredNames = _names('deliveredTo');
    final blockedNames = _names('blockedFor');
    final details = <String>[
      'נשלח בקבוצה',
      if (deliveredNames.isNotEmpty) 'קיבלו: ${deliveredNames.join(', ')}',
      if (blockedNames.isNotEmpty)
        'נחסם בסינון האישי אצל: ${blockedNames.join(', ')}',
    ].join('\n');
    return Align(
      alignment: Alignment.centerRight,
      child: Tooltip(
        message: details,
        waitDuration: const Duration(milliseconds: 250),
        child: Container(
          constraints: const BoxConstraints(maxWidth: 420),
          margin: const EdgeInsets.only(top: 7),
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
          decoration: BoxDecoration(
            color: blockedCount > 0
                ? const Color(0xFFFFF3E0)
                : const Color(0xFFE8F5E9),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: blockedCount > 0
                  ? const Color(0xFFFFB74D)
                  : const Color(0xFF81C784),
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                blockedCount > 0 ? Icons.shield_outlined : Icons.done_all,
                size: 14,
                color: blockedCount > 0 ? Colors.orange.shade800 : kReadTick,
              ),
              const SizedBox(width: 4),
              Flexible(
                child: Text(
                  'נשלח בקבוצה: $deliveredCount קיבלו'
                  ' • $blockedCount נחסמו בסינון האישי',
                  textDirection: TextDirection.rtl,
                  softWrap: true,
                  style: TextStyle(
                    fontSize: 12,
                    height: 1.3,
                    fontWeight: FontWeight.bold,
                    color: blockedCount > 0 ? Colors.orange.shade900 : kSubtext,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

