      {required this.fileName,
      required this.startedAt,
      this.fileType = 'image',
      this.scanning = false});

  @override
  State<_UploadProcessingCard> createState() => _UploadProcessingCardState();
}

class _UploadProcessingCardState extends State<_UploadProcessingCard>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1400),
  )..repeat();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final typeLabel = widget.fileType == 'video'
        ? 'הווידאו'
        : widget.fileType == 'document'
            ? 'המסמך'
            : widget.fileType == 'audio'
                ? 'ההקלטה'
                : 'התמונה';
    return AnimatedBuilder(
      animation: _controller,
      builder: (_, __) {
        final elapsed = DateTime.now().difference(widget.startedAt).inSeconds;
        return Container(
          width: 285,
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            gradient: const LinearGradient(
              colors: [Color(0xFFEAF6FD), Color(0xFFF8FCFF)],
            ),
            borderRadius: BorderRadius.circular(14),
            border: Border.all(color: const Color(0xFFB9D8ED)),
          ),
          child: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
            Row(children: [
              RotationTransition(
                turns: _controller,
                child:
                    const Icon(Icons.auto_awesome, color: kPrimary, size: 25),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.end,
                  children: [
                    Text(
                        widget.scanning
                            ? 'סורק את $typeLabel'
                            : 'מעלה ואחר כך סורק את $typeLabel',
                        style: const TextStyle(fontWeight: FontWeight.w800)),
                    Text(widget.fileName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(fontSize: 11, color: kSubtext)),
                  ],
                ),
              ),
              const SizedBox(width: 8),
              Text('$elapsed שנ׳',
                  style: const TextStyle(
                      color: kPrimary, fontWeight: FontWeight.bold)),
            ]),
            const SizedBox(height: 11),
            LinearProgressIndicator(
              value: _controller.value,
              minHeight: 5,
              borderRadius: BorderRadius.circular(5),
              color: kPrimary,
              backgroundColor: const Color(0xFFD7EAF6),
            ),
            const SizedBox(height: 7),
            Text(
                widget.scanning
                    ? 'הקובץ שמור וממתין לאישור הסריקה לפני שליחה'
                    : elapsed >= 45
                        ? 'הקובץ נשמר; בדיקת הבטיחות עדיין מתבצעת'
                        : 'קודם העלאה לאחסון, אחריה בדיקת בטיחות וסינון',
                style: const TextStyle(fontSize: 10, color: kSubtext)),
          ]),
        );
      },
    );
  }
}

