    categories = categories.where(_icons.containsKey).toSet().toList();
    if (categories.isEmpty) return const SizedBox.shrink();
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: categories
          .map((category) => Padding(
                padding: const EdgeInsets.only(left: 3),
                child: Tooltip(
                  message: _labels[category]!,
                  child: Container(
                    width: 27,
                    height: 27,
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.94),
                      shape: BoxShape.circle,
                      boxShadow: const [
                        BoxShadow(color: Colors.black26, blurRadius: 3),
                      ],
                    ),
                    child: Icon(_icons[category], size: 18, color: kPrimary),
                  ),
                ),
              ))
          .toList(),
    );
  }
}

class _DocumentClassificationSummary extends StatelessWidget {
  final Map<String, dynamic> message;

  const _DocumentClassificationSummary({required this.message});

  static const _labels = <String, String>{
    'men': 'גברים',
    'women': 'נשים',
    'children': 'ילדים',
    'nonHumanImages': 'נוף או חפצים',
    'people': 'אנשים',
    'landscape': 'נוף או חפצים',
  };

  @override
  Widget build(BuildContext context) {
    final raw = message['classification'];
    if (raw is! Map) return const SizedBox.shrink();
    final detected = raw['detectedCategories'];
    final categories = detected is List
        ? detected
            .map((value) => value.toString())
            .where((value) => _labels.containsKey(value))
            .toSet()
            .toList()
        : <String>[];
    final visualScan = raw['documentVisualScan'];
    final scan = visualScan is Map ? visualScan : const <String, dynamic>{};
    final scanned = int.tryParse(scan['scanned']?.toString() ?? '') ?? 0;
    final total = int.tryParse(scan['total']?.toString() ?? '') ?? scanned;
    final classificationText = raw['uncertain'] == true
        ? 'סיווג לא ודאי'
        : categories.isEmpty
            ? 'לא נמצאו תמונות לסיווג'
            : categories.map((category) => _labels[category]!).join(', ');
    final scanText = total > 0 ? ' · נסרקו $scanned מתוך $total' : '';
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
      decoration: BoxDecoration(
        color: kPrimary.withValues(alpha: 0.07),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(Icons.verified_user_outlined, size: 15, color: kPrimary),
          const SizedBox(width: 5),
          Flexible(
            child: Text(
              'סיווג: $classificationText$scanText',
              style: const TextStyle(fontSize: 11, color: kPrimary),
              textDirection: TextDirection.rtl,
              textAlign: TextAlign.right,
            ),
          ),
        ],
      ),
    );
  }
}

bool _isGridImageMessage(Map<String, dynamic> message) {
  final fileUrl = message['fileUrl'] as String?;
  if (fileUrl == null) return false;
  final status = message['status']?.toString();
  if (status == 'uploading' ||
      status == 'failed' ||
      status == 'pending_scan' ||
      status == 'rejected_scan') {
    return false;
  }
  return _normalizeIncomingFileType(
        message['fileType'] as String?,
        fileUrl: fileUrl,
        fileName: message['fileName'] as String?,
      ) ==
      'image';
}

List<Map<String, dynamic>> _conversationImageMessages(
        Iterable<Map<String, dynamic>> messages) =>
    messages.where(_isGridImageMessage).toList();

int _conversationImageIndex(
    List<Map<String, dynamic>> images, Map<String, dynamic> selectedMessage) {
  final selectedId = selectedMessage['id'];
  final index = images.indexWhere((message) =>
      identical(message, selectedMessage) ||
      (selectedId != null && message['id'] == selectedId));
  return index < 0 ? 0 : index;
}

String _imageSentAtLabel(Map<String, dynamic> message) {
  final parsed = DateTime.tryParse(message['createdAt']?.toString() ?? '');
  if (parsed == null) return message['time']?.toString() ?? '';
  final local = parsed.toLocal();
  String twoDigits(int value) => value.toString().padLeft(2, '0');
  return '${twoDigits(local.day)}/${twoDigits(local.month)}/${local.year} · '
      '${twoDigits(local.hour)}:${twoDigits(local.minute)}';
}

// Retained for the optional compact gallery layout.
// ignore: unused_element
bool _sameImageSequenceSender(
    Map<String, dynamic> first, Map<String, dynamic> second) {
  final firstTime = DateTime.tryParse(first['createdAt']?.toString() ?? '');
  final secondTime = DateTime.tryParse(second['createdAt']?.toString() ?? '');
  if (firstTime != null &&
      secondTime != null &&
      firstTime.difference(secondTime).abs() > const Duration(minutes: 5)) {
    return false;
  }
  if (first.containsKey('from') || second.containsKey('from')) {
    return first['from'] == second['from'];
  }
  return first['isMe'] == second['isMe'] &&
      first['senderName'] == second['senderName'];
}

// ignore: unused_element
class _ConsecutiveImageGrid extends StatelessWidget {
  final List<Map<String, dynamic>> messages;
  final List<Map<String, dynamic>> conversationMessages;
  final bool isMe;
  final VoidCallback? onForwardAll;
  final void Function(Map<String, dynamic>)? onMessageOptions;

  const _ConsecutiveImageGrid({
    required this.messages,
    required this.conversationMessages,
    required this.isMe,
    // ignore: unused_element_parameter
    this.onForwardAll,
    // ignore: unused_element_parameter
    this.onMessageOptions,
  });

  @override
  Widget build(BuildContext context) {
    final maxVisible = kIsWeb ? 8 : 4;
    final visible = messages.take(maxVisible).toList();
    final viewportWidth = MediaQuery.sizeOf(context).width;
    final gridWidth = kIsWeb
        ? (viewportWidth >= 900 ? 520.0 : math.min(344.0, viewportWidth - 24))
        : math.min(300.0, viewportWidth - 24);
    // Leave a physical-pixel margin for Flutter Web's fractional layout
    // rounding. With an exact fit the second tile can wrap onto a clipped
    // second row, so the gallery contains two images but the chat shows one.
    final tileExtent = (gridWidth - 8 - 3) / 2 - 1;
    final rowCount = (visible.length / 2).ceil();
    final gridHeight = rowCount * tileExtent + (rowCount - 1) * 3;
    return GestureDetector(
      onLongPress: onForwardAll == null
          ? null
          : () => showModalBottomSheet<void>(
                context: context,
                builder: (sheetContext) => SafeArea(
                  child: ListTile(
                    leading: const Icon(Icons.forward, color: kPrimary),
                    title: Text('העבר ${messages.length} תמונות'),
                    onTap: () {
                      Navigator.pop(sheetContext);
                      onForwardAll!();
                    },
                  ),
                ),
              ),
      child: Align(
        alignment: isMe ? Alignment.centerLeft : Alignment.centerRight,
        child: Container(
          width: gridWidth,
          margin: const EdgeInsets.symmetric(vertical: 2),
          padding: const EdgeInsets.all(4),
          decoration: BoxDecoration(
            color: isMe ? kOutgoing : kIncoming,
            borderRadius: BorderRadius.circular(14),
            border: isMe ? null : Border.all(color: kBorder),
          ),
          child: SizedBox(
            height: gridHeight,
            // This must not be a nested Scrollable. On Flutter web even a
            // GridView with NeverScrollableScrollPhysics can claim mouse-wheel
            // events and make the surrounding conversation appear stuck.
            child: Wrap(
              spacing: 3,
              runSpacing: 3,
              children: List.generate(visible.length, (index) {
                final message = visible[index];
                final url = message['fileUrl'] as String;
                final hiddenCount = messages.length - (maxVisible - 1);
                final conversationImages =
                    _conversationImageMessages(conversationMessages);
                final selectedIndex =
                    _conversationImageIndex(conversationImages, message);
                return SizedBox(
                  width: tileExtent,
                  height: tileExtent,
                  child: GestureDetector(
                    onTap: () => Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (_) => ImagePreviewScreen(
                          url: url,
                          filename: message['fileName'] as String?,
                          urls: conversationImages
                              .map((item) => item['fileUrl'] as String)
                              .toList(),
                          filenames: conversationImages
                              .map((item) => item['fileName'] as String?)
                              .toList(),
                          dates: conversationImages
                              .map((item) => _imageSentAtLabel(item))
                              .toList(),
                          messages: conversationImages,
                          onMessageOptions: onMessageOptions,
                          initialIndex: selectedIndex,
                        ),
                      ),
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(9),
                      child: Stack(
                        fit: StackFit.expand,
                        children: [
                          _PersistentMediaImage(
                            url: url,
                            fit: BoxFit.contain,
                            loadingBuilder: (_) => const ColoredBox(
                              color: kBorder,
                              child: Center(
                                child: CircularProgressIndicator(
                                    color: kPrimary, strokeWidth: 2),
                              ),
                            ),
                            errorBuilder: (_) => const ColoredBox(
                              color: kBorder,
                              child: Icon(Icons.broken_image, color: kSubtext),
                            ),
                          ),
                          if (index == maxVisible - 1 &&
                              messages.length > maxVisible) ...[
                            ColoredBox(
                                color: Colors.black.withValues(alpha: 0.48)),
                            Center(
                              child: Text(
                                '+$hiddenCount',
                                textDirection: TextDirection.ltr,
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 30,
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                            ),
                          ],
                          Positioned(
                            left: 5,
                            bottom: 5,
                            child:
                                _ImageStatusBadge(message: message, isMe: isMe),
                          ),
                          Positioned(
                            right: 5,
                            top: 5,
                            child: _ImageClassificationBadges(message: message),
                          ),
                          if (onMessageOptions != null)
                            Positioned(
                              left: 5,
                              top: 5,
                              child: _SmallImageOptionsButton(
                                onPressed: () => onMessageOptions!(message),
                              ),
                            ),
                        ],
                      ),
                    ),
                  ),
                );
              }),
            ),
          ),
        ),
      ),
    );
  }
}

class _OpenSharedContactChatNotification extends Notification {
  final Map<String, dynamic> recipient;
  bool handledInDesktopPane = false;

  _OpenSharedContactChatNotification(this.recipient);
}

class _SharedContactCard extends StatelessWidget {
  final Map<String, dynamic> contact;
  final String token;
  final Map<String, dynamic>? me;
  const _SharedContactCard(this.contact, {required this.token, this.me});

  void _openAppFriend(
      BuildContext context, String userId, String name, String? profilePicUrl) {
    final recipient = <String, dynamic>{
      'id': userId,
      'name': name,
      if (profilePicUrl != null) 'profile_pic_url': profilePicUrl,
    };
    final openNotification = _OpenSharedContactChatNotification(recipient);
    openNotification.dispatch(context);
    if (openNotification.handledInDesktopPane) return;
    Navigator.of(context).push(MaterialPageRoute(
      builder: (_) => ChatScreen(
        token: token,
        me: me,
        recipient: recipient,
        socket: null,
      ),
    ));
  }

  Future<void> _saveContact(BuildContext context, String name, String phone,
      String email, Uri uri) async {
    if (kIsWeb) {
      final opened = await launchUrl(uri, mode: LaunchMode.externalApplication);
      if (!opened && context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('לא ניתן להוריד את איש הקשר')),
        );
      }
      return;
    }

    try {
      final granted = await FlutterContacts.requestPermission();
      if (!granted) {
        if (context.mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('נדרשת הרשאה לשמירת אנשי קשר')),
          );
        }
        return;
      }
      final newContact = Contact()..name.first = name;
      if (phone.isNotEmpty) newContact.phones = [Phone(phone)];
      if (email.isNotEmpty) newContact.emails = [Email(email)];
      await newContact.insert();
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('$name נשמר באנשי הקשר')),
        );
      }
    } catch (_) {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('שמירת איש הקשר נכשלה')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final name = contact['name']?.toString() ?? 'איש קשר';
    final phone = contact['phone']?.toString() ?? '';
    final email = contact['email']?.toString() ?? '';
    final city = contact['city']?.toString() ?? '';
    final address = contact['address']?.toString() ?? '';
    final appUserId = contact['appUserId']?.toString() ?? '';
    final profilePicUrl = contact['profilePicUrl']?.toString();
    final uri = Uri.parse('$kServer/contact-vcard').replace(queryParameters: {
      'name': name,
      if (phone.isNotEmpty) 'phone': phone,
      if (email.isNotEmpty) 'email': email,
      if (city.isNotEmpty) 'city': city,
      if (address.isNotEmpty) 'address': address,
    });
    return Container(
      width: 250,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: .85),
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: kBorder)),
      child: Column(children: [
        Row(children: [
          UserAvatar(picUrl: profilePicUrl, name: name, radius: 22),
          const SizedBox(width: 10),
          Expanded(
              child:
                  Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
            Text(name,
                style:
                    const TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
            if (phone.isNotEmpty) Text(phone, textDirection: TextDirection.ltr),
            if (email.isNotEmpty)
              Text(email,
                  textDirection: TextDirection.ltr,
                  overflow: TextOverflow.ellipsis),
            if (city.isNotEmpty) Text('עיר: $city'),
            if (address.isNotEmpty) Text('כתובת: $address'),
          ])),
        ]),
        const Divider(),
        SizedBox(
            width: double.infinity,
            child: ElevatedButton.icon(
              onPressed: appUserId.isNotEmpty
                  ? () =>
                      _openAppFriend(context, appUserId, name, profilePicUrl)
                  : () => _saveContact(context, name, phone, email, uri),
              icon: Icon(appUserId.isNotEmpty
                  ? Icons.chat_bubble_outline
                  : Icons.person_add_alt_1),
              label: Text(appUserId.isNotEmpty ? 'פתח צ׳אט' : 'שמור בטלפון'),
            )),
      ]),
    );
  }
}

