String? _firstHttpUrl(String text) {
  final match =
      RegExp(r'https?://[^\s<>"׳״]+', caseSensitive: false).firstMatch(text);
  if (match == null) return null;
  return match.group(0)?.replaceFirst(RegExp(r'[.,!?)\]}]+$'), '');
}

class _WebsiteLinkPreview extends StatefulWidget {
  final String url;
  final String token;
  const _WebsiteLinkPreview(this.url, this.token);

  @override
  State<_WebsiteLinkPreview> createState() => _WebsiteLinkPreviewState();
}

class _WebsiteLinkPreviewState extends State<_WebsiteLinkPreview> {
  static final Map<String, Map<String, dynamic>> _cache = {};
  static final Map<String, DateTime> _cacheExpiresAt = {};
  Map<String, dynamic>? _data;
  bool _failed = false;

  bool get _isBetshuva {
    final host = Uri.tryParse(widget.url)?.host.toLowerCase() ?? '';
    return host == 'betshuva.com' || host.endsWith('.betshuva.com');
  }

  @override
  void initState() {
    super.initState();
    if (!_isBetshuva) _load();
  }

  Future<void> _load() async {
    final cached = _cache[widget.url];
    final cacheExpiresAt = _cacheExpiresAt[widget.url];
    if (cached != null &&
        cacheExpiresAt != null &&
        cacheExpiresAt.isAfter(DateTime.now())) {
      setState(() => _data = cached);
      return;
    }
    try {
      final response = await http.get(
        Uri.parse('$kApi/link-preview')
            .replace(queryParameters: {'url': widget.url}),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      ).timeout(const Duration(seconds: 10));
      if (response.statusCode != 200) throw Exception();
      final decoded = jsonDecode(response.body);
      if (decoded is! Map) throw Exception();
      final data = Map<String, dynamic>.from(decoded);
      _cache[widget.url] = data;
      final hasImage = data['image']?.toString().trim().isNotEmpty == true;
      _cacheExpiresAt[widget.url] = DateTime.now().add(
        hasImage ? const Duration(hours: 6) : const Duration(minutes: 1),
      );
      if (mounted) setState(() => _data = data);
    } catch (_) {
      if (mounted) setState(() => _failed = true);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_isBetshuva) return _BetshuvaInvitePreview(widget.url);
    final uri = Uri.tryParse(widget.url);
    final domain = _data?['domain']?.toString() ?? uri?.host ?? widget.url;
    final title = _data?['title']?.toString().trim() ?? '';
    final description = _data?['description']?.toString().trim() ?? '';
    final image = _data?['image']?.toString().trim() ?? '';
    return InkWell(
      onTap: _data == null
          ? null
          : () => _confirmAndOpenExternalLink(context, widget.url),
      borderRadius: BorderRadius.circular(10),
      child: Container(
        width: 330,
        clipBehavior: Clip.antiAlias,
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: kBorder),
        ),
        child:
            Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          if (image.isNotEmpty)
            _PersistentMediaImage(
              url: image,
              width: 330,
              height: 150,
              fit: BoxFit.cover,
              errorBuilder: (_) => const SizedBox.shrink(),
            )
          else if (_data == null && !_failed)
            const SizedBox(
              height: 64,
              child: Center(child: CircularProgressIndicator(strokeWidth: 2)),
            )
          else
            Container(
              height: 72,
              color: const Color(0xFFE8F4FD),
              child: const Icon(Icons.link, size: 34, color: kPrimary),
            ),
          Padding(
            padding: const EdgeInsets.all(11),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                if (title.isNotEmpty)
                  Text(title,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      textAlign: TextAlign.right,
                      style: const TextStyle(fontWeight: FontWeight.bold)),
                if (description.isNotEmpty) ...[
                  const SizedBox(height: 4),
                  Text(description,
                      maxLines: 3,
                      overflow: TextOverflow.ellipsis,
                      textAlign: TextAlign.right,
                      style: const TextStyle(fontSize: 13, color: kSubtext)),
                ],
                const SizedBox(height: 4),
                Text(domain,
                    textDirection: TextDirection.ltr,
                    style: const TextStyle(fontSize: 12, color: kSubtext)),
              ],
            ),
          ),
        ]),
      ),
    );
  }
}

class _PrivateContactFilterEntry extends StatelessWidget {
  final Map<String, bool> filter;
  final String recipientName;
  final String? recipientAvatarUrl;
  final VoidCallback onUpdate;

  const _PrivateContactFilterEntry({
    required this.filter,
    required this.recipientName,
    required this.recipientAvatarUrl,
    required this.onUpdate,
  });

  static const _labels = <String, String>{
    'text': 'טקסט',
    'nonHumanImages': 'נוף או חפצים',
    'men': 'גברים',
    'women': 'נשים',
    'children': 'ילדים',
    'video': 'וידאו',
  };

  @override
  Widget build(BuildContext context) {
    final allowed = _labels.entries
        .where((entry) => filter[entry.key] == true)
        .map((entry) => entry.value)
        .join(', ');
    final blocked = _labels.entries
        .where((entry) => filter[entry.key] != true)
        .map((entry) => entry.value)
        .join(', ');
    return Center(
      child: Container(
        constraints: const BoxConstraints(maxWidth: 520),
        margin: const EdgeInsets.symmetric(vertical: 8, horizontal: 12),
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
        decoration: BoxDecoration(
          color: const Color(0xFFEAF5FD),
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: const Color(0xFFAED4EE)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Center(
              child: Image.asset(
                'assets/guide/safe-information-ai.png',
                width: 64,
                height: 68,
                fit: BoxFit.contain,
                semanticLabel: 'עוזר ה-AI מזכיר את הגדרות הסינון',
              ),
            ),
            const SizedBox(height: 4),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                UserAvatar(
                  picUrl: recipientAvatarUrl,
                  name: recipientName,
                  radius: 17,
                ),
                const SizedBox(width: 8),
                Flexible(
                  child: Text(
                    'אני מוכן לקבל מ$recipientName',
                    textAlign: TextAlign.right,
                    style: const TextStyle(
                      color: kPrimary,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 7),
            Text('מותר: ${allowed.isEmpty ? "ללא" : allowed}',
                textAlign: TextAlign.right),
            const SizedBox(height: 3),
            Text('חסום: ${blocked.isEmpty ? "ללא" : blocked}',
                textAlign: TextAlign.right,
                style: const TextStyle(color: Color(0xFFB42318))),
            Align(
              alignment: Alignment.centerRight,
              child: TextButton.icon(
                onPressed: onUpdate,
                icon: const Icon(Icons.edit_outlined, size: 17),
                label: const Text('עדכון הסינון'),
              ),
            ),
            const SizedBox(height: 6),
            const Text(
              'רק אני רואה את ההגדרה הזו',
              textAlign: TextAlign.center,
              style: TextStyle(fontSize: 11, color: kSubtext),
            ),
          ],
        ),
      ),
    );
  }
}

class _MessageBubble extends StatelessWidget {
  final Map<String, dynamic> message;
  final List<Map<String, dynamic>> conversationMessages;
  final bool isMe;
  final String token;
  final Map<String, dynamic>? me;
  final String? senderAvatarUrl;
  final String senderName;
  final String? recipientName;
  final bool forceRightAlignment;
  final bool hideReply;
  final void Function(Map<String, dynamic>)? onMessageOptions;
  final void Function(String fileUrl, String? fileName, bool isPdf)?
      onDocumentOpen;

  const _MessageBubble({
    required this.message,
    required this.conversationMessages,
    required this.isMe,
    required this.token,
    required this.me,
    this.senderAvatarUrl,
    required this.senderName,
    this.recipientName,
    this.forceRightAlignment = false,
    this.hideReply = false,
    this.onMessageOptions,
    this.onDocumentOpen,
  });

  Alignment get _messageAlignment => forceRightAlignment
      ? Alignment.centerRight
      : isMe
          ? Alignment.centerLeft
          : Alignment.centerRight;

  Widget _statusIcon() {
    if (!isMe) return const SizedBox.shrink();
    switch (message['status'] as String? ?? 'sent') {
      case 'read':
        return const Icon(Icons.done_all, size: 14, color: kReadTick);
      case 'received':
      case 'delivered':
        return const Icon(Icons.done_all, size: 14, color: kPrimaryMid);
      case 'pending_scan':
        return const Tooltip(
          message: 'בהמתנה לבדיקת תוכן לא ראוי',
          child:
              Icon(Icons.hourglass_top, size: 14, color: Colors.orangeAccent),
        );
      case 'awaiting_contact_approval':
        return const Tooltip(
          message: 'ממתין לאישור חברות — הקובץ יישלח לאחר האישור',
          child: Icon(Icons.person_add_alt_1, size: 15, color: Colors.orange),
        );
      case 'failed':
        return const Tooltip(
          message: 'השליחה נכשלה',
          child: Icon(Icons.error_outline, size: 15, color: Colors.red),
        );
      case 'blocked_content':
        return const Tooltip(
          message: 'נחסם בגלל תוכן לא ראוי — יימחק אוטומטית',
          child: Icon(Icons.block, size: 15, color: Colors.red),
        );
      case 'rejected_scan':
        return const Tooltip(
          message: 'התמונה לא נשלחה',
          child: Icon(Icons.error_outline, size: 15, color: Colors.red),
        );
      default:
        return const Icon(Icons.done, size: 14, color: kPrimaryMid);
    }
  }

  @override
  Widget build(BuildContext context) {
    final isFile = message['isFile'] == true;
    final fileUrl = message['fileUrl'] as String?;
    final fileName = message['fileName'] as String?;
    final fileType = _normalizeIncomingFileType(
      message['fileType'] as String?,
      fileUrl: fileUrl,
      fileName: fileName,
    );
    final uploadStatus = message['status']?.toString();
    if (fileType == 'document' &&
        (uploadStatus == 'pending_scan' || uploadStatus == 'rejected_scan')) {
      return Align(
        alignment: _messageAlignment,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: _DocumentModerationCard(
            fileName: fileName ?? 'מסמך',
            blocked: uploadStatus == 'rejected_scan',
            reason: message['scanReason']?.toString(),
          ),
        ),
      );
    }
    final isVisualUpload = fileType == 'image' || fileType == 'video';
    final uploadTypeLabel = fileType == 'video'
        ? 'הווידאו'
        : fileType == 'audio'
            ? 'ההקלטה'
            : 'התמונה';
    if ((isVisualUpload || fileType == 'audio') &&
        uploadStatus == 'uploading') {
      return Align(
        alignment: _messageAlignment,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: _UploadProcessingCard(
            fileName: fileName ?? uploadTypeLabel,
            fileType: fileType ?? 'image',
            startedAt: DateTime.tryParse(
                    message['uploadStartedAt']?.toString() ?? '') ??
                DateTime.now(),
          ),
        ),
      );
    }
    if ((isVisualUpload || fileType == 'audio') &&
        uploadStatus == 'pending_scan') {
      return Align(
        alignment: _messageAlignment,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: _UploadProcessingCard(
            fileName: fileName ?? uploadTypeLabel,
            fileType: fileType ?? 'audio',
            scanning: true,
            startedAt:
                DateTime.tryParse(message['createdAt']?.toString() ?? '') ??
                    DateTime.now(),
          ),
        ),
      );
    }
    if ((isVisualUpload || fileType == 'audio') && uploadStatus == 'failed') {
      return Align(
        alignment: _messageAlignment,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: _UploadResultCard(
            blocked: false,
            title: 'העלאת $uploadTypeLabel נכשלה',
            reason: message['uploadError']?.toString() ??
                'אירעה שגיאה בזמן העלאת $uploadTypeLabel',
          ),
        ),
      );
    }
    if ((isVisualUpload || fileType == 'audio') &&
        uploadStatus == 'rejected_scan') {
      final baseReason = message['scanReason']?.toString() ??
          (fileType == 'audio'
              ? 'ההקלטה לא עברה את בדיקת התוכן ולכן לא נשלחה'
              : fileType == 'video'
                  ? 'הווידאו אינו תואם את הגדרות הסינון ולכן לא נשלח'
                  : 'התמונה אינה תואמת את הגדרות הסינון ולכן לא נשלחה');
      final displayedReason = message['forwardAllowed'] == true
          ? '$baseReason\nהקובץ עבר את בדיקת הבטיחות. ניתן להעביר אותו, והסינון של היעד החדש ייבדק מחדש.'
          : baseReason;
      return Align(
        alignment: _messageAlignment,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: _UploadResultCard(
            blocked: true,
            showBlockedArtwork: fileType != 'image',
            title: fileType == 'audio'
                ? 'ההקלטה נחסמה ולא נשלחה'
                : fileType == 'video'
                    ? 'הווידאו נחסם ולא נשלח'
                    : _imageBlockTitle(message['scanReason']),
            reason: displayedReason,
            imageUrl: fileType == 'audio' ? null : fileUrl,
            fileName: fileName,
            recipientName: message['forwardAllowed'] == true
                ? (isMe ? recipientName : senderName)
                : null,
            destinationFilterRejected: message['forwardAllowed'] == true,
            transcript: message['audioTranscript']?.toString(),
            contentPurged: message['contentPurged'] == true,
            blockedPreviewUrl: message['blockedPreviewUrl']?.toString(),
            authToken: token,
            previewExpiresAt: DateTime.tryParse(
                message['previewExpiresAt']?.toString() ?? ''),
          ),
        ),
      );
    }
    final isImageFile = isFile && fileUrl != null && fileType == 'image';
    final isAudioFile = isFile && fileUrl != null && fileType == 'audio';
    final isVideoFile = isFile && fileUrl != null && fileType == 'video';
    final isPdfFile = isFile &&
        fileUrl != null &&
        fileType == 'document' &&
        ((fileName ?? '').toLowerCase().endsWith('.pdf') ||
            Uri.tryParse(fileUrl)?.path.toLowerCase().endsWith('.pdf') == true);
    final isOfficeFile = isFile &&
        fileUrl != null &&
        fileType == 'document' &&
        _isOfficePreviewFile(fileName ?? Uri.tryParse(fileUrl)?.path);
    final conversationImages = _conversationImageMessages(conversationMessages);
    final selectedImageIndex =
        _conversationImageIndex(conversationImages, message);

    // זיהוי קישור מודעה פנימי: betshuva://listing/{id}
    final rawText = message['text'] as String? ?? '';
    final sharedContact = !isFile ? _sharedContactFromText(rawText) : null;
    final sharedUrl = !isFile ? _firstHttpUrl(rawText) : null;
    final guideExternalUrls = !isFile && message['from'] == kSystemGuideId
        ? RegExp(r'https://[^\s<>]+')
            .allMatches(rawText)
            .map((match) => match.group(0))
            .whereType<String>()
            .map((value) => value.replaceFirst(RegExp(r'[.,;:)\]]+$'), ''))
            .toSet()
            .take(5)
            .toList()
        : const <String>[];
    final linkRegex = RegExp(r'betshuva://listing/([\w\-]+)');
    final linkMatch = !isFile ? linkRegex.firstMatch(rawText) : null;
    final listingId = linkMatch?.group(1);
    final guideAppLinkRegex = RegExp(
        r'betshuva://app/(content-filter|profile|personal-media|screenshot|my-issues)(?:/([0-9a-fA-F-]{36}))?');
    final guideAppLinkMatch = !isFile && message['from'] == kSystemGuideId
        ? guideAppLinkRegex.firstMatch(rawText)
        : null;
    final guideAppDestination = guideAppLinkMatch?.group(1);
    final guideIssueId = guideAppLinkMatch?.group(2);
    final issueDraftRegex = RegExp(r'betshuva://issue-draft/([A-Za-z0-9_-]+)');
    final issueDraftMatch = !isFile && message['from'] == kSystemGuideId
        ? issueDraftRegex.firstMatch(rawText)
        : null;
    final issueDraft = _decodeGuideIssueDraft(issueDraftMatch?.group(1));
    // טקסט נקי ללא שורת הקישור
    final displayTextWithInternalLink = sharedContact != null
        ? ''
        : linkMatch != null
            ? rawText
                .replaceAll('\nbetshuva://listing/$listingId', '')
                .replaceAll('betshuva://listing/$listingId', '')
                .trim()
            : rawText;
    final displayText = displayTextWithInternalLink
        .replaceAll(guideAppLinkRegex, '')
        .replaceAll(issueDraftRegex, '')
        .replaceAll(RegExp(r'\n{3,}'), '\n\n')
        .trim();
    final avielSticker = _avielStickerById(
        message['stickerId'] ?? (fileType == 'sticker' ? rawText : null));
    if (avielSticker != null) {
      return Align(
        alignment: _messageAlignment,
        child: GestureDetector(
          onLongPress: onMessageOptions == null
              ? null
              : () => onMessageOptions!(message),
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 4),
            child: Column(
              crossAxisAlignment:
                  isMe ? CrossAxisAlignment.start : CrossAxisAlignment.end,
              children: [
                Semantics(
                  image: true,
                  label: 'מדבקת עוזר AI: ${avielSticker.label}',
                  child: Image.asset(avielSticker.asset,
                      width: 190, height: 190, fit: BoxFit.contain),
                ),
                Row(mainAxisSize: MainAxisSize.min, children: [
                  Text(message['time'] as String? ?? '',
                      style: const TextStyle(fontSize: 10, color: kSubtext)),
                  const SizedBox(width: 3),
                  _statusIcon(),
                ]),
              ],
            ),
          ),
        ),
      );
    }

    const textColor = kTextDark;
    const timeColor = kSubtext;
    final replyBg = kPrimary.withValues(alpha: 0.08);
    const replyBorder = kPrimary;

    return Align(
      alignment: _messageAlignment,
      child: Container(
        margin: const EdgeInsets.symmetric(vertical: 2),
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        constraints: BoxConstraints(
          maxWidth: MediaQuery.of(context).size.width * 0.72,
        ),
        decoration: BoxDecoration(
          color: isMe ? kOutgoing : kIncoming,
          borderRadius: BorderRadius.only(
            topLeft: const Radius.circular(14),
            topRight: const Radius.circular(14),
            bottomLeft:
                isMe ? const Radius.circular(3) : const Radius.circular(14),
            bottomRight:
                isMe ? const Radius.circular(14) : const Radius.circular(3),
          ),
          border: isMe ? null : Border.all(color: kBorder, width: 1),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: 0.06),
              blurRadius: 4,
              offset: const Offset(0, 2),
            ),
          ],
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.end,
          mainAxisSize: MainAxisSize.min,
          children: [
            if (!hideReply && message['replyTo'] != null)
              Align(
                alignment: Alignment.centerRight,
                child: Container(
                  margin: const EdgeInsets.only(bottom: 6),
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    color: replyBg,
                    borderRadius: BorderRadius.circular(8),
                    border: Border(
                      right: BorderSide(color: replyBorder, width: 3),
                    ),
                  ),
                  child: Text(
                    (message['replyTo'] as Map)['text'] as String,
                    style: TextStyle(fontSize: 12, color: timeColor),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    textDirection: TextDirection.rtl,
                    textAlign: TextAlign.right,
                  ),
                ),
              ),

            if (uploadStatus == 'blocked_content') ...[
              if (!isImageFile) ...[
                const Center(child: _SystemContentWarningArtwork()),
                const SizedBox(height: 8),
              ],
            ] else if (isAudioFile)
              Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
                VoiceMessagePlayer(
                  url: fileUrl,
                  isMe: isMe,
                  senderAvatarUrl: senderAvatarUrl,
                  senderName: senderName,
                  initialDurationSeconds:
                      (message['audioDurationSeconds'] as num?)?.toDouble(),
                ),
                _AudioScanBadge(
                    transcript: message['audioTranscript']?.toString()),
              ])
            else if (isVideoFile)
              Stack(children: [
                if (kIsWeb)
                  NativeWebVideoPlayer(
                    key: ValueKey('video-$fileUrl'),
                    url: _absoluteMediaUrl(fileUrl),
                    onOptions: onMessageOptions == null
                        ? null
                        : () => onMessageOptions!(message),
                  )
                else
                  _ChatVideoPlayer(url: fileUrl),
                Positioned(
                  right: 7,
                  top: 7,
                  child: _ImageClassificationBadges(message: message),
                ),
                Positioned(
                  left: 7,
                  top: 7,
                  child: _ImageStatusBadge(message: message, isMe: isMe),
                ),
              ])
            else if (isImageFile)
              Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  GestureDetector(
                    onTap: () => Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (_) => ImagePreviewScreen(
                            url: fileUrl,
                            filename: fileName,
                            urls: conversationImages
                                .map((item) => item['fileUrl'] as String)
                                .toList(),
                            filenames: conversationImages
                                .map((item) => item['fileName'] as String?)
                                .toList(),
                            dates: conversationImages
                                .map((item) => _imageSentAtLabel(item))
                                .toList(),
                            messages: conversationImages,
                            onMessageOptions: onMessageOptions,
                            initialIndex: selectedImageIndex,
                          ),
                        )),
                    child: Stack(
                      children: [
                        ClipRRect(
                          borderRadius: BorderRadius.circular(10),
                          child: _PersistentMediaImage(
                            url: fileUrl,
                            width: 220,
                            height: 180,
                            fit: BoxFit.contain,
                            loadingBuilder: (_) => Container(
                              width: 220,
                              height: 180,
                              color: kBorder,
                              child: const Center(
                                  child: CircularProgressIndicator(
                                      color: kPrimary, strokeWidth: 2)),
                            ),
                            errorBuilder: (_) => Container(
                              width: 220,
                              height: 180,
                              color: kBorder,
                              child: const Icon(Icons.broken_image,
                                  color: kSubtext, size: 40),
                            ),
                          ),
                        ),
                        Positioned(
                          left: 7,
                          bottom: 7,
                          child:
                              _ImageStatusBadge(message: message, isMe: isMe),
                        ),
                        Positioned(
                          right: 7,
                          top: 7,
                          child: _ImageClassificationBadges(message: message),
                        ),
                        if (onMessageOptions != null)
                          Positioned(
                            left: 7,
                            top: 7,
                            child: _SmallImageOptionsButton(
                              onPressed: () => onMessageOptions!(message),
                            ),
                          ),
                      ],
                    ),
                  ),
                  if (displayText.trim().isNotEmpty &&
                      displayText.trim() != (fileName ?? '').trim()) ...[
                    const SizedBox(height: 8),
                    Text(
                      displayText,
                      style: const TextStyle(
                          fontSize: 14, height: 1.45, color: textColor),
                      textDirection: TextDirection.rtl,
                      textAlign: TextAlign.right,
                    ),
                  ],
                ],
              )
            else if (isFile)
              InkWell(
                onTap: fileUrl == null
                    ? null
                    : isPdfFile
                        ? () => onDocumentOpen != null
                            ? onDocumentOpen!(fileUrl, fileName, true)
                            : _openPdfInsideApp(context, fileUrl, fileName)
                        : isOfficeFile
                            ? () => onDocumentOpen != null
                                ? onDocumentOpen!(fileUrl, fileName, false)
                                : _openOfficeInsideApp(
                                    context, fileUrl, fileName, token)
                            : () =>
                                _downloadChatFile(context, fileUrl, fileName),
                borderRadius: BorderRadius.circular(8),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 4),
                  child: SizedBox(
                    width: 220,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        if (isPdfFile) ...[
                          _PdfFirstPagePreview(url: fileUrl),
                          const SizedBox(height: 7),
                        ] else if (isOfficeFile) ...[
                          _OfficeDocumentPreview(
                              fileUrl: fileUrl,
                              fileName: fileName ?? 'מסמך',
                              token: token),
                          const SizedBox(height: 7),
                        ],
                        Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Icon(
                                isPdfFile
                                    ? Icons.picture_as_pdf_outlined
                                    : isOfficeFile
                                        ? (fileName
                                                    ?.toLowerCase()
                                                    .endsWith('.xlsx') ==
                                                true
                                            ? Icons.table_chart_outlined
                                            : Icons.description_outlined)
                                        : isVideoFile
                                            ? Icons.videocam_outlined
                                            : Icons.insert_drive_file,
                                size: 20,
                                color: isPdfFile ? Colors.red : kPrimary),
                            const SizedBox(width: 6),
                            Expanded(
                              child: Tooltip(
                                message: fileName ??
                                    message['text'] as String? ??
                                    (isVideoFile ? 'סרטון וידאו' : 'מסמך'),
                                child: Text(
                                  fileName ??
                                      message['text'] as String? ??
                                      (isVideoFile ? 'סרטון וידאו' : 'מסמך'),
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style:
                                      TextStyle(fontSize: 14, color: textColor),
                                  textDirection: TextDirection.rtl,
                                ),
                              ),
                            ),
                            const SizedBox(width: 10),
                            if (isPdfFile || isOfficeFile)
                              IconButton(
                                visualDensity: VisualDensity.compact,
                                tooltip: 'הורדה',
                                onPressed: () => _downloadChatFile(
                                    context, fileUrl, fileName),
                                icon: const Icon(Icons.download_outlined,
                                    size: 20, color: kPrimary),
                              )
                            else ...[
                              const Icon(Icons.download,
                                  size: 20, color: kPrimary),
                              const SizedBox(width: 3),
                              const Text('הורדה',
                                  style: TextStyle(
                                      fontSize: 12,
                                      color: kPrimary,
                                      fontWeight: FontWeight.w600)),
                            ],
                          ],
                        ),
                      ],
                    ),
                  ),
                ),
              )
            else if (sharedContact != null)
              _SharedContactCard(
                sharedContact,
                token: token,
                me: me,
              )
            else
              Text(
                displayText,
                style: TextStyle(
                    fontSize: _looksLikeSticker(displayText) ? 44 : 14,
                    height: 1.45,
                    color: textColor),
                textDirection: TextDirection.rtl,
                textAlign: TextAlign.right,
              ),

            if (isFile && fileType == 'document') ...[
              const SizedBox(height: 6),
              _DocumentClassificationSummary(message: message),
            ],

            if (sharedUrl != null) ...[
              const SizedBox(height: 8),
              _WebsiteLinkPreview(sharedUrl, token),
            ],

            if (guideExternalUrls.length > 1) ...[
              const SizedBox(height: 7),
              Wrap(
                spacing: 6,
                runSpacing: 5,
                alignment: WrapAlignment.end,
                children: guideExternalUrls.indexed
                    .map((entry) => OutlinedButton.icon(
                          onPressed: () => launchUrl(Uri.parse(entry.$2),
                              mode: LaunchMode.externalApplication),
                          icon: const Icon(Icons.verified_outlined, size: 16),
                          label: Text('מקור ${entry.$1 + 1}'),
                        ))
                    .toList(),
              ),
            ],

            if (guideAppDestination != null) ...[
              const SizedBox(height: 8),
              Semantics(
                button: true,
                label: _guideAppLinkLabel(guideAppDestination,
                    issueId: guideIssueId),
                child: InkWell(
                  borderRadius: BorderRadius.circular(9),
                  onTap: () => _openGuideAppLink(
                      context, guideAppDestination, token, me,
                      issueId: guideIssueId),
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 11, vertical: 9),
                    decoration: BoxDecoration(
                      color: kPrimary.withValues(alpha: 0.08),
                      borderRadius: BorderRadius.circular(9),
                      border:
                          Border.all(color: kPrimary.withValues(alpha: 0.3)),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Icon(_guideAppLinkIcon(guideAppDestination),
                            size: 18, color: kPrimary),
                        const SizedBox(width: 7),
                        Text(
                          _guideAppLinkLabel(guideAppDestination,
                              issueId: guideIssueId),
                          style: const TextStyle(
                            color: kPrimary,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ],

            if (issueDraft != null) ...[
              const SizedBox(height: 8),
              _GuideIssueDraftCard(
                draft: issueDraft,
                token: token,
                messageId: message['id']?.toString() ?? '',
              ),
            ],

            // כרטיסיית קישור למודעה
            if (listingId != null) ...[
              const SizedBox(height: 6),
              _ListingMessageCard(
                listingId: listingId,
                token: token,
                me: me,
              ),
            ],

            const SizedBox(height: 3),
            Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (message['isEdited'] == true)
                  Text('נערך · ',
                      style: TextStyle(
                          fontSize: 10,
                          color: timeColor,
                          fontStyle: FontStyle.italic)),
                Text(
                  message['time'] as String? ?? '',
                  style: TextStyle(fontSize: 10, color: timeColor),
                ),
                if (!isImageFile) ...[
                  const SizedBox(width: 3),
                  _statusIcon(),
                ],
              ],
            ),
          ],
        ),
      ),
    );
  }
}

