  Future<void> _handleGroupMenuAction(String action) async {
    switch (action) {
      case 'info':
        await _showGroupDetailsPanel();
        break;
      case 'screenshot':
        await openAppScreenshot(context,
            token: widget.token,
            destination: AppScreenshotDestination.group(_groupId));
        break;
      case 'members':
        _showMembersDialog();
        break;
      case 'education':
        await _openEducationForms();
        break;
      case 'filter':
        await Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => ContentFilterSettingsScreen(
              token: widget.token,
              groupId: _groupId,
              groupName: widget.group['name'] as String?,
              groupPhotoUrl: widget.group['profile_pic_url'] as String?,
              groupMembers: _members,
              onAddGroupMember: _isAdmin ? _showAddMemberDialog : null,
              onManageGroupMembers: _showMembersDialog,
              onChangeGroupPhoto: _isAdmin ? _changeGroupPhoto : null,
            ),
          ),
        );
        await _loadGroupReceivingFilter();
        break;
      case 'search':
        _searchGroupMessages();
        break;
      case 'mute':
        final prefs = await SharedPreferences.getInstance();
        await prefs.setBool('muted_group_$_groupId', true);
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('התראות הקבוצה הושתקו')),
          );
        }
        break;
      case 'add':
        _showAddMemberDialog();
        break;
      case 'photo':
        _changeGroupPhoto();
        break;
      case 'delete':
        _deleteGroup();
        break;
      case 'report':
        await _showReportDialog(
          context: context,
          token: widget.token,
          targetType: 'group',
          targetId: _groupId,
          targetLabel: 'הקבוצה ${widget.group['name'] as String? ?? ''}',
        );
        break;
      case 'leave':
        _leaveGroup();
        break;
    }
  }

  Future<void> _openEducationForms() => Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => EducationFormsScreen(
            token: widget.token,
            groupId: _groupId,
            groupName: widget.group['name'] as String? ?? 'קבוצה',
            isAdmin: _isAdmin,
            socket: widget.socket,
          ),
        ),
      );

  Future<void> _openEducationAnnouncement(Map<String, dynamic> message) async {
    final directFormId = message['educationFormId']?.toString();
    if (directFormId != null && directFormId.isNotEmpty) {
      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => EducationFormDetailsScreen(
            token: widget.token,
            formId: directFormId,
            isAdmin: _isAdmin,
            socket: widget.socket,
          ),
        ),
      );
      if (mounted) await _loadMessages();
      return;
    }
    final text = message['text']?.toString() ?? '';
    final firstLine = text.split('\n').first;
    final separator = firstLine.indexOf(':');
    final title =
        separator == -1 ? '' : firstLine.substring(separator + 1).trim();
    if (title.isEmpty) {
      await _openEducationForms();
      return;
    }
    try {
      final response = await http.get(
        Uri.parse('$kApi/groups/$_groupId/education-forms'),
        headers: {'Authorization': 'Bearer ${widget.token}'},
      );
      if (response.statusCode != 200) throw Exception();
      final data = jsonDecode(response.body) as Map<String, dynamic>;
      final forms = (data['forms'] as List).cast<Map<String, dynamic>>();
      final matchIndex =
          forms.indexWhere((form) => form['title']?.toString().trim() == title);
      if (matchIndex == -1) throw Exception();
      if (!mounted) return;
      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => EducationFormDetailsScreen(
            token: widget.token,
            formId: forms[matchIndex]['id'] as String,
            isAdmin: _isAdmin,
            socket: widget.socket,
          ),
        ),
      );
      if (mounted) await _loadMessages();
    } catch (_) {
      if (mounted) await _openEducationForms();
    }
  }

  Future<void> _searchGroupMessages() async {
    final controller = TextEditingController();
    await showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          final query = controller.text.trim().toLowerCase();
          final matches = query.isEmpty
              ? <Map<String, dynamic>>[]
              : _messages
                  .where((m) => (m['text'] as String? ?? '')
                      .toLowerCase()
                      .contains(query))
                  .toList();
          return AlertDialog(
            title: const Text('חיפוש בהודעות הקבוצה'),
            content: SizedBox(
              width: 420,
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                TextField(
                  controller: controller,
                  autofocus: true,
                  textDirection: TextDirection.rtl,
                  decoration: const InputDecoration(
                    hintText: 'הקלד טקסט לחיפוש...',
                    prefixIcon: Icon(Icons.search),
                  ),
                  onChanged: (_) => setDialogState(() {}),
                ),
                const SizedBox(height: 12),
                ConstrainedBox(
                  constraints: const BoxConstraints(maxHeight: 300),
                  child: query.isEmpty
                      ? const Text('')
                      : matches.isEmpty
                          ? const Text('לא נמצאו הודעות')
                          : ListView.builder(
                              shrinkWrap: true,
                              itemCount: matches.length,
                              itemBuilder: (_, i) => ListTile(
                                dense: true,
                                title:
                                    Text(matches[i]['text'] as String? ?? ''),
                                subtitle: Text(
                                    matches[i]['senderName'] as String? ?? ''),
                                trailing:
                                    Text(matches[i]['time'] as String? ?? ''),
                              ),
                            ),
                ),
              ]),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('סגור'),
              )
            ],
          );
        },
      ),
    );
  }

  static const _groupFilterLabels = <String, String>{
    'text': 'הודעות טקסט',
    'video': 'סרטוני וידאו',
    'nonHumanImages': 'תמונות נוף או חפצים',
    'men': 'תמונות גברים',
    'women': 'תמונות נשים',
    'children': 'תמונות ילדים',
  };

  List<String> _blockedGroupFilterItems(Map<String, bool>? filter) =>
      _groupFilterLabels.entries
          .where((entry) => filter?[entry.key] == false)
          .map((entry) => entry.value)
          .toList();

  bool get _isSelfGroup {
    return widget.group['is_self'] == true;
  }

  Future<void> _showGroupFilterStatus() async {
    await _loadGroupReceivingFilter();
    if (!mounted) return;
    if (_groupReceivingFilter == null || _outgoingFilter == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('לא ניתן לטעון כעת את נתוני הסינון')),
      );
      return;
    }
    var groupDraft = Map<String, bool>.from(_groupReceivingFilter!);
    var personalDraft = Map<String, bool>.from(_outgoingFilter!);
    var groupDirty = false;
    var personalDirty = false;
    var saving = false;
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: Row(
            children: [
              const Icon(Icons.shield_outlined, color: kPrimary),
              const SizedBox(width: 9),
              Expanded(
                child: Text(
                  'מצב סינון הקבוצה — ${widget.group['name']?.toString() ?? 'קבוצה'}',
                  textAlign: TextAlign.right,
                ),
              ),
            ],
          ),
          content: SizedBox(
            width: 760,
            child: SingleChildScrollView(
              child: _InvitationFilterComparisonTable(
                groupName: widget.group['name']?.toString(),
                groupFilter: groupDraft,
                personalFilter: personalDraft,
                onCounterpartFilterChanged: _isAdmin
                    ? (updated) => setDialogState(() {
                          groupDraft = updated;
                          groupDirty = true;
                        })
                    : null,
                onPersonalFilterChanged: (updated) => setDialogState(() {
                  personalDraft = updated;
                  personalDirty = true;
                }),
              ),
            ),
          ),
          actions: [
            FilledButton.icon(
              onPressed: saving || (!groupDirty && !personalDirty)
                  ? null
                  : () async {
                      setDialogState(() => saving = true);
                      try {
                        if (groupDirty) {
                          final response = await http.put(
                            Uri.parse('$kApi/groups/$_groupId/filter-settings'),
                            headers: {
                              'Authorization': 'Bearer ${widget.token}',
                              'Content-Type': 'application/json',
                            },
                            body: jsonEncode({'filter': groupDraft}),
                          );
                          if (response.statusCode != 200) throw Exception();
                        }
                        if (personalDirty) {
                          final response = await http.put(
                            Uri.parse('$kApi/groups/$_groupId/personal-filter'),
                            headers: {
                              'Authorization': 'Bearer ${widget.token}',
                              'Content-Type': 'application/json',
                            },
                            body: jsonEncode({'filter': personalDraft}),
                          );
                          if (response.statusCode != 200) throw Exception();
                        }
                        if (!mounted) return;
                        setState(() {
                          _groupReceivingFilter = Map.from(groupDraft);
                          _outgoingFilter = Map.from(personalDraft);
                        });
                        if (personalDirty) {
                          await _saveAcceptedFilterNotice(personalDraft);
                        }
                        if (dialogContext.mounted) {
                          Navigator.pop(dialogContext);
                        }
                        if (mounted) {
                          ScaffoldMessenger.of(this.context).showSnackBar(
                            const SnackBar(
                                content: Text('הגדרות הסינון נשמרו')),
                          );
                        }
                      } catch (_) {
                        if (dialogContext.mounted) {
                          setDialogState(() => saving = false);
                        }
                        if (mounted) {
                          ScaffoldMessenger.of(this.context).showSnackBar(
                            const SnackBar(content: Text('שמירת הסינון נכשלה')),
                          );
                        }
                      }
                    },
              icon: saving
                  ? const SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white),
                    )
                  : const Icon(Icons.save_outlined, size: 18),
              label: const Text('שמור'),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('סגור'),
            ),
          ],
        ),
      ),
    );
  }

  Widget _groupFilterStatusButton() {
    final hasGroupRestrictions =
        _blockedGroupFilterItems(_groupReceivingFilter).isNotEmpty;
    final hasRestrictions = _isSelfGroup || _isAdmin
        ? hasGroupRestrictions
