              Text('$_total קבצים בבעלותך',
                  style: const TextStyle(fontWeight: FontWeight.bold)),
              const SizedBox(height: 8),
              Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    SizedBox(
                      width: 220,
                      child: TextField(
                        controller: _searchCtrl,
                        decoration: const InputDecoration(
                          labelText: 'שם הקובץ',
                          prefixIcon: Icon(Icons.search, size: 20),
                        ),
                        onChanged: (_) => _debouncedLoad(),
                      ),
                    ),
                    _filterDropdown(
                      label: 'סוג',
                      value: _type,
                      values: _filters,
                      onChanged: (value) {
                        setState(() => _type = value);
                        _load(reset: true);
                      },
                      width: 145,
                    ),
                    SizedBox(
                      width: 125,
                      child: TextField(
                        controller: _minSizeCtrl,
                        keyboardType: TextInputType.number,
                        decoration:
                            const InputDecoration(labelText: 'גודל מ־MB'),
                        onChanged: (_) => _debouncedLoad(),
                      ),
                    ),
                    SizedBox(
                      width: 125,
                      child: TextField(
                        controller: _maxSizeCtrl,
                        keyboardType: TextInputType.number,
                        decoration:
                            const InputDecoration(labelText: 'גודל עד MB'),
                        onChanged: (_) => _debouncedLoad(),
                      ),
                    ),
                    OutlinedButton.icon(
                      onPressed: () => _pickFilterDate(from: true),
