class _AdminOpenIssuesView extends StatefulWidget {
  final String token;
  final String perm;
  const _AdminOpenIssuesView({required this.token, required this.perm});

  @override
  State<_AdminOpenIssuesView> createState() => _AdminOpenIssuesViewState();
}

class _AdminOpenIssuesViewState extends State<_AdminOpenIssuesView> {
  List<Map<String, dynamic>> _issues = [];
  bool _loading = true;
  String _filter = 'all';

  static const _statusLabels = {
    'received': 'התקבל',
    'reviewing': 'בבדיקה',
    'needs_info': 'נדרש מידע',
    'resolved': 'טופל',
    'closed': 'נסגר',
  };

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final response = await http.get(
      Uri.parse('$kApi/admin/support-issues?status=$_filter'),
      headers: {'Authorization': 'Bearer ${widget.token}'},
    );
    if (!mounted) return;
    setState(() {
      _issues = response.statusCode == 200
          ? (jsonDecode(response.body) as List).cast<Map<String, dynamic>>()
          : [];
      _loading = false;
    });
  }

  Future<void> _handle(Map<String, dynamic> issue) async {
    var selectedStatus = issue['status']?.toString() ?? 'reviewing';
    final controller = TextEditingController(
        text: issue['developer_response']?.toString() ?? '');
    final result = await showDialog<Map<String, String>>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (_, setDialogState) => AlertDialog(
          title: const Text('טיפול בפנייה'),
          content: SizedBox(
            width: 520,
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              DropdownButtonFormField<String>(
                initialValue: selectedStatus,
                decoration: const InputDecoration(labelText: 'מצב'),
                items: _statusLabels.entries
                    .map((entry) => DropdownMenuItem(
                        value: entry.key, child: Text(entry.value)))
                    .toList(),
                onChanged: (value) {
                  if (value != null) {
                    setDialogState(() => selectedStatus = value);
                  }
                },
              ),
              const SizedBox(height: 12),
              TextField(
                controller: controller,
                minLines: 4,
                maxLines: 8,
                maxLength: 2000,
                textDirection: TextDirection.rtl,
                decoration: const InputDecoration(
                  labelText: 'תשובה למשתמש',
                  helperText: 'תגובה תישלח למשתמש כהודעה משירות ה-AI',
                ),
              ),
            ]),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('ביטול')),
            FilledButton(
              onPressed: () => Navigator.pop(dialogContext, {
                'status': selectedStatus,
                'response': controller.text.trim(),
              }),
              child: const Text('שמור ועדכן'),
            ),
          ],
        ),
      ),
    );
    controller.dispose();
    if (result == null) return;
    final response = await http.patch(
      Uri.parse('$kApi/admin/support-issues/${issue['id']}'),
      headers: {
        'Authorization': 'Bearer ${widget.token}',
        'Content-Type': 'application/json',
      },
      body: jsonEncode(result),
    );
    if (!mounted) return;
    final message = response.statusCode == 200
        ? 'הפנייה עודכנה והמשתמש יקבל הודעה'
        : (jsonDecode(response.body)['error']?.toString() ?? 'העדכון נכשל');
    ScaffoldMessenger.of(context)
        .showSnackBar(SnackBar(content: Text(message)));
    if (response.statusCode == 200) await _load();
  }

  @override
  Widget build(BuildContext context) {
    return Column(children: [
      Padding(
        padding: const EdgeInsets.all(10),
        child: DropdownButtonFormField<String>(
          initialValue: _filter,
          decoration: const InputDecoration(labelText: 'סינון מצב'),
          items: {'all': 'הכול', ..._statusLabels}
              .entries
              .map((entry) =>
                  DropdownMenuItem(value: entry.key, child: Text(entry.value)))
              .toList(),
          onChanged: (value) {
            if (value == null) return;
            setState(() {
              _filter = value;
              _loading = true;
            });
            _load();
          },
        ),
      ),
      Expanded(
        child: _loading
            ? const Center(child: CircularProgressIndicator())
            : _issues.isEmpty
                ? const Center(child: Text('אין פניות במצב שנבחר'))
                : RefreshIndicator(
                    onRefresh: _load,
                    child: ListView.builder(
                      padding: const EdgeInsets.all(10),
                      itemCount: _issues.length,
                      itemBuilder: (_, index) {
                        final issue = _issues[index];
                        return Card(
                          child: ExpansionTile(
                            leading: Icon(issue['issue_type'] == 'bug'
                                ? Icons.bug_report_outlined
                                : Icons.lightbulb_outline),
                            title:
                                Text(issue['user_name']?.toString() ?? 'משתמש'),
                            subtitle: Text(
                                '${issue['issue_type'] == 'bug' ? 'תקלה' : 'הצעה'} • ${_statusLabels[issue['status']] ?? issue['status']}'),
                            childrenPadding:
                                const EdgeInsets.fromLTRB(16, 0, 16, 14),
                            children: [
                              Align(
                                  alignment: Alignment.centerRight,
                                  child: SelectableText(
                                      issue['description']?.toString() ?? '')),
                              if ((issue['attachments'] as List? ?? const [])
                                  .isNotEmpty) ...[
                                const Divider(),
                                Align(
                                  alignment: Alignment.centerRight,
                                  child: Wrap(
                                    spacing: 8,
                                    runSpacing: 8,
                                    children: (issue['attachments'] as List)
                                        .whereType<Map>()
                                        .map((attachment) => ActionChip(
                                              avatar: const Icon(
                                                  Icons.attach_file,
                                                  size: 17),
                                              label: Text(attachment['name']
                                                      ?.toString() ??
                                                  'קובץ'),
                                              onPressed: () => launchUrl(
                                                  Uri.parse(_absoluteMediaUrl(
                                                      attachment['url']
                                                              ?.toString() ??
                                                          '')),
                                                  mode: LaunchMode
                                                      .externalApplication),
                                            ))
                                        .toList(),
                                  ),
                                ),
                              ],
                              if ((issue['user_update']?.toString() ?? '')
                                  .isNotEmpty) ...[
                                const Divider(),
                                Align(
                                    alignment: Alignment.centerRight,
                                    child: Text(
                                        'מידע נוסף:\n${issue['user_update']}')),
                              ],
                              if (widget.perm == 'edit')
                                Align(
                                  alignment: Alignment.centerLeft,
                                  child: FilledButton.icon(
                                    onPressed: () => _handle(issue),
                                    icon: const Icon(Icons.edit_note),
                                    label: const Text('טפל בפנייה'),
                                  ),
                                ),
                            ],
                          ),
                        );
                      },
                    ),
                  ),
      ),
    ]);
  }
}

class _ModerationUsersView extends StatefulWidget {
  final String token;
  final String perm;
  const _ModerationUsersView({required this.token, required this.perm});
  @override
  State<_ModerationUsersView> createState() => _ModerationUsersViewState();
}

class _ModerationUsersViewState extends State<_ModerationUsersView> {
  List<Map<String, dynamic>> _users = [];
  bool _loading = true;
  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final response = await http.get(Uri.parse('$kApi/admin/moderation/users'),
        headers: {'Authorization': 'Bearer ${widget.token}'});
    if (!mounted) return;
    setState(() {
      _users = response.statusCode == 200
          ? (jsonDecode(response.body) as List).cast<Map<String, dynamic>>()
          : [];
      _loading = false;
    });
  }

  Future<void> _act(Map<String, dynamic> user, String action) async {
    final controller = TextEditingController();
    final reason = await showDialog<String>(
        context: context,
        builder: (dialogContext) => AlertDialog(
              title: Text(action == 'block'
                  ? 'חסימה לצמיתות'
                  : action == 'suspend'
                      ? 'השעיה זמנית'
                      : action == 'warn'
                          ? 'שליחת אזהרה'
                          : 'הסרת חסימה'),
              content: TextField(
                  controller: controller,
                  autofocus: true,
                  maxLines: 3,
                  decoration:
                      const InputDecoration(labelText: 'סיבה והערת מנהל')),
              actions: [
                TextButton(
                    onPressed: () => Navigator.pop(dialogContext),
                    child: const Text('ביטול')),
                FilledButton(
                    onPressed: () {
                      if (controller.text.trim().isNotEmpty) {
                        Navigator.pop(dialogContext, controller.text.trim());
                      }
                    },
                    child: const Text('אישור'))
              ],
            ));
    controller.dispose();
    if (reason == null) return;
    final response = await http.post(
        Uri.parse('$kApi/admin/moderation/users/${user['id']}/action'),
        headers: {
          'Authorization': 'Bearer ${widget.token}',
          'Content-Type': 'application/json'
        },
        body: jsonEncode(
            {'action': action, 'reason': reason, 'durationHours': 24}));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(
            response.statusCode == 200 ? 'הפעולה נשמרה' : 'הפעולה נכשלה')));
    await _load();
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return const Center(child: CircularProgressIndicator());
    if (_users.isEmpty) {
      return const Center(child: Text('אין אירועי חסימה שנשמרו'));
    }
    return RefreshIndicator(
        onRefresh: _load,
        child: ListView.builder(
          padding: const EdgeInsets.all(12),
          itemCount: _users.length,
          itemBuilder: (_, index) {
            final user = _users[index];
            return Card(
                child: ExpansionTile(
              leading: const Icon(Icons.gpp_maybe_outlined, color: Colors.red),
              title: Text(user['name']?.toString() ?? 'משתמש'),
              subtitle: Text(
                  '${user['incident_count']} אירועים • ${user['recent_count']} ב־30 יום • מצב: ${user['moderation_state']}'),
              children: [
                if (user['email'] != null)
                  SelectableText(user['email'].toString()),
                if (user['moderation_reason'] != null)
                  Padding(
                      padding: const EdgeInsets.all(8),
                      child: Text('סיבה: ${user['moderation_reason']}')),
                if (widget.perm == 'edit')
                  Wrap(spacing: 6, children: [
                    TextButton(
                        onPressed: () => _act(user, 'warn'),
                        child: const Text('אזהרה')),
                    TextButton(
                        onPressed: () => _act(user, 'suspend'),
                        child: const Text('השעיה ל־24 שעות')),
                    TextButton(
                        onPressed: () => _act(user, 'block'),
                        child: const Text('חסימה לצמיתות')),
                    TextButton(
                        onPressed: () => _act(user, 'unblock'),
                        child: const Text('ביטול חסימה')),
                  ]),
              ],
            ));
          },
        ));
  }
}

class _TablesView extends StatelessWidget {
  final String token;
  final String perm;
  final List<Map<String, dynamic>> tables;
  final bool loading;
  final VoidCallback onRefresh;
  const _TablesView(
      {required this.token,
      required this.perm,
      required this.tables,
      required this.loading,
      required this.onRefresh});

  @override
  Widget build(BuildContext context) {
    if (loading) return const Center(child: CircularProgressIndicator());
    if (tables.isEmpty) {
      return const Center(child: Text('שגיאה בטעינת הנתונים'));
    }
    return RefreshIndicator(
      onRefresh: () async => onRefresh(),
      child: ListView.separated(
        padding: const EdgeInsets.all(12),
        itemCount: tables.length,
        separatorBuilder: (_, __) => const SizedBox(height: 8),
        itemBuilder: (ctx, i) {
          final t = tables[i];
          return Card(
            elevation: 0,
            color: kCard,
            shape:
                RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
            child: ListTile(
              leading: CircleAvatar(
                backgroundColor: kPrimaryMid.withValues(alpha: 0.15),
                child: Text('${t['count']}',
                    style: const TextStyle(
                        color: kPrimary,
                        fontWeight: FontWeight.bold,
                        fontSize: 13)),
              ),
              title: Text(t['label'] as String,
                  style: const TextStyle(fontWeight: FontWeight.w600)),
